import Database from 'better-sqlite3';
import fs from 'node:fs';
import path from 'node:path';

export type DB = Database.Database;

// Timestamps are stored as integer epoch milliseconds; DTOs convert to ISO strings.
const MIGRATIONS: string[] = [
  `
  CREATE TABLE users (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE COLLATE NOCASE,
    name TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('admin','member')),
    disabled INTEGER NOT NULL DEFAULT 0,
    daily_tokens INTEGER,
    allowed_models TEXT,
    allowed_modes TEXT,
    failed_logins INTEGER NOT NULL DEFAULT 0,
    locked_until INTEGER,
    created_at INTEGER NOT NULL,
    last_seen_at INTEGER
  );
  CREATE TABLE sessions (
    id TEXT PRIMARY KEY,               -- HMAC(secret, token)
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    ip TEXT,
    user_agent TEXT
  );
  CREATE INDEX sessions_user ON sessions(user_id);
  CREATE TABLE projects (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    color TEXT NOT NULL,
    icon TEXT NOT NULL,
    preview_port INTEGER NOT NULL UNIQUE,
    preview_command TEXT,
    preview_strip INTEGER NOT NULL DEFAULT 0,
    links TEXT NOT NULL DEFAULT '[]',
    created_by TEXT,
    created_at INTEGER NOT NULL,
    last_active_at INTEGER,
    archived INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE project_members (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role TEXT NOT NULL CHECK (role IN ('owner','editor','viewer')),
    created_at INTEGER NOT NULL,
    PRIMARY KEY (project_id, user_id)
  );
  CREATE INDEX project_members_user ON project_members(user_id);
  CREATE TABLE conversations (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    claude_session_id TEXT,
    model TEXT NOT NULL,
    mode TEXT NOT NULL,
    created_by TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
  );
  CREATE INDEX conversations_project ON conversations(project_id, updated_at);
  CREATE TABLE runs (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    project_id TEXT NOT NULL,
    user_id TEXT,
    status TEXT NOT NULL CHECK (status IN ('queued','running','done','error','aborted')),
    model TEXT NOT NULL,
    mode TEXT NOT NULL,
    thinking TEXT NOT NULL DEFAULT 'normal',
    started_at INTEGER NOT NULL,
    ended_at INTEGER,
    input_tokens INTEGER NOT NULL DEFAULT 0,
    output_tokens INTEGER NOT NULL DEFAULT 0,
    cache_read INTEGER NOT NULL DEFAULT 0,
    cache_write INTEGER NOT NULL DEFAULT 0,
    cost_usd REAL NOT NULL DEFAULT 0,
    duration_ms INTEGER,
    ip TEXT,
    upstream_seq INTEGER NOT NULL DEFAULT 0,
    error TEXT
  );
  CREATE INDEX runs_conv ON runs(conversation_id);
  CREATE INDEX runs_user_started ON runs(user_id, started_at);
  CREATE INDEX runs_started ON runs(started_at);
  CREATE INDEX runs_status ON runs(status);
  CREATE INDEX runs_project ON runs(project_id, started_at);
  CREATE TABLE messages (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    role TEXT NOT NULL CHECK (role IN ('user','assistant')),
    content TEXT NOT NULL DEFAULT '',
    attachments TEXT NOT NULL DEFAULT '[]',
    suggestions TEXT,
    run_id TEXT,
    user_id TEXT,
    created_at INTEGER NOT NULL
  );
  CREATE INDEX messages_conv ON messages(conversation_id, created_at);
  CREATE INDEX messages_run ON messages(run_id);
  CREATE TABLE run_events (
    run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
    seq INTEGER NOT NULL,
    type TEXT NOT NULL,
    data TEXT NOT NULL,
    ts INTEGER NOT NULL,
    PRIMARY KEY (run_id, seq)
  ) WITHOUT ROWID;
  CREATE TABLE uploads (
    id TEXT PRIMARY KEY,
    user_id TEXT,
    project_id TEXT,
    filename TEXT NOT NULL,
    mime TEXT NOT NULL,
    size INTEGER NOT NULL,
    path TEXT NOT NULL,
    has_thumb INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL
  );
  CREATE TABLE audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id TEXT,
    ip TEXT,
    action TEXT NOT NULL,
    target TEXT,
    meta TEXT,
    ts INTEGER NOT NULL
  );
  CREATE INDEX audit_ts ON audit_log(ts);
  CREATE INDEX audit_action ON audit_log(action, ts);
  CREATE TABLE request_log (
    ts INTEGER NOT NULL,
    ip TEXT,
    user_id TEXT,
    method TEXT NOT NULL,
    path TEXT NOT NULL,
    status INTEGER NOT NULL,
    ms REAL NOT NULL
  );
  CREATE INDEX request_log_ts ON request_log(ts);
  CREATE TABLE ip_rules (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL CHECK (kind IN ('allow','block')),
    cidr TEXT NOT NULL,
    note TEXT,
    created_by TEXT,
    created_at INTEGER NOT NULL
  );
  CREATE TABLE settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
  );
  `,
  // v2: context meter + manual compaction, custom subagents
  `
  ALTER TABLE conversations ADD COLUMN context_tokens INTEGER;
  ALTER TABLE conversations ADD COLUMN agent_slug TEXT;
  ALTER TABLE messages ADD COLUMN kind TEXT;
  CREATE TABLE agents (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    prompt TEXT NOT NULL,
    tools TEXT,                          -- JSON string[]; NULL = inherit all tools
    model TEXT NOT NULL DEFAULT 'inherit' CHECK (model IN ('inherit','haiku','sonnet','opus')),
    scope TEXT NOT NULL CHECK (scope IN ('global','project')),
    project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,
    enabled INTEGER NOT NULL DEFAULT 1,
    builtin INTEGER NOT NULL DEFAULT 0,
    created_by TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    CHECK ((scope = 'global' AND project_id IS NULL) OR (scope = 'project' AND project_id IS NOT NULL))
  );
  CREATE UNIQUE INDEX agents_global_slug ON agents(slug) WHERE scope = 'global';
  CREATE UNIQUE INDEX agents_project_slug ON agents(project_id, slug) WHERE scope = 'project';
  `,
  // v3: the CLI reports total_cost_usd cumulatively per session; keep that raw value and store per-run deltas.
  `
  ALTER TABLE runs ADD COLUMN session_cost_usd REAL;
  UPDATE runs SET session_cost_usd = cost_usd WHERE cost_usd > 0;
  UPDATE runs SET cost_usd = (
    SELECT CASE WHEN runs.session_cost_usd >= p.prev THEN runs.session_cost_usd - p.prev ELSE runs.session_cost_usd END
    FROM (SELECT COALESCE(MAX(r2.session_cost_usd), 0) AS prev FROM runs r2
          WHERE r2.conversation_id = runs.conversation_id AND r2.started_at < runs.started_at) p
  ) WHERE session_cost_usd > 0;
  `,
];

export function openDb(dbPath: string): DB {
  if (dbPath !== ':memory:') fs.mkdirSync(path.dirname(dbPath), { recursive: true });
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('synchronous = NORMAL');
  db.pragma('foreign_keys = ON');
  db.pragma('busy_timeout = 5000');
  migrate(db);
  return db;
}

function migrate(db: DB) {
  const current = db.pragma('user_version', { simple: true }) as number;
  for (let v = current; v < MIGRATIONS.length; v++) {
    db.transaction(() => {
      db.exec(MIGRATIONS[v]!);
      db.pragma(`user_version = ${v + 1}`);
    })();
  }
}

export const now = () => Date.now();
export const iso = (ms: number | null | undefined): string | null => (ms == null ? null : new Date(ms).toISOString());
export function parseJson<T>(s: string | null | undefined, fallback: T): T {
  if (s == null) return fallback;
  try {
    return JSON.parse(s) as T;
  } catch {
    return fallback;
  }
}

import argon2 from 'argon2';
import crypto from 'node:crypto';
import type { FastifyReply, FastifyRequest } from 'fastify';
