export const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
const COLORS = ['#ff3e8a', '#ff6fae', '#ff8a5c', '#b14bff', '#3dffb5', '#ffc857', '#5ce1ff', '#ff4d6d'];

const colorSchema = z.string().regex(/^#[0-9a-fA-F]{6}$/, 'color must be #rrggbb');
const iconSchema = z.string().trim().regex(/^[a-z0-9-]{1,40}$/, 'icon must be a lucide icon name');
const createSchema = z.object({
  name: z.string().trim().min(1).max(80),
  description: z.string().max(2000).optional().default(''),
  color: colorSchema.optional(),
  icon: iconSchema.optional(),
  slug: z.string().trim().regex(SLUG_RE).optional(),
  previewCommand: z.string().max(500).nullable().optional(),
  previewStrip: z.boolean().optional(),
  links: z.array(z.string().max(64)).max(50).optional(),
});
const patchSchema = z.object({
  name: z.string().trim().min(1).max(80).optional(),
  description: z.string().max(2000).optional(),
  color: colorSchema.optional(),
  icon: iconSchema.optional(),
  previewCommand: z.string().max(500).nullable().optional(),
  previewStrip: z.boolean().optional(),
  links: z.array(z.string().max(64)).max(50).optional(),
  archived: z.boolean().optional(),
});
const membersSchema = z.object({
  members: z
    .array(
      z.object({
        userId: z.string().optional(),
        email: z.string().optional(),
        role: z.enum(['owner', 'editor', 'viewer']),
      }),
    )
    .max(500),
});

export function slugify(name: string): string {
  const s = name
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
    .replace(/-+$/g, '');
  return s && SLUG_RE.test(s) ? s : `project-${crypto.randomBytes(3).toString('hex')}`;
}

export function uniqueSlug(ctx: Ctx, base: string): string {
  const exists = (s: string) =>
    !!ctx.db.prepare(`SELECT 1 FROM projects WHERE slug = ?`).get(s) || fs.existsSync(path.join(ctx.cfg.projectsDir, s));
  if (!exists(base)) return base;
  for (let i = 2; i < 1000; i++) {
    const s = `${base.slice(0, 44)}-${i}`;
    if (!exists(s)) return s;
  }
  return `${base.slice(0, 40)}-${crypto.randomBytes(3).toString('hex')}`;
}

export function allocatePort(ctx: Ctx): number {
  const used = new Set((ctx.db.prepare(`SELECT preview_port FROM projects`).all() as { preview_port: number }[]).map((r) => r.preview_port));
  for (let p = ctx.cfg.previewPortMin; p <= ctx.cfg.previewPortMax; p++) if (!used.has(p)) return p;
  throw conflict('No free preview ports left (all 100 are allocated). Delete a project first.', 'no_ports');
}

function starterReadme(name: string, description: string, slug: string, port: number) {
  return `# ${name}\n\n${description || 'A new Nxeon Workspace project.'}\n\n## Workspace\n\n- Directory: \`/workspace/projects/${slug}\`\n- Preview port: \`${port}\` (served at \`/preview/${slug}/\`)\n\nAsk Claude to scaffold the app — it will keep this README up to date.\n`;
}

/** Projects visible to the user (admins: all). */
export function visibleProjects(ctx: Ctx, user: UserRow, includeArchived: boolean): { p: ProjectRow; role: EffectiveRole }[] {
  const arch = includeArchived ? '' : 'AND p.archived = 0';
  if (user.role === 'admin') {
    return (ctx.db.prepare(`SELECT p.* FROM projects p WHERE 1=1 ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`).all() as ProjectRow[]).map(
      (p) => ({ p, role: 'admin' as const }),
    );
  }
  return (
    ctx.db
      .prepare(
        `SELECT p.*, m.role AS member_role FROM projects p JOIN project_members m ON m.project_id = p.id AND m.user_id = ?
         WHERE 1=1 ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`,
      )
      .all(user.id) as (ProjectRow & { member_role: ProjectRole })[]
  ).map((p) => ({ p, role: p.member_role }));
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cfg } = ctx;

    app.get('/api/projects', async (req) => {
      const u = requireUser(req);
      const q = req.query as { archived?: string };
      return visibleProjects(ctx, u, q.archived === '1' || q.archived === 'true').map(({ p, role }) => projectDTO(p, role));
    });

    app.post('/api/projects', async (req, reply) => {
      const u = requireUser(req);
      const body = createSchema.parse(req.body);
      const t = now();
      const id = crypto.randomUUID();
      let created: ProjectRow | undefined;
      // allocate slug + port inside a transaction to avoid races
      db.transaction(() => {
        const slug = body.slug ? uniqueSlug(ctx, body.slug) : uniqueSlug(ctx, slugify(body.name));
        const port = allocatePort(ctx);
        const color = body.color ?? COLORS[Math.floor(Math.random() * COLORS.length)]!;
        db.prepare(
          `INSERT INTO projects(id, slug, name, description, color, icon, preview_port, preview_command, preview_strip, links, created_by, created_at, last_active_at)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        ).run(id, slug, body.name, body.description, color, body.icon ?? 'box', port, body.previewCommand ?? null, body.previewStrip ? 1 : 0,
          JSON.stringify(body.links ?? []), u.id, t, t);
        db.prepare(`INSERT INTO project_members(project_id, user_id, role, created_at) VALUES (?,?, 'owner', ?)`).run(id, u.id, t);
        created = db.prepare(`SELECT * FROM projects WHERE id = ?`).get(id) as ProjectRow;
      })();
      const p = created!;
      const dir = path.join(cfg.projectsDir, p.slug);
      fs.mkdirSync(dir, { recursive: true });
      const readme = path.join(dir, 'README.md');
      if (!fs.existsSync(readme)) fs.writeFileSync(readme, starterReadme(p.name, p.description, p.slug, p.preview_port));
      ctx.audit(req, 'project_create', p.id, { slug: p.slug, name: p.name });
      ctx.hub.invalidatePermissions();
      reply.code(201);
      return projectDTO(p, u.role === 'admin' ? 'admin' : 'owner');
    });

    app.get('/api/projects/graph', async (req) => {
      const u = requireUser(req);
      const projects = visibleProjects(ctx, u, false);
      const ids = projects.map(({ p }) => p.id);
      const running = new Set<string>();
      const lastStatus = new Map<string, string>();
      if (ids.length) {
        const ph = ids.map(() => '?').join(',');
        for (const r of db
          .prepare(`SELECT DISTINCT project_id FROM runs WHERE status IN ('queued','running') AND project_id IN (${ph})`)
          .all(...ids) as { project_id: string }[])
          running.add(r.project_id);
        for (const r of db
          .prepare(
            `SELECT r.project_id, r.status FROM runs r JOIN (SELECT project_id, MAX(started_at) AS m FROM runs WHERE project_id IN (${ph}) GROUP BY project_id) x
             ON x.project_id = r.project_id AND x.m = r.started_at`,
          )
          .all(...ids) as { project_id: string; status: string }[])
          lastStatus.set(r.project_id, r.status);
      }
      const t = now();
      const nodes: Record<string, unknown>[] = [{ id: 'core', name: 'Nxeon Core', color: '#ff3e8a', icon: 'cpu', status: running.size ? 'running' : 'idle', activity: running.size ? 1 : 0.3, lastActiveAt: null }];
      for (const { p } of projects) {
        const last = p.last_active_at ?? p.created_at;
        const ageH = (t - last) / 3600_000;
        const isRunning = running.has(p.id);
        nodes.push({
          id: p.id, slug: p.slug, name: p.name, color: p.color, icon: p.icon,
          status: isRunning ? 'running' : lastStatus.get(p.id) === 'error' ? 'error' : 'idle',
          activity: isRunning ? 1 : Math.round(Math.exp(-ageH / 24) * 100) / 100,
          lastActiveAt: iso(last),
        });
      }
      const links: { source: string; target: string; kind: string }[] = ids.map((id) => ({ source: 'core', target: id, kind: 'core' }));
      const idSet = new Set(ids);
      const seen = new Set<string>();
      const key = (a: string, b: string) => (a < b ? `${a}|${b}` : `${b}|${a}`);
      for (const { p } of projects) {
        for (const other of parseJson<string[]>(p.links, [])) {
          if (!idSet.has(other) || other === p.id || seen.has(key(p.id, other))) continue;
          seen.add(key(p.id, other));
          links.push({ source: p.id, target: other, kind: 'link' });
        }
      }
      // shared-member affinity: keep each node's 2 strongest (Jaccard) neighbours
      if (ids.length > 1) {
        const ph = ids.map(() => '?').join(',');
        const members = new Map<string, Set<string>>();
        for (const r of db.prepare(`SELECT project_id, user_id FROM project_members WHERE project_id IN (${ph})`).all(...ids) as {
          project_id: string; user_id: string;
        }[]) {
          let s = members.get(r.project_id);
          if (!s) members.set(r.project_id, (s = new Set()));
          s.add(r.user_id);
        }
        const best = new Map<string, { other: string; score: number }[]>();
        for (let i = 0; i < ids.length; i++)
          for (let j = i + 1; j < ids.length; j++) {
            const a = members.get(ids[i]!) ?? new Set<string>();
            const b = members.get(ids[j]!) ?? new Set<string>();
            let inter = 0;
            for (const x of a) if (b.has(x)) inter++;
            if (!inter) continue;
            const score = inter / (a.size + b.size - inter);
            for (const [x, y] of [[ids[i]!, ids[j]!], [ids[j]!, ids[i]!]] as const) {
              const l = best.get(x) ?? [];
              l.push({ other: y, score });
              best.set(x, l);
            }
          }
        for (const [id, l] of best) {
          l.sort((a, b) => b.score - a.score);
          for (const { other } of l.slice(0, 2)) {
            const k = key(id, other);
            if (seen.has(k)) continue;
            seen.add(k);
            links.push({ source: id, target: other, kind: 'affinity' });
          }
        }
      }
      return { nodes, links };
    });

    app.get('/api/projects/:id', async (req) => {
      const u = requireUser(req);
      const { project, role } = requireProject(db, u, (req.params as { id: string }).id, 'viewer');
      return projectDTO(project, role);
    });

    app.patch('/api/projects/:id', async (req) => {
      const u = requireUser(req);
      const body = patchSchema.parse(req.body);
      const ownerFields = body.archived !== undefined;
      const { project, role } = requireProject(db, u, (req.params as { id: string }).id, ownerFields ? 'owner' : 'editor');
      const sets: string[] = [];
      const vals: unknown[] = [];
      const add = (col: string, v: unknown) => {
        sets.push(`${col} = ?`);
        vals.push(v);
      };
      if (body.name !== undefined) add('name', body.name);
      if (body.description !== undefined) add('description', body.description);
      if (body.color !== undefined) add('color', body.color);
      if (body.icon !== undefined) add('icon', body.icon);
      if (body.previewCommand !== undefined) add('preview_command', body.previewCommand || null);
      if (body.previewStrip !== undefined) add('preview_strip', body.previewStrip ? 1 : 0);
      if (body.links !== undefined) add('links', JSON.stringify([...new Set(body.links.filter((l) => l !== project.id))]));
      if (body.archived !== undefined) add('archived', body.archived ? 1 : 0);
      if (sets.length) db.prepare(`UPDATE projects SET ${sets.join(', ')} WHERE id = ?`).run(...vals, project.id);
      ctx.audit(req, 'project_update', project.id, body);
      const p = db.prepare(`SELECT * FROM projects WHERE id = ?`).get(project.id) as ProjectRow;
      return projectDTO(p, role);
    });

    app.delete('/api/projects/:id', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'owner');
      const active = db.prepare(`SELECT id FROM runs WHERE project_id = ? AND status IN ('queued','running')`).all(project.id) as { id: string }[];
      for (const r of active) await ctx.runs.abort(r.id);
      try {
        await ctx.cb.previewStop(project.slug);
      } catch {
        /* claudebox may be down; ignore */
      }
      ctx.watchers.stop(project.id);
      db.transaction(() => {
        db.prepare(`DELETE FROM run_events WHERE run_id IN (SELECT id FROM runs WHERE project_id = ?)`).run(project.id);
        db.prepare(`DELETE FROM projects WHERE id = ?`).run(project.id);
      })();
      // Keep files recoverable: move the directory into a hidden trash folder.
      const dir = path.join(cfg.projectsDir, project.slug);
      if (fs.existsSync(dir)) {
        const trash = path.join(cfg.projectsDir, '.trash');
        fs.mkdirSync(trash, { recursive: true });
        try {
          fs.renameSync(dir, path.join(trash, `${project.slug}-${Date.now()}`));
        } catch (err) {
          ctx.log.warn({ err: (err as Error).message }, 'failed to move project dir to trash');
        }
      }
      ctx.audit(req, 'project_delete', project.id, { slug: project.slug, name: project.name });
      ctx.hub.invalidatePermissions();
      return { ok: true };
    });

    app.get('/api/projects/:id/members', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'viewer');
      return db
        .prepare(
          `SELECT m.user_id AS userId, u.name, u.email, m.role FROM project_members m JOIN users u ON u.id = m.user_id
           WHERE m.project_id = ? ORDER BY CASE m.role WHEN 'owner' THEN 0 WHEN 'editor' THEN 1 ELSE 2 END, u.name`,
        )
        .all(project.id);
    });

    app.put('/api/projects/:id/members', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'owner');
      const { members } = membersSchema.parse(req.body);
      const resolved = new Map<string, ProjectRole>();
      for (const m of members) {
        let uid = m.userId;
        if (!uid && m.email) uid = (db.prepare(`SELECT id FROM users WHERE email = ?`).get(m.email.toLowerCase()) as { id: string } | undefined)?.id;
        if (!uid || !db.prepare(`SELECT 1 FROM users WHERE id = ?`).get(uid)) throw badRequest(`Unknown user ${m.userId ?? m.email}`, 'unknown_user');
        resolved.set(uid, m.role);
      }
      if (![...resolved.values()].includes('owner')) throw new HttpError(400, 'no_owner', 'A project needs at least one owner');
      const t = now();
      db.transaction(() => {
        db.prepare(`DELETE FROM project_members WHERE project_id = ?`).run(project.id);
        const ins = db.prepare(`INSERT INTO project_members(project_id, user_id, role, created_at) VALUES (?,?,?,?)`);
        for (const [uid, role] of resolved) ins.run(project.id, uid, role, t);
      })();
      ctx.audit(req, 'project_members', project.id, Object.fromEntries(resolved));
      ctx.hub.invalidatePermissions();
      return db
        .prepare(`SELECT m.user_id AS userId, u.name, u.email, m.role FROM project_members m JOIN users u ON u.id = m.user_id WHERE m.project_id = ?`)
        .all(project.id);
    });
  };

import type { WebSocket } from 'ws';
import type { DB } from './db.js';
import { projectRole, type UserRow } from './auth.js';
import type { ServerMsg } from './shared/protocol.js';

const MAX_BUFFERED = 8 * 1024 * 1024; // close slow consumers (they reconnect + replay)

export interface Client {
  ws: WebSocket;
  user: Pick<UserRow, 'id' | 'role' | 'email'>;
  runs: Set<string>;
  projects: Set<string>;
  /** cache of view permission per project (ms timestamp of check, allowed) */
  viewCache: Map<string, { at: number; ok: boolean }>;
  alive: boolean;
}

export class Hub {
  clients = new Set<Client>();
  private runSubs = new Map<string, Set<Client>>();
  private projectSubs = new Map<string, Set<Client>>();
  /** called when a project gains its first / loses its last subscriber */
  onProjectSubChange: (projectId: string, subscribed: boolean) => void = () => {};

  constructor(private db: DB) {}

  add(c: Client) {
    this.clients.add(c);
  }

  remove(c: Client) {
    this.clients.delete(c);
    for (const r of c.runs) this.unsubRun(c, r);
    for (const p of [...c.projects]) this.unsubProject(c, p);
  }

  send(c: Client, msg: ServerMsg | string) {
    const ws = c.ws;
    if (ws.readyState !== ws.OPEN) return;
    if (ws.bufferedAmount > MAX_BUFFERED) {
      ws.close(1013, 'slow consumer');
      return;
    }
    ws.send(typeof msg === 'string' ? msg : JSON.stringify(msg));
  }

  subRun(c: Client, runId: string) {
    c.runs.add(runId);
    let s = this.runSubs.get(runId);
    if (!s) this.runSubs.set(runId, (s = new Set()));
    s.add(c);
  }
  unsubRun(c: Client, runId: string) {
    c.runs.delete(runId);
    const s = this.runSubs.get(runId);
    if (s) {
      s.delete(c);
      if (!s.size) this.runSubs.delete(runId);
    }
  }

  subProject(c: Client, projectId: string) {
    if (c.projects.has(projectId)) return;
    c.projects.add(projectId);
    let s = this.projectSubs.get(projectId);
    if (!s) this.projectSubs.set(projectId, (s = new Set()));
    s.add(c);
    if (s.size === 1) this.onProjectSubChange(projectId, true);
  }
  unsubProject(c: Client, projectId: string) {
    if (!c.projects.delete(projectId)) return;
    const s = this.projectSubs.get(projectId);
    if (s) {
      s.delete(c);
      if (!s.size) {
        this.projectSubs.delete(projectId);
        this.onProjectSubChange(projectId, false);
      }
    }
  }

  hasProjectSubscribers(projectId: string) {
    return (this.projectSubs.get(projectId)?.size ?? 0) > 0;
  }

  broadcastRun(runId: string, msg: ServerMsg) {
    const s = this.runSubs.get(runId);
    if (!s) return;
    const payload = JSON.stringify(msg);
    for (const c of s) this.send(c, payload);
  }

  broadcastProject(projectId: string, msg: ServerMsg) {
    const s = this.projectSubs.get(projectId);
    if (!s) return;
    const payload = JSON.stringify(msg);
    for (const c of s) this.send(c, payload);
  }

  canView(c: Client, projectId: string): boolean {
    if (c.user.role === 'admin') return true;
    const cached = c.viewCache.get(projectId);
    const t = Date.now();
    if (cached && t - cached.at < 30_000) return cached.ok;
    const ok = !!projectRole(this.db, c.user, projectId);
    c.viewCache.set(projectId, { at: t, ok });
    return ok;
  }

  /** Everyone connected who may view the project (graph pulses + run status for the Nexus view). */
  broadcastViewers(projectId: string, msg: ServerMsg) {
    const payload = JSON.stringify(msg);
    for (const c of this.clients) if (this.canView(c, projectId)) this.send(c, payload);
  }

  /** Drop all sockets of a user (disabled / deleted / logged out everywhere). */
  kickUser(userId: string) {
    for (const c of this.clients) if (c.user.id === userId) c.ws.close(4401, 'session ended');
  }

  invalidatePermissions() {
    for (const c of this.clients) c.viewCache.clear();
  }
}
import type { FastifyInstance } from 'fastify';
import type http from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocketServer, type WebSocket } from 'ws';
import { projectRole, SESSION_COOKIE } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { parseJson } from '../db.js';
import type { Client } from '../hub.js';
import type { ClientMsg, RunStatus, Suggestion } from '../shared/protocol.js';
import { clientIpOf, handlePreviewUpgrade } from './previewProxy.js';

export function attachWebSocket(app: FastifyInstance, ctx: Ctx) {
  const wss = new WebSocketServer({ noServer: true, maxPayload: 64 * 1024, perMessageDeflate: false });
  const { hub, db, runs } = ctx;

  const reject = (socket: Duplex, code: number, text: string) => {
    socket.end(`HTTP/1.1 ${code} ${text}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`);
  };

  app.server.on('upgrade', (req: http.IncomingMessage, socket: Duplex, head: Buffer) => {
    socket.on('error', () => socket.destroy());
    const url = req.url ?? '';
    if (url.startsWith('/preview/')) {
      handlePreviewUpgrade(app, ctx, req, socket, head);
      return;
    }
    if (url !== '/ws' && !url.startsWith('/ws?')) return reject(socket, 404, 'Not Found');
    const ip = clientIpOf(ctx, req);
    if (!ctx.ipRules.isAllowed(ip)) return reject(socket, 403, 'Forbidden');
    const origin = req.headers.origin;
    if (origin && !originOk(origin, req, ctx)) return reject(socket, 403, 'Forbidden');
    const token = app.parseCookie(req.headers.cookie ?? '')[SESSION_COOKIE];
    const user = ctx.sessions.lookup(token);
    if (!user) return reject(socket, 401, 'Unauthorized');
    wss.handleUpgrade(req, socket, head, (ws) => onConnection(ws, { id: user.id, role: user.role, email: user.email }, token!));
  });

  function onConnection(ws: WebSocket, user: Client['user'], token: string) {
    const c: Client = { ws, user, runs: new Set(), projects: new Set(), viewCache: new Map(), alive: true };
    hub.add(c);
    ws.on('pong', () => (c.alive = true));
    ws.on('close', () => hub.remove(c));
    ws.on('error', () => ws.terminate());
    ws.on('message', (raw, isBinary) => {
      if (isBinary) return;
      let msg: ClientMsg;
      try {
        msg = JSON.parse(raw.toString()) as ClientMsg;
      } catch {
        return hub.send(c, { t: 'error', message: 'invalid json' });
      }
      try {
        handle(c, msg);
      } catch (err) {
        ctx.log.warn({ err: (err as Error).message }, 'ws message failed');
        hub.send(c, { t: 'error', message: 'internal error' });
      }
    });
    // periodic session re-validation (logout / disable / password change)
    const recheck = setInterval(() => {
      const u = ctx.sessions.lookup(token);
      if (!u) ws.close(4401, 'session ended');
      else c.user = { id: u.id, role: u.role, email: u.email };
    }, 60_000);
    ws.on('close', () => clearInterval(recheck));
  }

  function handle(c: Client, msg: ClientMsg) {
    switch (msg?.t) {
      case 'ping':
        return hub.send(c, { t: 'pong' });
      case 'sub': {
        if (typeof msg.runId !== 'string') return;
        const run = db.prepare(`SELECT id, project_id, conversation_id, status FROM runs WHERE id = ?`).get(msg.runId) as
          | { id: string; project_id: string; conversation_id: string; status: RunStatus }
          | undefined;
        if (!run || !projectRole(db, c.user, run.project_id)) return hub.send(c, { t: 'error', message: `run ${msg.runId} not found` });
        const from = Number.isFinite(msg.fromSeq) ? Math.max(0, Math.floor(msg.fromSeq!)) : 0;
        // replay + subscribe synchronously: no events can slip in between
        const events = runs.replay(run.id, from);
        for (const e of events) hub.send(c, JSON.stringify({ t: 'run_event', runId: run.id, seq: e.seq, type: e.type, data: e.data, ts: e.ts }));
        hub.subRun(c, run.id);
        if (!runs.isActive(run.id)) {
          const fresh = db.prepare(`SELECT status FROM runs WHERE id = ?`).get(run.id) as { status: RunStatus };
          hub.send(c, { t: 'run_status', runId: run.id, conversationId: run.conversation_id, projectId: run.project_id, status: fresh.status });
          const m = db.prepare(`SELECT suggestions FROM messages WHERE run_id = ? AND role = 'assistant'`).get(run.id) as
            | { suggestions: string | null }
            | undefined;
          const items = parseJson<Suggestion[]>(m?.suggestions, []);
          if (items.length) hub.send(c, { t: 'suggestions', runId: run.id, items });
        } else {
          hub.send(c, { t: 'run_status', runId: run.id, conversationId: run.conversation_id, projectId: run.project_id, status: 'running' });
        }
        return;
      }
      case 'unsub':
        if (typeof msg.runId === 'string') hub.unsubRun(c, msg.runId);
        return;
      case 'sub_project': {
        if (typeof msg.projectId !== 'string') return;
        if (!projectRole(db, c.user, msg.projectId)) return hub.send(c, { t: 'error', message: `project ${msg.projectId} not found` });
        hub.subProject(c, msg.projectId);
        return;
      }
      case 'unsub_project':
        if (typeof msg.projectId === 'string') hub.unsubProject(c, msg.projectId);
        return;
      default:
        hub.send(c, { t: 'error', message: 'unknown message' });
    }
  }

  const heartbeat = setInterval(() => {
    for (const c of hub.clients) {
      if (!c.alive) {
        c.ws.terminate();
        continue;
      }
      c.alive = false;
      try {
        c.ws.ping();
      } catch {
        /* closed */
      }
    }
  }, 30_000);
  heartbeat.unref();
  app.addHook('onClose', async () => {
    clearInterval(heartbeat);
    wss.close();
  });
}

function originOk(origin: string, req: http.IncomingMessage, ctx: Ctx): boolean {
  try {
    const o = new URL(origin);
    if (o.origin === new URL(ctx.cfg.publicUrl).origin) return true;
    const host = (req.headers['x-forwarded-host'] as string | undefined) ?? req.headers.host;
    return !!host && o.host === host;
  } catch {
    return false;
  }
}
