export function scriptFor(prompt: string, sessionId = 'sess-1'): FakeEvent[] {
  const evs: FakeEvent[] = [
    { event: 'init', data: { sessionId, model: 'claude-test', tools: ['Read'], cwd: '/workspace/projects/x' } },
    { event: 'thinking', data: { delta: 'Let me think' } },
    { event: 'block_end', data: { kind: 'thinking' } },
    { event: 'tool_use', data: { id: 't1', name: 'Read', input: { file_path: 'README.md' } } },
    { event: 'tool_result', data: { id: 't1', isError: false, content: '# hi' } },
    { event: 'usage', data: { inputTokens: 100, outputTokens: 20, cacheReadTokens: 5, cacheWriteTokens: 1, contextTokens: 106 } },
    { event: 'text', data: { delta: 'Hello ' } },
    { event: 'text', data: { delta: 'world.\n\n<nx-sugg' } },
    { event: 'text', data: { delta: 'estions>[{"label":"Run tests","prompt":"npm test","kind":"test"},' } },
    { event: 'text', data: { delta: '{"label":"Next","prompt":"do next","kind":"weird"}]</nx-suggestions>' } },
    { event: 'block_end', data: { kind: 'text' } },
    {
      event: 'result',
      data: {
        sessionId, isError: false, result: 'Hello world.\n\n<nx-suggestions>[]</nx-suggestions>', durationMs: 1234, numTurns: 2, costUsd: 0.0123,
        usage: { inputTokens: 150, outputTokens: 40, cacheReadTokens: 5, cacheWriteTokens: 1 },
      },
    },
    { event: 'done', data: { exitCode: 0 } },
  ];
  if (prompt.includes('[auth]'))
    return [
      evs[0]!,
      { event: 'error', data: { message: 'Not logged in · Please run /login', code: 'authentication_failed' } },
      { event: 'result', data: { sessionId, isError: true, result: 'Not logged in', durationMs: 5, numTurns: 0, costUsd: 0, usage: { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 } } },
      { event: 'done', data: { exitCode: 1 } },
    ];
  if (prompt.startsWith('/compact'))
    return [
      evs[0]!,
      { event: 'compact', data: { trigger: 'manual', preTokens: 52100, postTokens: 3200, durationMs: 4000 } },
      { event: 'usage', data: { inputTokens: 0, outputTokens: 3200, cacheReadTokens: 52100, cacheWriteTokens: 0, estimated: true } },
      { event: 'result', data: { sessionId, isError: false, result: '', durationMs: 4100, numTurns: 0, costUsd: 0.01, usage: { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 } } },
      { event: 'done', data: { exitCode: 0 } },
    ];
  if (prompt.includes('[delegate]'))
    return [
      evs[0]!,
      { event: 'tool_use', data: { id: 'ag1', name: 'Agent', input: { subagent_type: 'researcher', description: 'Look it up', prompt: 'q' } } },
      { event: 'tool_use', data: { id: 'w1', name: 'WebSearch', input: { query: 'x' }, parentId: 'ag1' } },
      { event: 'tool_result', data: { id: 'w1', isError: false, content: 'results', parentId: 'ag1' } },
      { event: 'text', data: { delta: 'SUBAGENT SAYS 42', parentId: 'ag1' } },
      { event: 'usage', data: { inputTokens: 1000, outputTokens: 50, cacheReadTokens: 0, cacheWriteTokens: 0, parentId: 'ag1' } },
      { event: 'tool_result', data: { id: 'ag1', isError: false, content: '42' } },
      { event: 'usage', data: { inputTokens: 10, outputTokens: 5, cacheReadTokens: 900, cacheWriteTokens: 100, contextTokens: 1010 } },
      { event: 'text', data: { delta: 'The answer is 42.' } },
      { event: 'block_end', data: { kind: 'text' } },
      { event: 'result', data: { sessionId, isError: false, result: 'The answer is 42.', durationMs: 900, numTurns: 2, costUsd: 0.002, usage: { inputTokens: 10, outputTokens: 5, cacheReadTokens: 900, cacheWriteTokens: 100 } } },
      { event: 'done', data: { exitCode: 0 } },
    ];
  if (prompt.includes('[echo]')) evs.splice(6, 0, { event: 'text', data: { delta: `echo:${prompt}|` } });
  return evs;
}

