            prompt,
            projectSlug: project.slug,
            sessionId: conv.claude_session_id,
            model,
            mode,
            thinking: body.thinking,
            attachments: attachmentPaths,
            appendSystemPrompt: buildSystemPrompt(project as ProjectRow, cfg, [...agents.values()].map((a) => ({ slug: a.slug, description: a.description }))),
            maxTurns: s.maxTurns,
            previewPort: project.preview_port,
            ...(authToken ? { authToken } : {}),
            ...(s.autoCompactTokens ? { autocompactTokens: s.autoCompactTokens } : {}),
            ...(agents.size ? { agents: cliAgents(agents) } : {}),
