          messageId: userMsgId,
          assistantMessageId: asstMsgId,
          conversation: conversationDTO(db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(conv.id) as ConversationRow),
          attachments: loadAttachments(db, uploads.map((x) => x.id)),
