        const t = now();
        const runId = crypto.randomUUID();
        const userMsgId = crypto.randomUUID();
        const asstMsgId = crypto.randomUUID();
        db.transaction(() => {
          db.prepare(
            `INSERT INTO runs(id, conversation_id, project_id, user_id, status, model, mode, thinking, started_at, ip) VALUES (?,?,?,?, 'queued', ?,?, 'off', ?,?)`,
