196	    }
197	    let attempt = 0;
198	    let first = !recovering;
199	    while (!run.ended) {
200	      if (run.abortRequested && first) {
201	        this.synthEnd(run, null);
202	        return;
203	      }
204	      let res: Dispatcher.ResponseData;
205	      try {
206	        res = first ? await this.cb.startRun(run.body!, run.controller.signal) : await this.cb.attach(run.id, run.upstreamSeq + 1, run.controller.signal);
207	      } catch (err) {
208	        if (run.ended) return;
209	        if (run.abortRequested) {
210	          this.synthEnd(run, null);
211	          return;
212	        }
213	        if (first) {
214	          this.emit(run, 'error', { message: `Cannot reach claudebox: ${(err as Error).message}` });
215	          this.synthEnd(run, null);
216	          return;
217	        }
218	        if (++attempt > (recovering ? 2 : MAX_REATTACH)) {
219	          this.emit(run, 'error', { message: 'Lost connection to the Claude runner.' });
220	          this.synthEnd(run, null);
221	          return;
222	        }
223	        await sleep(Math.min(8000, 500 * 2 ** attempt));
224	        continue;
225	      }
226	      const wasFirst = first;
227	      first = false;
228	      if (res.statusCode !== 200) {
229	        const text = (await res.body.text().catch(() => '')).slice(0, 500);
230	        if (run.ended) return;
231	        if (!wasFirst && res.statusCode === 404) {
232	          this.emit(run, 'error', { message: recovering ? 'The run was lost while the server restarted.' : 'Lost connection to the Claude runner (run no longer available).' });
