234	          let msg = text;
235	          try {
236	            const j = JSON.parse(text) as { error?: unknown; message?: unknown };
237	            const e = j.error ?? j.message;
238	            msg = typeof e === 'string' ? e : (e as { message?: string })?.message ?? text;
239	          } catch {
240	            /* plain text */
241	          }
242	          this.emit(run, 'error', { message: `Claude runner error (${res.statusCode}): ${msg || 'unknown error'}` });
243	        }
244	        this.synthEnd(run, null);
245	        return;
246	      }
247	      attempt = 0;
248	      try {
249	        await this.consume(run, res.body);
