289	    const type = m.event as RunEventType;
290	    if (!KNOWN_TYPES.has(type)) return;
291	    let data: Record<string, unknown>;
292	    try {
293	      data = (m.data ? JSON.parse(m.data) : {}) as Record<string, unknown>;
294	    } catch {
295	      return;
296	    }
297	    switch (type) {
298	      case 'init': {
299	        const sid = typeof data.sessionId === 'string' ? data.sessionId : null;
300	        if (sid) this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(sid, run.conversationId);
301	        this.emit(run, 'init', data);
302	        break;
303	      }
304	      case 'text': {
305	        if (typeof data.parentId === 'string') {
306	          // forwarded subagent text: shown under the delegating tool, never part of the answer
307	          this.emit(run, 'text', data);
308	          break;
309	        }
310	        let delta = typeof data.delta === 'string' ? data.delta : '';
311	        if (!delta) return;
312	        if (run.needSep && run.fullText.length && !/\n\s*$/.test(run.fullText)) delta = '\n\n' + delta;
313	        run.needSep = false;
314	        run.fullText += delta;
315	        this.emitVisible(run, true);
316	        break;
317	      }
318	      case 'block_end': {
319	        if (data.kind === 'text') {
320	          this.emitVisible(run, false);
321	          run.needSep = true;
322	        }
323	        this.emit(run, 'block_end', data);
324	        break;
325	      }
326	      case 'usage': {
327	        const u = data as Partial<Usage>;
328	        run.usage.inputTokens += num(u.inputTokens);
329	        run.usage.outputTokens += num(u.outputTokens);
330	        run.usage.cacheReadTokens += num(u.cacheReadTokens);
331	        run.usage.cacheWriteTokens += num(u.cacheWriteTokens);
332	        if (!data.parentId && num(data.contextTokens) > 0) this.setContextTokens(run, num(data.contextTokens));
333	        this.emit(run, 'usage', data);
334	        break;
335	      }
336	      case 'compact': {
337	        this.setContextTokens(run, num(data.postTokens));
338	        this.emit(run, 'compact', data);
339	        break;
340	      }
341	      case 'result': {
342	        run.sawResult = true;
343	        run.resultIsError = !!data.isError;
344	        run.resultText = typeof data.result === 'string' ? data.result : '';
345	        const u = data.usage as Partial<Usage> | undefined;
346	        if (u && typeof u === 'object') {
347	          // result.usage covers the main thread only; the summed usage events also include subagents
348	          // (parentId) and estimated compaction usage — keep whichever is larger per field.
349	          run.usage = {
350	            inputTokens: Math.max(num(u.inputTokens), run.usage.inputTokens),
351	            outputTokens: Math.max(num(u.outputTokens), run.usage.outputTokens),
352	            cacheReadTokens: Math.max(num(u.cacheReadTokens), run.usage.cacheReadTokens),
353	            cacheWriteTokens: Math.max(num(u.cacheWriteTokens), run.usage.cacheWriteTokens),
354	          };
355	        }
356	        if (typeof data.costUsd === 'number') {
357	          // total_cost_usd is cumulative for the resumed session: charge this run only the increase.
358	          const prev = (this.db
359	            .prepare(`SELECT COALESCE(MAX(session_cost_usd), 0) AS v FROM runs WHERE conversation_id = ? AND id != ? AND started_at <= ?`)
360	            .get(run.conversationId, run.id, run.startedAt) as { v: number }).v;
361	          run.sessionCostUsd = data.costUsd;
362	          run.costUsd = data.costUsd >= prev ? data.costUsd - prev : data.costUsd;
363	        }
364	        if (typeof data.durationMs === 'number') run.durationMs = data.durationMs;
365	        if (typeof data.sessionId === 'string' && data.sessionId)
366	          this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(data.sessionId, run.conversationId);
367	        if (run.resultIsError && run.resultText && !run.lastError) run.lastError = run.resultText;
368	        // The suggestions block lives in the final text; don't leak it through the result payload.
369	        this.emit(run, 'result', { ...data, result: finalContent(run.resultText) });
370	        break;
371	      }
372	      case 'error': {
373	        run.sawError = true;
374	        if (data.code === 'authentication_failed') {
375	          data = { ...data, detail: data.message, message: AUTH_HINT };
376	        }
377	        run.lastError = typeof data.message === 'string' ? data.message : 'error';
378	        this.emit(run, 'error', data);
379	        break;
380	      }
381	      case 'done': {
382	        this.emitVisible(run, false);
383	        run.exitCode = typeof data.exitCode === 'number' ? data.exitCode : null;
384	        if (data.aborted === true) run.abortRequested = true;
385	        this.emit(run, 'done', { ...data, exitCode: run.exitCode });
386	        this.finalize(run);
387	        break;
388	      }
389	      default:
390	        this.emit(run, type, data);
391	    }
392	  }
