407	  private emit(run: ActiveRun, type: string, data: unknown) {
408	    const seq = ++run.seq;
409	    const ts = now();
410	    const ev: StoredEvent = { seq, type, data, ts };
411	    run.pending.push(ev);
412	    // `ts` is an additive field (not in protocol.ts) used by the UI for "Thought for Xs".
413	    this.hub.broadcastRun(run.id, { t: 'run_event', runId: run.id, seq, type, data, ts } as never);
414	    this.pulse(run.projectId, PULSE[type as RunEventType] ?? 0.2);
415	    if (!this.flushTimer) this.flushTimer = setTimeout(() => this.flushAll(), FLUSH_MS);
