425	  flushAll() {
426	    if (this.flushTimer) {
427	      clearTimeout(this.flushTimer);
428	      this.flushTimer = null;
429	    }
430	    const tx = this.db.transaction(() => {
431	      for (const run of this.active.values()) this.flushRun(run);
