440	  private flushRun(run: ActiveRun) {
441	    if (!run.pending.length) return;
442	    for (const e of run.pending) this.insertEvent.run(run.id, e.seq, e.type, JSON.stringify(e.data ?? null), e.ts);
443	    run.pending = [];
444	    this.updateRunTotals.run(
445	      run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
446	      run.costUsd, run.upstreamSeq, run.id,
447	    );
448	  }
