450	  /** Emit a synthetic `done` and finalize (used on errors / aborts without upstream completion). */
451	  private synthEnd(run: ActiveRun, exitCode: number | null) {
452	    if (run.ended) return;
453	    this.emitVisible(run, false);
454	    run.exitCode = exitCode;
455	    this.emit(run, 'done', { exitCode });
456	    this.finalize(run);
