459	  private finalize(run: ActiveRun) {
460	    if (run.ended) return;
461	    run.ended = true;
462	    run.controller.abort();
463	    let status: RunStatus;
464	    if (run.abortRequested) status = 'aborted';
465	    else if (run.sawResult) status = run.resultIsError ? 'error' : 'done';
466	    else if (run.sawError) status = 'error';
467	    else status = run.exitCode === 0 ? 'done' : 'error';
468	
469	    let suggestions: Suggestion[] = parseSuggestions(run.fullText);
470	    if (!suggestions.length && run.resultText) suggestions = parseSuggestions(run.resultText);
471	    let content = finalContent(run.fullText);
472	    if (!content && run.resultText) content = finalContent(run.resultText);
473	    const t = now();
474	    const durationMs = run.durationMs ?? t - run.startedAt;
475	
476	    this.db.transaction(() => {
477	      this.flushRun(run);
478	      this.updateRunTotals.run(
479	        run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
480	        run.costUsd, run.upstreamSeq, run.id,
481	      );
482	      this.db
483	        .prepare(`UPDATE runs SET status = ?, ended_at = ?, duration_ms = ?, error = ?, session_cost_usd = ? WHERE id = ?`)
484	        .run(status, t, durationMs, status === 'error' ? (run.lastError ?? 'Run failed').slice(0, 2000) : null, run.sessionCostUsd, run.id);
485	      this.db
486	        .prepare(`UPDATE messages SET content = ?, suggestions = ? WHERE id = ?`)
487	        .run(content, suggestions.length ? JSON.stringify(suggestions) : null, run.assistantMessageId);
488	      this.db.prepare(`UPDATE conversations SET updated_at = ? WHERE id = ?`).run(t, run.conversationId);
489	      this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(t, run.projectId);
490	    })();
491	    this.active.delete(run.id);
492	    if (suggestions.length) this.hub.broadcastRun(run.id, { t: 'suggestions', runId: run.id, items: suggestions });
493	    this.hub.broadcastViewers(run.projectId, { t: 'run_status', runId: run.id, conversationId: run.conversationId, projectId: run.projectId, status });
494	    this.pulse(run.projectId, 1);
495	    if (status === 'done' && run.kind !== 'compact') void this.autoStartPreview(run.projectId);
496	  }
