516	  async abort(runId: string): Promise<boolean> {
517	    const run = this.active.get(runId);
518	    if (!run) {
519	      // orphan (e.g. not driven by this process): mark aborted directly
520	      const r = this.db.prepare(`SELECT status FROM runs WHERE id = ?`).get(runId) as { status: RunStatus } | undefined;
521	      if (r && (r.status === 'running' || r.status === 'queued')) {
522	        this.db.prepare(`UPDATE runs SET status = 'aborted', ended_at = ? WHERE id = ?`).run(now(), runId);
523	        return true;
524	      }
525	      return false;
526	    }
527	    if (run.ended) return false;
528	    run.abortRequested = true;
529	    try {
530	      await this.cb.abort(runId);
531	    } catch (err) {
532	      this.log.warn({ runId, err: (err as Error).message }, 'claudebox abort failed');
533	    }
534	    setTimeout(() => {
535	      if (!run.ended) {
536	        run.controller.abort();
537	        this.synthEnd(run, null);
538	      }
539	    }, ABORT_GRACE_MS).unref();
540	    return true;
541	  }
