545	  /** On startup: re-attach to runs left running by a previous process, or mark them as errored. */
546	  recoverOrphans() {
547	    const rows = this.db
548	      .prepare(
549	        `SELECT r.id, r.conversation_id, r.project_id, r.user_id, r.upstream_seq, r.input_tokens, r.output_tokens, r.cache_read,
550	                r.cache_write, r.cost_usd, r.started_at, m.id AS message_id
551	         FROM runs r LEFT JOIN messages m ON m.run_id = r.id AND m.role = 'assistant'
552	         WHERE r.status IN ('queued','running')`,
553	      )
554	      .all() as {
555	      id: string; conversation_id: string; project_id: string; user_id: string | null; upstream_seq: number;
556	      input_tokens: number; output_tokens: number; cache_read: number; cache_write: number; cost_usd: number;
557	      started_at: number; message_id: string | null;
558	    }[];
559	    for (const r of rows) {
560	      if (this.active.has(r.id)) continue;
561	      const run = this.newState(r.id, r.conversation_id, r.project_id, r.user_id, r.message_id ?? '', null);
562	      run.startedAt = r.started_at;
563	      run.upstreamSeq = r.upstream_seq;
564	      run.usage = { inputTokens: r.input_tokens, outputTokens: r.output_tokens, cacheReadTokens: r.cache_read, cacheWriteTokens: r.cache_write };
565	      run.costUsd = r.cost_usd;
566	      const evs = this.db.prepare(`SELECT seq, type, data FROM run_events WHERE run_id = ? ORDER BY seq`).all(r.id) as {
567	        seq: number; type: string; data: string;
568	      }[];
569	      for (const e of evs) {
570	        run.seq = e.seq;
571	        const d = parseJson<Record<string, unknown>>(e.data, {});
572	        if (e.type === 'text' && typeof d.delta === 'string' && !d.parentId) {
573	          run.fullText += d.delta;
574	          run.needSep = false;
575	        } else if (e.type === 'block_end' && d.kind === 'text') run.needSep = true;
576	        else if (e.type === 'error') {
577	          run.sawError = true;
578	          run.lastError = String(d.message ?? 'error');
579	        }
580	      }
581	      run.emittedLen = run.fullText.length;
582	      this.active.set(run.id, run);
583	      this.log.info({ runId: r.id }, 'recovering orphaned run');
584	      void this.drive(run, true);
585	    }
586	  }
