588	  /** Graceful shutdown: flush pending events; leave runs as running so the next start can re-attach. */
589	  shutdown() {
590	    this.flushAll();
591	    for (const run of this.active.values()) {
592	      run.ended = true; // stop drive loops without finalizing
593	      run.controller.abort();
594	    }
595	  }
596	}
