38	async function buildTree(abs: string, rel: string, depth: number, budget: { n: number }): Promise<FileNode[]> {
39	  let entries: fs.Dirent[];
40	  try {
41	    entries = await fsp.readdir(abs, { withFileTypes: true });
42	  } catch {
43	    return [];
44	  }
45	  entries.sort((a, b) => {
46	    const ad = a.isDirectory() ? 0 : 1;
47	    const bd = b.isDirectory() ? 0 : 1;
48	    return ad - bd || a.name.localeCompare(b.name);
49	  });
50	  const out: FileNode[] = [];
51	  for (const e of entries) {
52	    if (budget.n-- <= 0) break;
53	    const childRel = rel ? `${rel}/${e.name}` : e.name;
54	    const childAbs = path.join(abs, e.name);
55	    if (e.isSymbolicLink()) {
56	      // never follow symlinks in the tree; show them as files
57	      out.push({ name: e.name, path: childRel, type: 'file', symlink: true });
58	      continue;
59	    }
60	    if (e.isDirectory()) {
61	      const node: FileNode = { name: e.name, path: childRel, type: 'dir' };
62	      if (HEAVY_DIRS.has(e.name) || depth >= MAX_DEPTH || budget.n <= 0) node.lazy = true;
63	      else node.children = await buildTree(childAbs, childRel, depth + 1, budget);
64	      out.push(node);
65	    } else if (e.isFile()) {
66	      let size: number | undefined;
67	      let mtime: string | undefined;
68	      try {
69	        const st = await fsp.stat(childAbs);
70	        size = st.size;
71	        mtime = st.mtime.toISOString();
72	      } catch {
73	        /* vanished */
74	      }
75	      out.push({ name: e.name, path: childRel, type: 'file', size, mtime });
76	    }
77	  }
78	  return out;
