#!/usr/bin/env bash
# Nxeon Workspace — build images and (re)start the stack, then wait for health.
#   deploy/up.sh                # build all + up
#   deploy/up.sh --no-build     # just (re)create containers
#   deploy/up.sh app            # build + restart only the given service(s)
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT=$PWD
DC=(sudo docker compose -f "$ROOT/docker-compose.yml" --project-directory "$ROOT")

BUILD=1
SERVICES=()
for a in "$@"; do
  case "$a" in
    --no-build) BUILD=0 ;;
    -h|--help) sed -n '2,6p' "$0"; exit 0 ;;
    *) SERVICES+=("$a") ;;
  esac
done

log() { printf '\033[38;5;205m[nxeon]\033[0m %s\n' "$*"; }
die() { printf '\033[31m[nxeon] %s\033[0m\n' "$*" >&2; exit 1; }

[ -f .env ] || die ".env missing (copy .env.example, fill secrets, chmod 600)"
[ "$(stat -c %a .env)" = "600" ] || { log "fixing .env permissions -> 600"; chmod 600 .env; }
[ -f Dockerfile.app ] || die "Dockerfile.app missing (app image cannot be built)"

# Bind-mount dirs must exist and be writable by uid 1000 (app + claudebox users).
for d in projects uploads db claude-home whisper-models backups; do
  mkdir -p "data/$d"
done
if [ -n "$(find data -maxdepth 2 \( -not -uid 1000 -o -not -gid 1000 \) -print -quit 2>/dev/null)" ]; then
  log "fixing ownership of data/ -> 1000:1000"
  sudo chown -R 1000:1000 data
fi

if [ "$BUILD" = 1 ]; then
  log "building images ${SERVICES[*]:-(all)}"
  "${DC[@]}" build --pull "${SERVICES[@]}"
fi

log "starting containers"
"${DC[@]}" up -d --remove-orphans "${SERVICES[@]}"

# Wait for docker healthchecks.
wait_healthy() {
  local c=$1 timeout=${2:-180} s
  for ((i = 0; i < timeout; i += 3)); do
    s=$(sudo docker inspect -f '{{if .State.Health}}{{.State.Health.Status}}{{else}}{{.State.Status}}{{end}}' "$c" 2>/dev/null || echo missing)
    case "$s" in
      healthy|running) log "$c: $s"; return 0 ;;
      unhealthy|exited|dead|missing) break ;;
    esac
    sleep 3
  done
  sudo docker logs --tail 40 "$c" 2>&1 | sed 's/^/    /' >&2
  die "$c did not become healthy (status: $s)"
}
wait_healthy nxeon-whisper 240
wait_healthy nxeon-claudebox 240
wait_healthy nxeon-app 180

# End-to-end through the published loopback port (what Caddy uses).
curl -fsS --max-time 5 http://127.0.0.1:8080/api/health >/dev/null \
  && log "app reachable on 127.0.0.1:8080" || die "app not reachable on 127.0.0.1:8080"

# Safety: nothing but 127.0.0.1:8080 may be published (docker bypasses ufw).
bad=$(sudo docker ps --format '{{.Names}} {{.Ports}}' | grep -E '0\.0\.0\.0:|\[::\]:|:::' || true)
[ -z "$bad" ] || log "WARNING: publicly published ports found: $bad"

"${DC[@]}" ps
log "done"
"use strict";
// Preview process manager: one dev server (or built-in static server) per project.

const { spawn } = require("child_process");
const fs = require("fs");
const net = require("net");
const path = require("path");
const { createStaticServer } = require("./static");

const LOG_LINES = 200;

function probePort(port, timeoutMs = 400) {
  const tryHost = (host) =>
    new Promise((resolve) => {
      const sock = net.connect({ host, port });
      const finish = (ok) => {
        sock.destroy();
        resolve(ok);
      };
      sock.setTimeout(timeoutMs, () => finish(false));
      sock.once("connect", () => finish(true));
      sock.once("error", () => finish(false));
    });
  return tryHost("127.0.0.1").then((ok) => ok || tryHost("::1"));
}

/** Find pids (same uid) with a LISTEN socket on `port`, via /proc. Linux only. */
function listenerPids(port) {
  const inodes = new Set();
  const hex = port.toString(16).toUpperCase().padStart(4, "0");
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) {
    let txt;
    try {
      txt = fs.readFileSync(f, "utf8");
    } catch {
      continue;
    }
    for (const line of txt.split("\n").slice(1)) {
      const cols = line.trim().split(/\s+/);
      if (cols.length < 10) continue;
      const localPort = cols[1].split(":").pop();
      if (localPort === hex && cols[3] === "0A") inodes.add(cols[9]);
    }
  }
  const pids = new Set();
  if (!inodes.size) return [];
  let procs = [];
  try {
    procs = fs.readdirSync("/proc").filter((d) => /^\d+$/.test(d));
  } catch {
    return [];
  }
  for (const pid of procs) {
    let fds;
    try {
      fds = fs.readdirSync(`/proc/${pid}/fd`);
    } catch {
      continue;
    }
    for (const fd of fds) {
      try {
        const l = fs.readlinkSync(`/proc/${pid}/fd/${fd}`);
        const m = /^socket:\[(\d+)\]$/.exec(l);
        if (m && inodes.has(m[1])) {
          pids.add(Number(pid));
          break;
        }
      } catch {
        /* ignore */
      }
    }
  }
  return [...pids];
}

function pgidOf(pid) {
  try {
    const stat = fs.readFileSync(`/proc/${pid}/stat`, "utf8");
    const after = stat.slice(stat.lastIndexOf(")") + 2).split(" ");
    return Number(after[2]); // state ppid pgrp
  } catch {
    return null;
  }
}

function readJSON(file) {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return null;
  }
}

/**
 * Decide how to run a project's preview.
 * @returns {{kind:'process', command:string} | {kind:'static', root:string} | {error:string}}
 */
function detectCommand(dir, slug, port) {
  const base = `/preview/${slug}/`;
  const pkg = readJSON(path.join(dir, "package.json"));
  if (pkg) {
    const scripts = pkg.scripts || {};
    const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
    const install = fs.existsSync(path.join(dir, "node_modules")) ? "" : "npm install --no-audit --no-fund && ";
    if (scripts.dev) {
      if (deps.vite || /\bvite\b/.test(scripts.dev)) {
        return { kind: "process", command: `${install}npm run dev -- --host 0.0.0.0 --port ${port} --strictPort --base ${base}` };
      }
      if (deps.next || /\bnext\b/.test(scripts.dev)) {
        return { kind: "process", command: `${install}npx next dev -p ${port} -H 0.0.0.0` };
      }
      return { kind: "process", command: `${install}npm run dev` };
    }
    if (scripts.start) return { kind: "process", command: `${install}npm start` };
  }
  for (const sub of ["", "dist", "build", "public", "out"]) {
    const root = path.join(dir, sub);
    if (fs.existsSync(path.join(root, "index.html"))) return { kind: "static", root };
  }
  return { error: "Could not detect a preview command (no package.json dev/start script and no index.html). Pass `command`." };
}

class PreviewManager {
  constructor(config) {
    this.config = {
      projectsDir: "/workspace/projects",
      portMin: 4100,
      portMax: 4199,
      env: process.env,
      allowedHost: "claudebox",
      log: () => {},
      ...config,
    };
    this.previews = new Map(); // slug -> record
  }

  _alive(rec) {
    return !!rec && rec.alive;
  }

  _appendLog(rec, text) {
    rec.partial += text;
    const lines = rec.partial.split(/\r?\n/);
    rec.partial = lines.pop();
    for (const l of lines) rec.logs.push(l);
    if (rec.partial.length > 4000) {
      rec.logs.push(rec.partial);
      rec.partial = "";
    }
    if (rec.logs.length > LOG_LINES) rec.logs.splice(0, rec.logs.length - LOG_LINES);
  }

  _env(slug, port) {
    const env = { ...this.config.env };
    for (const k of ["CLAUDEBOX_API_KEY", "CLAUDE_CODE_OAUTH_TOKEN", "ANTHROPIC_API_KEY"]) delete env[k];
    Object.assign(env, {
      PORT: String(port),
      HOST: "0.0.0.0",
      BASE_PATH: `/preview/${slug}/`,
      BROWSER: "none",
      __VITE_ADDITIONAL_SERVER_ALLOWED_HOSTS: this.config.allowedHost,
    });
    return env;
  }

  async start({ projectSlug: slug, port, command }) {
    const c = this.config;
    const dir = path.join(c.projectsDir, slug);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    if (!Number.isInteger(port) || port < c.portMin || port > c.portMax) {
      return { status: 400, body: { error: `port must be an integer in ${c.portMin}-${c.portMax}` } };
    }
    for (const [other, rec] of this.previews) {
      if (other !== slug && this._alive(rec) && rec.port === port) {
        return { status: 409, body: { error: `Port ${port} is used by preview of '${other}'` } };
      }
    }
    if (this._alive(this.previews.get(slug))) await this.stop({ projectSlug: slug });
    if (await probePort(port)) {
      // Something (usually a dev server Claude started via Bash) already serves this port: adopt it.
      return { status: 200, body: { ...(await this.status(slug, port)), adopted: true } };
    }

    let plan;
    if (command != null && command !== "") {
      if (typeof command !== "string" || command.length > 4000) return { status: 400, body: { error: "Invalid command" } };
      plan = { kind: "process", command };
    } else {
      plan = detectCommand(dir, slug, port);
      if (plan.error) return { status: 422, body: { error: plan.error } };
    }

    const rec = {
      slug, port, kind: plan.kind, command: plan.kind === "static" ? `builtin-static ${plan.root}` : plan.command,
      pid: null, proc: null, server: null, alive: false, startedAt: Date.now(), exitCode: null, exitedAt: null,
      logs: [], partial: "",
    };
    this.previews.set(slug, rec);

    if (plan.kind === "static") {
      const server = createStaticServer({
        root: plan.root,
        prefix: `/preview/${slug}/`,
        onLog: (l) => this._appendLog(rec, l + "\n"),
      });
      const sockets = new Set();
      server.on("connection", (s) => {
        sockets.add(s);
        s.on("close", () => sockets.delete(s));
      });
      try {
        await new Promise((resolve, reject) => {
          server.once("error", reject);
          server.listen(port, "0.0.0.0", resolve);
        });
      } catch (err) {
        rec.exitCode = 1;
        this._appendLog(rec, `static server failed: ${err.message}\n`);
        return { status: 500, body: { error: err.message, ...(await this.status(slug)) } };
      }
      rec.server = server;
      rec.sockets = sockets;
      rec.alive = true;
      rec.pid = process.pid;
      this._appendLog(rec, `serving ${plan.root} at http://0.0.0.0:${port}/preview/${slug}/\n`);
      c.log("info", "preview started", { slug, port, kind: "static" });
      return { status: 200, body: await this.status(slug) };
    }

    const proc = spawn("bash", ["-c", plan.command], {
      cwd: dir,
      env: this._env(slug, port),
      stdio: ["ignore", "pipe", "pipe"],
      detached: true,
    });
    rec.proc = proc;
    rec.pid = proc.pid;
    rec.alive = true;
    this._appendLog(rec, `$ ${plan.command}\n`);
    proc.stdout.setEncoding("utf8");
    proc.stderr.setEncoding("utf8");
    proc.stdout.on("data", (d) => this._appendLog(rec, d));
    proc.stderr.on("data", (d) => this._appendLog(rec, d));
    proc.on("error", (err) => {
      this._appendLog(rec, `spawn error: ${err.message}\n`);
      rec.alive = false;
    });
    proc.on("exit", (code, signal) => {
      rec.alive = false;
      rec.exitCode = code;
      rec.exitedAt = Date.now();
      if (rec.partial) {
        rec.logs.push(rec.partial);
        rec.partial = "";
      }
      this._appendLog(rec, `[process exited code=${code} signal=${signal || ""}]\n`);
      c.log("info", "preview exited", { slug, code, signal });
    });
    c.log("info", "preview started", { slug, port, pid: proc.pid, command: plan.command });
    return { status: 200, body: await this.status(slug) };
  }

  async stop({ projectSlug: slug, port }) {
    const rec = this.previews.get(slug);
    const targetPort = port || rec?.port || null;
    let stopped = false;
    if (rec && rec.alive) {
      if (rec.kind === "static" && rec.server) {
        await new Promise((resolve) => {
          rec.server.close(() => resolve());
          for (const s of rec.sockets || []) s.destroy();
        });
        rec.alive = false;
        rec.exitedAt = Date.now();
        this._appendLog(rec, "[static server stopped]\n");
      } else if (rec.proc) {
        const pid = rec.pid;
        const kill = (sig) => {
          try {
            process.kill(-pid, sig);
          } catch {
            try {
              process.kill(pid, sig);
            } catch {
              /* gone */
            }
          }
        };
        kill("SIGTERM");
        const exited = await new Promise((resolve) => {
          if (!rec.alive) return resolve(true);
          const t = setTimeout(() => resolve(false), 3000);
          rec.proc.once("exit", () => {
            clearTimeout(t);
            resolve(true);
          });
        });
        if (!exited) kill("SIGKILL");
        // also kill leftovers of the group even if leader exited
        try {
          process.kill(-pid, "SIGKILL");
        } catch {
          /* none */
        }
      }
      stopped = true;
    }
    // Something else (e.g. a server Claude started via Bash) still listening on the port?
    if (targetPort && Number.isInteger(targetPort) && targetPort >= this.config.portMin && targetPort <= this.config.portMax) {
      const ownPgid = pgidOf(process.pid);
      const protectedPgids = new Set(this.config.protectedPgids ? this.config.protectedPgids() : []);
      for (const pid of listenerPids(targetPort)) {
        if (pid === process.pid) continue;
        const pg = pgidOf(pid);
        try {
          if (pg && pg !== ownPgid && pg > 1 && !protectedPgids.has(pg)) process.kill(-pg, "SIGTERM");
          else process.kill(pid, "SIGTERM");
          stopped = true;
          this.config.log("info", "killed external preview listener", { slug, port: targetPort, pid, pgid: pg });
        } catch {
          /* ignore */
        }
      }
    }
    return { stopped, ...(await this.status(slug, targetPort)) };
  }

  async status(slug, port) {
    const rec = this.previews.get(slug) || null;
    const p = port || rec?.port || null;
    const listening = p ? await probePort(p) : false;
    const managed = this._alive(rec);
    return {
      projectSlug: slug,
      running: managed || listening,
      managed,
      listening,
      port: p,
      pid: managed ? rec.pid : null,
      kind: rec?.kind || null,
      command: rec?.command || null,
      startedAt: rec?.startedAt || null,
      exitCode: rec ? rec.exitCode : null,
      logTail: rec ? rec.logs.concat(rec.partial ? [rec.partial] : []).slice(-LOG_LINES) : [],
    };
  }

  async list() {
    const out = [];
    for (const slug of this.previews.keys()) out.push(await this.status(slug));
    return out;
  }

  async stopAll() {
    for (const slug of this.previews.keys()) await this.stop({ projectSlug: slug }).catch(() => {});
  }
}

module.exports = { PreviewManager, detectCommand, probePort, listenerPids };

