225	function findNode(s: { tree: FileNode[] | null; lazyKids: Record<string, FileNode[]> }, path: string): FileNode | null {
226	  let found: FileNode | null = null;
227	  const visit = (n: FileNode) => { if (n.path === path) found = n; };
228	  walkFiles(s.tree, visit);
229	  for (const kids of Object.values(s.lazyKids)) walkFiles(kids, visit);
230	  return found;
231	}
232	export function treeHas(nodes: FileNode[] | null, path: string): boolean {
233	  let found = false; walkFiles(nodes, (n) => { if (n.path === path) found = true; }); return found;
