354	function fileIcon(name: string) {
355	  if (IMAGE_RE.test(name)) return <ImageIcon size={14} className="text-warm/80" />;
356	  if (/\.(json|lock)$/i.test(name)) return <FileJson size={14} className="text-warn/70" />;
357	  if (/\.(md|txt|mdx)$/i.test(name)) return <FileText size={14} className="text-muted" />;
358	  if (/\.(tsx?|jsx?|mjs|cjs|py|go|rs|rb|java|c|cpp|h|cs|php|sh|vue|svelte)$/i.test(name)) return <FileCode size={14} className="text-pink/70" />;
359	  if (/\.(css|scss|less|html?)$/i.test(name)) return <CodeIcon size={14} className="text-violet/80" />;
360	  return <FileIcon size={14} className="text-muted/80" />;
361	}
