389	        onClick={() => (isDir ? toggleDir(node.path) : openFile(node.path))}
390	        onKeyDown={(e) => { if (e.key === 'Enter') isDir ? toggleDir(node.path) : openFile(node.path); if (e.key === 'F2') setRenaming(node.path); }}
