410	        {renaming === node.path ? (
411	          <InlineInput initial={node.name} onCancel={() => setRenaming(null)}
412	            onCommit={(v) => { setRenaming(null); renamePath(node.path, join(parentOf(node.path), v)).catch(() => {}); }} />
413	        ) : (
414	          <span className="min-w-0 flex-1 truncate">{node.name}</span>
415	        )}
416	        <button type="button" onClick={(e) => { e.stopPropagation(); onMenu(e, node); }}
417	          className="hidden h-5 w-5 shrink-0 items-center justify-center rounded text-muted hover:bg-white/10 hover:text-ink group-hover:flex">
418	          <Ellipsis size={13} />
419	        </button>
