422	        <div>
423	          {childPending && (
424	            <div className="flex h-[26px] items-center gap-1.5 pr-2" style={{ paddingLeft: pad + 12 + 15 }}>
425	              {pending!.kind === 'dir' ? <Folder size={14} className="shrink-0 text-pink/60" /> : <FileIcon size={14} className="shrink-0 text-muted" />}
426	              <InlineInput initial="" placeholder={pending!.kind === 'dir' ? 'folder name' : 'file name'} onCancel={() => setPending(null)}
427	                onCommit={(v) => { setPending(null); (pending!.kind === 'dir' ? createDir : createFile)(join(node.path, v)).catch(() => {}); }} />
428	            </div>
