518	function relTime(iso?: string) {
519	  if (!iso) return '';
520	  const d = Date.now() - Date.parse(iso);
521	  if (d < 60_000) return 'now';
522	  if (d < 3_600_000) return `${Math.floor(d / 60_000)}m`;
523	  if (d < 86_400_000) return `${Math.floor(d / 3_600_000)}h`;
524	  if (d < 7 * 86_400_000) return `${Math.floor(d / 86_400_000)}d`;
525	  return new Date(iso).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
526	}
