496	 *  open, onClose, title?, description?, children, footer? (right-aligned action row)
497	 *  size 'sm'(380) | 'md'(520) | 'lg'(720) | 'xl'(960)  (default 'md'); dismissible (default true)
498	 * Drawer — side sheet, same props + side 'right'|'left' (default right), width px (default 560).
499	 */
500	export interface ModalProps {
501	  open: boolean; onClose: () => void; title?: ReactNode; description?: ReactNode; children?: ReactNode; footer?: ReactNode;
502	  size?: 'sm' | 'md' | 'lg' | 'xl'; dismissible?: boolean; className?: string; icon?: ReactNode;
