506	function useDialog(open: boolean, onClose: () => void, dismissible: boolean) {
507	  const ref = useRef<HTMLDivElement>(null);
508	  useEffect(() => {
509	    if (!open) return;
510	    const prev = document.activeElement as HTMLElement | null;
511	    const t = window.setTimeout(() => {
512	      const el = ref.current;
513	      if (!el) return;
514	      const f = el.querySelector<HTMLElement>('[autofocus],input:not([disabled]):not([type=hidden]),textarea:not([disabled]),select:not([disabled])');
515	      (f || el).focus();
516	    }, 20);
517	    const onKey = (e: KeyboardEvent) => {
518	      if (e.key === 'Escape' && dismissible) { e.stopPropagation(); onClose(); }
519	      if (e.key === 'Tab' && ref.current) {
520	        const els = Array.from(ref.current.querySelectorAll<HTMLElement>('a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])'));
521	        if (!els.length) return;
522	        const first = els[0], last = els[els.length - 1];
523	        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
524	        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
525	      }
526	    };
527	    window.addEventListener('keydown', onKey);
528	    return () => { window.clearTimeout(t); window.removeEventListener('keydown', onKey); prev?.focus?.(); };
529	  }, [open, onClose, dismissible]);
530	  return ref;
531	}
