6	// ---------- Tooltip ----------
7	export function Tip({ label, children, side = 'top', kbd }: { label: ReactNode; children: ReactElement<any>; side?: 'top' | 'bottom' | 'left' | 'right'; kbd?: string }) {
8	  const [rect, setRect] = useState<DOMRect | null>(null);
9	  const timer = useRef<number>();
10	  const show = (e: React.SyntheticEvent) => {
11	    const el = e.currentTarget as HTMLElement;
12	    window.clearTimeout(timer.current);
13	    timer.current = window.setTimeout(() => setRect(el.getBoundingClientRect()), 350);
14	  };
15	  const hide = () => { window.clearTimeout(timer.current); setRect(null); };
16	  useEffect(() => () => window.clearTimeout(timer.current), []);
17	  const child = cloneElement(children, {
18	    onMouseEnter: (e: any) => { show(e); children.props.onMouseEnter?.(e); },
19	    onMouseLeave: (e: any) => { hide(); children.props.onMouseLeave?.(e); },
20	    onMouseDown: (e: any) => { hide(); children.props.onMouseDown?.(e); },
21	    onFocus: (e: any) => { children.props.onFocus?.(e); },
22	    onBlur: (e: any) => { hide(); children.props.onBlur?.(e); },
23	  });
24	  let style: React.CSSProperties = {};
25	  if (rect) {
26	    const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
27	    if (side === 'top') style = { left: cx, top: rect.top - 8, transform: 'translate(-50%, -100%)' };
28	    if (side === 'bottom') style = { left: cx, top: rect.bottom + 8, transform: 'translate(-50%, 0)' };
29	    if (side === 'left') style = { left: rect.left - 8, top: cy, transform: 'translate(-100%, -50%)' };
30	    if (side === 'right') style = { left: rect.right + 8, top: cy, transform: 'translate(0, -50%)' };
31	  }
32	  return (
33	    <>
34	      {child}
35	      {rect && createPortal(
36	        <div className="nxw-tip pointer-events-none fixed z-[1000] max-w-[280px] rounded-md border border-line bg-panel2/95 px-2.5 py-1.5 text-xs text-ink shadow-[0_8px_30px_rgba(0,0,0,.6)] backdrop-blur" style={style}>
37	          {label}
38	          {kbd && <span className="ml-2 rounded border border-line px-1 font-mono text-[10px] text-muted">{kbd}</span>}
39	        </div>,
40	        document.body,
41	      )}
42	    </>
43	  );
44	}
