47	export function Popover({
48	  open, onClose, anchor, children, side = 'top', align = 'start', className,
49	}: {
50	  open: boolean; onClose: () => void; anchor: HTMLElement | null; children: ReactNode;
51	  side?: 'top' | 'bottom'; align?: 'start' | 'end'; className?: string;
52	}) {
53	  const ref = useRef<HTMLDivElement>(null);
54	  const [pos, setPos] = useState<React.CSSProperties>({ visibility: 'hidden' });
55	  useLayoutEffect(() => {
56	    if (!open || !anchor) return;
57	    const place = () => {
58	      const r = anchor.getBoundingClientRect();
59	      const el = ref.current; const w = el?.offsetWidth ?? 220; const h = el?.offsetHeight ?? 0;
60	      let left = align === 'start' ? r.left : r.right - w;
61	      left = Math.max(8, Math.min(left, window.innerWidth - w - 8));
62	      let top = side === 'top' ? r.top - h - 6 : r.bottom + 6;
63	      if (side === 'top' && top < 8) top = r.bottom + 6;
64	      if (side === 'bottom' && top + h > window.innerHeight - 8) top = Math.max(8, r.top - h - 6);
65	      setPos({ left, top });
66	    };
67	    place();
68	    const ro = new ResizeObserver(place); if (ref.current) ro.observe(ref.current);
69	    window.addEventListener('resize', place);
70	    return () => { ro.disconnect(); window.removeEventListener('resize', place); };
71	  }, [open, anchor, side, align]);
72	  useEffect(() => {
73	    if (!open) return;
74	    const onDown = (e: MouseEvent) => {
75	      if (ref.current?.contains(e.target as Node) || anchor?.contains(e.target as Node)) return;
76	      onClose();
77	    };
78	    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.stopPropagation(); onClose(); } };
79	    document.addEventListener('mousedown', onDown);
80	    document.addEventListener('keydown', onKey, true);
81	    return () => { document.removeEventListener('mousedown', onDown); document.removeEventListener('keydown', onKey, true); };
82	  }, [open, anchor, onClose]);
83	  if (!open) return null;
84	  return createPortal(
85	    <div ref={ref} style={pos} className={clsx('nxw-pop fixed z-[900] rounded-xl border border-line bg-panel/95 p-1 shadow-[0_18px_50px_rgba(0,0,0,.7),0_0_0_1px_rgba(255,62,138,.06)] backdrop-blur-md', className)}>
86	      {children}
87	    </div>,
88	    document.body,
89	  );
90	}
