175	/** Inline editable text: renders an input that commits on Enter/blur and cancels on Esc. */
176	export function InlineInput({ initial, onCommit, onCancel, className, placeholder }: {
177	  initial: string; onCommit: (v: string) => void; onCancel: () => void; className?: string; placeholder?: string;
178	}) {
179	  const [v, setV] = useState(initial);
180	  const ref = useRef<HTMLInputElement>(null);
181	  const done = useRef(false);
182	  useEffect(() => {
183	    const el = ref.current; if (!el) return;
184	    el.focus();
185	    const dot = initial.lastIndexOf('.');
186	    el.setSelectionRange(0, dot > 0 ? dot : initial.length);
187	  }, [initial]);
188	  const commit = useCallback(() => {
189	    if (done.current) return; done.current = true;
190	    const t = v.trim();
191	    if (t && t !== initial) onCommit(t); else onCancel();
192	  }, [v, initial, onCommit, onCancel]);
193	  return (
194	    <input
195	      ref={ref} value={v} placeholder={placeholder} onChange={(e) => setV(e.target.value)} onBlur={commit}
196	      onKeyDown={(e) => {
197	        e.stopPropagation();
198	        if (e.key === 'Enter') commit();
199	        if (e.key === 'Escape') { done.current = true; onCancel(); }
200	      }}
201	      onClick={(e) => e.stopPropagation()}
202	      className={clsx('w-full rounded border border-pink/50 bg-bg px-1.5 py-0.5 text-[13px] text-ink outline-none shadow-[0_0_0_3px_rgba(255,62,138,.12)]', className)}
203	    />
204	  );
205	}
