207	export function useMediaQuery(q: string) {
208	  const [m, setM] = useState(() => typeof window !== 'undefined' && window.matchMedia(q).matches);
209	  useEffect(() => {
210	    const mq = window.matchMedia(q);
211	    const fn = () => setM(mq.matches);
212	    fn(); mq.addEventListener('change', fn);
213	    return () => mq.removeEventListener('change', fn);
214	  }, [q]);
215	  return m;
216	}
