14	function useIconSprites(onReady: (m: Map<string, HTMLImageElement>) => void) {
15	  const ref = useRef<HTMLDivElement>(null);
16	  useEffect(() => {
17	    const host = ref.current;
18	    if (!host) return;
19	    const map = new Map<string, HTMLImageElement>();
20	    host.querySelectorAll<SVGSVGElement>('svg[data-icon]').forEach((svg) => {
21	      const name = svg.getAttribute('data-icon')!;
22	      const clone = svg.cloneNode(true) as SVGSVGElement;
23	      clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
24	      clone.setAttribute('width', '64'); clone.setAttribute('height', '64');
25	      const img = new Image();
26	      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(clone.outerHTML);
27	      map.set(name, img);
28	    });
29	    onReady(map);
30	  }, []); // eslint-disable-line react-hooks/exhaustive-deps
31	  return (
32	    <div ref={ref} aria-hidden className="hidden">
33	      {Object.entries(PROJECT_ICONS).map(([n, I]) => <I key={n} data-icon={n} color="#f6e9f0" strokeWidth={1.75} />)}
