374	  constructor(canvas: HTMLCanvasElement, cb: EngineCallbacks = {}) {
375	    this.canvas = canvas;
376	    this.ctx = canvas.getContext('2d', { alpha: false })!;
377	    this.cb = cb;
378	    this.reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
379	    this.sim = forceSimulation<SimNode>([]).stop();
380	    this.ro = new ResizeObserver(() => this.resize());
381	    this.ro.observe(canvas);
