389	  // ---------- public API ----------
390	  setIcons(map: Map<string, HTMLImageElement>) { this.icons = map; this.dirty = true; }
391	  setHoverElement(el: HTMLElement | null) { this.hoverEl = el; }
392	  setFocus(id: string | null) { this.focusId = id; this.dirty = true; }
393	
394	  setGraph(g: Graph) {
395	    const prev = this.byId;
396	    const nodes: SimNode[] = [];
397	    const core = prev.get('core') || this.mkNode('core', 'core', undefined);
398	    core.fx = 0; core.fy = 0; core.x = 0; core.y = 0;
399	    nodes.push(core);
400	
401	    const projects = g.nodes.filter((n) => n.id !== 'core');
402	    // most recently active → inner rings
403	    const sorted = [...projects].sort((a, b) => (Date.parse(b.lastActiveAt || '') || 0) - (Date.parse(a.lastActiveAt || '') || 0));
404	    let ring = 1, inRing = 0, cap = 6;
405	    const rings: { n: GraphNode; ring: number; idx: number; cap: number }[] = [];
406	    for (const n of sorted) {
407	      rings.push({ n, ring, idx: inRing, cap });
408	      if (++inRing >= cap) { ring++; inRing = 0; cap = 6 + (ring - 1) * 5; }
409	    }
410	    const ringR = (i: number) => 170 + (i - 1) * 120;
411	    const ringCount = new Map<number, number>();
412	    for (const x of rings) ringCount.set(x.ring, (ringCount.get(x.ring) || 0) + 1);
413	    for (const { n, ring: ri, idx } of rings) {
414	      let sn = prev.get(n.id);
415	      const count = ringCount.get(ri) || 1;
416	      if (!sn) {
417	        sn = this.mkNode(n.id, 'project', n);
418	        const off = (hashStr('ring' + ri) % 1000) / 1000 * TAU;
419	        const a = off + (idx / count) * TAU;
420	        const saved = this.positions[n.id];
421	        if (saved) { sn.x = saved.x; sn.y = saved.y; sn.fx = saved.x; sn.fy = saved.y; sn.pinned = true; }
422	        else { sn.x = Math.cos(a) * ringR(ri); sn.y = Math.sin(a) * ringR(ri); }
423	      }
424	      sn.data = n; sn.label = n.name; sn.color = n.color || '#ff3e8a'; sn.rgb = hexToRgb(sn.color);
425	      sn.status = n.status || 'idle'; sn.activity = Math.max(0, Math.min(1, n.activity || 0));
426	      sn.ringR = ringR(ri);
427	      sn.r = 15 + sn.activity * 5;
428	      nodes.push(sn);
429	    }
430	    const maxRing = rings.length ? rings[rings.length - 1].ring : 0;
431	    const ghost = prev.get('__ghost') || this.mkNode('__ghost', 'ghost', undefined);
432	    ghost.ringR = ringR(maxRing + 1) - (maxRing ? 40 : 30);
433	    if (!prev.get('__ghost')) {
434	      const a = -Math.PI * 0.25;
435	      ghost.x = Math.cos(a) * ghost.ringR; ghost.y = Math.sin(a) * ghost.ringR;
436	    }
437	    nodes.push(ghost);
438	
439	    this.nodes = nodes;
440	    this.byId = new Map(nodes.map((n) => [n.id, n]));
441	    this.outerR = ringR(Math.max(1, maxRing)) + 150;
442	
443	    // strands: core spokes + graph links
444	    const strands: Strand[] = [];
445	    const seen = new Set<string>();
446	    const add = (a: SimNode | undefined, b: SimNode | undefined, kind: string, core: boolean) => {
447	      if (!a || !b || a === b) return;
448	      const key = a.id < b.id ? a.id + '|' + b.id : b.id + '|' + a.id;
449	      if (seen.has(key)) return; seen.add(key);
450	      strands.push({ a, b, kind, core, phase: (hashStr(key) % 1000) / 1000 * TAU, len: 0, cx: 0, cy: 0 });
451	    };
452	    for (const n of nodes) if (n.kind === 'project') add(core, n, 'core', true);
453	    add(core, ghost, 'ghost', true);
454	    for (const l of g.links) {
455	      const s = typeof l.source === 'string' ? l.source : (l.source as any)?.id;
456	      const t = typeof l.target === 'string' ? l.target : (l.target as any)?.id;
457	      add(this.byId.get(s), this.byId.get(t), l.kind, s === 'core' || t === 'core');
458	    }
459	    this.strands = strands;
460	    this.nodeStrands = new Map();
461	    for (const s of strands) {
462	      for (const n of [s.a, s.b]) { const arr = this.nodeStrands.get(n.id) || []; arr.push(s); this.nodeStrands.set(n.id, arr); }
463	    }
464	    this.pulses = this.pulses.filter((p) => strands.includes(p.s));
465	    this.buildWeb();
466	
467	    // forces
468	    const projLinks = strands.filter((s) => !s.core).map((s) => ({ source: s.a, target: s.b }));
469	    this.sim = forceSimulation<SimNode>(nodes)
470	      .force('charge', forceManyBody<SimNode>().strength((n) => (n.kind === 'core' ? -400 : -90)).distanceMax(400))
471	      .force('collide', forceCollide<SimNode>().radius((n) => (n.kind === 'core' ? CORE_R + 50 : n.r + 28)).strength(0.9))
472	      .force('radial', forceRadial<SimNode>((n) => n.ringR, 0, 0).strength((n) => (n.kind === 'core' ? 0 : 0.6)))
473	      .force('link', forceLink<SimNode, SimulationLinkDatum<SimNode>>(projLinks).distance(150).strength(0.03))
474	      .alphaDecay(0.035)
475	      .stop();
476	    const fresh = nodes.some((n) => !prev.has(n.id));
477	    if (fresh) { this.sim.alpha(1); for (let i = 0; i < 220; i++) this.sim.tick(); }
478	    this.sim.alpha(this.reduced ? 0 : 0.15);
479	    if (prev.size === 0) this.fit(true);
480	    this.dirty = true;
481	  }
482	
483	  /** Update one project's status (from run_status). */
484	  setStatus(projectId: string, status: NodeStatus) {
485	    const n = this.byId.get(projectId);
486	    if (!n || n.kind !== 'project') return;
487	    if (n.status !== status && status === 'running') n.flash = 1;
488	    n.status = status; this.dirty = true;
489	  }
