491	  /** graph_pulse: fire light along all strands of a node. */
492	  pulse(projectId: string, intensity = 0.5) {
493	    const n = this.byId.get(projectId);
494	    if (!n) return;
495	    n.flash = Math.min(1.5, n.flash + 0.6 + intensity * 0.4);
496	    n.activity = Math.min(1, n.activity + intensity * 0.05);
497	    if (this.reduced) { this.dirty = true; return; }
498	    n.ripples.push(0);
499	    if (n.ripples.length > 4) n.ripples.shift();
500	    const strands = this.nodeStrands.get(n.id) || [];
501	    const count = 1 + Math.round(intensity * 4);
502	    for (const s of strands) for (let i = 0; i < count; i++) {
503	      this.spawn(s, s.a === n ? 1 : -1, n.rgb, 1 + intensity, i * -0.08);
504	    }
505	  }
