509	  fit(instant = false) {
510	    const pad = 0.9;
511	    const k = Math.max(0.25, Math.min(1.6, (Math.min(this.W, this.H) / 2 / (this.outerR - 60)) * pad));
512	    this.animateTo({ x: 0, y: 0, k }, instant ? 0 : 600);
513	  }
