515	  resetLayout() {
516	    this.positions = {}; savePositions({});
517	    for (const n of this.nodes) if (n.kind !== 'core') { n.fx = null; n.fy = null; n.pinned = false; }
518	    this.sim.alpha(0.9);
519	    if (this.reduced) for (let i = 0; i < 200; i++) this.sim.tick();
520	    this.dirty = true;
521	  }
