545	  // ---------- internals ----------
546	  private mkNode(id: string, kind: NodeKind, data?: GraphNode): SimNode {
547	    const color = kind === 'core' ? '#ff3e8a' : data?.color || '#ff3e8a';
548	    return {
549	      id, kind, data, r: kind === 'core' ? CORE_R : kind === 'ghost' ? 15 : 16, ringR: 0, color, rgb: hexToRgb(color),
550	      status: data?.status || 'idle', activity: data?.activity || 0, phase: (hashStr(id) % 1000) / 1000 * TAU,
551	      flash: 0, ripples: [], pinned: false, label: kind === 'ghost' ? 'New project' : data?.name || 'core', x: 0, y: 0,
552	    };
553	  }
