555	  private makeStars() {
556	    const rnd = mulberry(1337);
557	    this.stars = Array.from({ length: 240 }, () => ({ x: rnd() * 4000, y: rnd() * 4000, z: 0.04 + rnd() * rnd() * 0.35, tw: rnd() * TAU, s: rnd() < 0.08 ? 1.6 : rnd() < 0.4 ? 1.1 : 0.7 }));
558	  }
559	
560	  private buildWeb() {
561	    // Orb-web: radial spokes + sagging capture rings with slight organic jitter.
562	    const rnd = mulberry(424242);
563	    const spokes = 28;
564	    const R = this.outerR;
565	    const angles = Array.from({ length: spokes }, (_, i) => (i / spokes) * TAU + (rnd() - 0.5) * 0.08);
566	    const sp = new Path2D();
567	    for (const a of angles) { sp.moveTo(Math.cos(a) * 46, Math.sin(a) * 46); sp.lineTo(Math.cos(a) * R * 1.35, Math.sin(a) * R * 1.35); }
568	    this.spokePath = sp;
569	    const web = new Path2D();
570	    const gap = 46;
571	    for (let r = 64; r < R * 1.25; r += gap * (0.88 + rnd() * 0.24)) {
572	      const pts = angles.map((a) => { const rr = r * (0.97 + rnd() * 0.06); return [Math.cos(a) * rr, Math.sin(a) * rr, rr] as const; });
573	      web.moveTo(pts[0][0], pts[0][1]);
574	      for (let i = 0; i < spokes; i++) {
575	        const p = pts[i], q = pts[(i + 1) % spokes];
576	        const am = (angles[i] + (i === spokes - 1 ? angles[0] + TAU : angles[(i + 1) % spokes])) / 2;
577	        const sag = ((p[2] + q[2]) / 2) * 0.955;
578	        web.quadraticCurveTo(Math.cos(am) * sag, Math.sin(am) * sag, q[0], q[1]);
579	      }
580	    }
581	    this.webPath = web;
582	  }
