590	  private sprite(rgb: [number, number, number]) {
591	    const key = rgb.join(',');
592	    let c = this.sprites.get(key);
593	    if (!c) {
594	      c = document.createElement('canvas'); c.width = c.height = 64;
595	      const g = c.getContext('2d')!;
596	      const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
597	      gr.addColorStop(0, `rgba(255,240,248,1)`);
598	      gr.addColorStop(0.12, rgba(rgb, 0.95));
599	      gr.addColorStop(0.4, rgba(rgb, 0.28));
600	      gr.addColorStop(1, rgba(rgb, 0));
601	      g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
602	      this.sprites.set(key, c);
603	    }
604	    return c;
605	  }
606	  private haloSprite(rgb: [number, number, number]) {
607	    const key = 'h' + rgb.join(',');
608	    let c = this.sprites.get(key);
609	    if (!c) {
610	      c = document.createElement('canvas'); c.width = c.height = 128;
611	      const g = c.getContext('2d')!;
612	      const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
613	      gr.addColorStop(0, rgba(rgb, 0.55)); gr.addColorStop(0.35, rgba(rgb, 0.18)); gr.addColorStop(1, rgba(rgb, 0));
614	      g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
615	      this.sprites.set(key, c);
616	    }
617	    return c;
618	  }
