620	  private resize() {
621	    const r = this.canvas.getBoundingClientRect();
622	    this.dpr = Math.min(2, window.devicePixelRatio || 1);
623	    this.W = Math.max(1, r.width); this.H = Math.max(1, r.height);
624	    this.canvas.width = Math.round(this.W * this.dpr);
625	    this.canvas.height = Math.round(this.H * this.dpr);
626	    this.bgCache = null;
627	    this.dirty = true;
628	    if (this.reduced && this.running) this.frame(performance.now());
629	  }
