631	  private onVis = () => { if (document.hidden) this.stop(); else this.start(); };
632	  private start() {
633	    if (this.running || this.disposed) return;
634	    this.running = true; this.last = performance.now();
635	    this.raf = requestAnimationFrame(this.loop);
636	  }
