644	  private animateTo(to: { x: number; y: number; k: number }, dur: number, done?: () => void) {
645	    if (dur <= 0 || this.reduced) {
646	      this.cam = { ...to }; this.target = { ...to }; this.tween = null; this.dirty = true; done?.(); return;
647	    }
648	    this.tween = { from: { ...this.cam }, to, t0: performance.now(), dur, done };
649	    this.target = { ...to };
650	  }
651	
652	  private zoomAt(sx: number, sy: number, f: number) {
653	    const k0 = this.target.k;
654	    const k1 = Math.max(0.2, Math.min(5, k0 * f));
655	    // keep world point under cursor fixed (relative to target camera)
656	    const wx = (sx - this.W / 2) / k0 + this.target.x;
657	    const wy = (sy - this.H / 2) / k0 + this.target.y;
658	    this.target = { k: k1, x: wx - (sx - this.W / 2) / k1, y: wy - (sy - this.H / 2) / k1 };
659	    this.tween = null;
660	    if (this.reduced) this.cam = { ...this.target };
661	    this.dirty = true;
662	  }
663	
664	  private toWorld(sx: number, sy: number) {
665	    return { x: (sx - this.W / 2) / this.cam.k + this.cam.x, y: (sy - this.H / 2) / this.cam.k + this.cam.y };
666	  }
667	
668	  private hit(sx: number, sy: number): SimNode | null {
669	    const w = this.toWorld(sx, sy);
670	    let best: SimNode | null = null, bd = Infinity;
671	    for (const n of this.nodes) {
672	      const d = Math.hypot(n.x - w.x, n.y - w.y);
673	      const lim = n.r + 8 / this.cam.k;
674	      if (d < lim && d < bd) { bd = d; best = n; }
675	    }
676	    return best;
677	  }
