679	  private setHover(n: SimNode | null) {
680	    if (n === this.hovered) return;
681	    this.hovered = n;
682	    this.canvas.style.cursor = n && n.kind !== 'core' ? 'pointer' : this.drag?.mode === 'pan' ? 'grabbing' : 'grab';
683	    this.cb.onHover?.(n && n.kind === 'project' ? n : null);
684	    this.dirty = true;
685	  }
