687	  // ----- events -----
688	  private bind() {
689	    const c = this.canvas;
690	    c.addEventListener('pointerdown', this.onDown);
691	    window.addEventListener('pointermove', this.onMove);
692	    window.addEventListener('pointerup', this.onUp);
693	    window.addEventListener('pointercancel', this.onUp);
694	    c.addEventListener('wheel', this.onWheel, { passive: false });
695	    c.addEventListener('dblclick', this.onDbl);
696	    c.addEventListener('pointerleave', this.onLeave);
697	    c.style.cursor = 'grab';
698	    c.style.touchAction = 'none';
699	  }
700	  private unbind() {
701	    const c = this.canvas;
702	    c.removeEventListener('pointerdown', this.onDown);
703	    window.removeEventListener('pointermove', this.onMove);
704	    window.removeEventListener('pointerup', this.onUp);
705	    window.removeEventListener('pointercancel', this.onUp);
706	    c.removeEventListener('wheel', this.onWheel);
707	    c.removeEventListener('dblclick', this.onDbl);
708	    c.removeEventListener('pointerleave', this.onLeave);
709	  }
710	  private local(e: { clientX: number; clientY: number }) {
711	    const r = this.canvas.getBoundingClientRect();
712	    return { x: e.clientX - r.left, y: e.clientY - r.top };
713	  }
714	  private onDown = (e: PointerEvent) => {
715	    const p = this.local(e);
716	    this.pointers.set(e.pointerId, p);
717	    try { this.canvas.setPointerCapture(e.pointerId); } catch { /* noop */ }
718	    if (this.pointers.size === 2) {
719	      const [a, b] = [...this.pointers.values()];
720	      this.drag = { mode: 'pinch', sx: (a.x + b.x) / 2, sy: (a.y + b.y) / 2, moved: true, camX: this.cam.x, camY: this.cam.y, dist: Math.hypot(a.x - b.x, a.y - b.y), k0: this.target.k };
721	      return;
722	    }
723	    const n = this.hit(p.x, p.y);
724	    this.tween = null;
725	    if (n && n.kind !== 'core') this.drag = { mode: 'node', node: n, sx: p.x, sy: p.y, moved: false, camX: 0, camY: 0 };
726	    else { this.drag = { mode: 'pan', sx: p.x, sy: p.y, moved: false, camX: this.target.x, camY: this.target.y }; this.canvas.style.cursor = 'grabbing'; }
727	  };
728	  private onMove = (e: PointerEvent) => {
729	    const p = this.local(e);
730	    if (this.pointers.has(e.pointerId)) this.pointers.set(e.pointerId, p);
731	    const d = this.drag;
732	    if (!d) {
733	      if (e.target === this.canvas) this.setHover(this.hit(p.x, p.y));
734	      return;
735	    }
736	    if (d.mode === 'pinch' && this.pointers.size >= 2) {
737	      const [a, b] = [...this.pointers.values()];
738	      const dist = Math.hypot(a.x - b.x, a.y - b.y);
739	      const f = dist / (d.dist || dist);
740	      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
741	      const k1 = Math.max(0.2, Math.min(5, (d.k0 || 1) * f));
742	      this.zoomAt(mx, my, k1 / this.target.k);
743	      this.cam = { ...this.target };
744	      return;
745	    }
