791	  // ----- frame -----
792	  private frame(now: number) {
793	    const dt = Math.min(0.05, (now - this.last) / 1000);
794	    this.last = now;
795	    const animating = !this.reduced;
796	    if (animating) this.time += dt;
797	
798	    // simulation
799	    if (this.sim.alpha() > this.sim.alphaMin() || (this.sim as any).alphaTarget?.() > 0) {
800	      this.sim.tick(); this.dirty = true;
801	    }
802	
803	    // camera
804	    if (this.tween) {
805	      const u = Math.min(1, (now - this.tween.t0) / this.tween.dur);
806	      const e = u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
807	      const { from, to } = this.tween;
808	      // zoom interpolated geometrically
809	      this.cam.k = from.k * Math.pow(to.k / from.k, e);
810	      this.cam.x = from.x + (to.x - from.x) * e; this.cam.y = from.y + (to.y - from.y) * e;
811	      this.dirty = true;
812	      if (u >= 1) { const d = this.tween.done; this.tween = null; d?.(); }
813	    } else {
814	      const f = 1 - Math.exp(-dt * 12);
815	      const dx = this.target.x - this.cam.x, dy = this.target.y - this.cam.y, dk = this.target.k - this.cam.k;
816	      if (Math.abs(dx) + Math.abs(dy) > 0.01 || Math.abs(dk) > 0.0005) {
817	        this.cam.x += dx * f; this.cam.y += dy * f; this.cam.k += dk * f; this.dirty = true;
818	      }
819	    }
820	
821	    if (animating) {
822	      this.updatePulses(dt);
823	      for (const n of this.nodes) {
824	        if (n.flash > 0) n.flash = Math.max(0, n.flash - dt * 0.9);
825	        n.ripples = n.ripples.map((r) => r + dt).filter((r) => r < 1.6);
826	      }
827	      this.dirty = true;
828	    }
829	    if (!this.dirty) return;
830	    this.dirty = false;
831	    this.draw();
832	  }
