834	  private updatePulses(dt: number) {
835	    // ambient + status-driven spawning
836	    const density = Math.min(1, 120 / Math.max(1, this.strands.length));
837	    for (const s of this.strands) {
838	      if (s.kind === 'ghost') continue;
839	      const run = (s.a.status === 'running' ? 1 : 0) + (s.b.status === 'running' ? 1 : 0);
840	      const act = (s.a.activity + s.b.activity) / 2;
841	      const rate = ((s.core ? 0.035 : 0.02) + act * 0.08) * density + run * 1.1 * Math.max(0.35, density);
842	      if (Math.random() < rate * dt) {
843	        const src = s.b.status === 'running' ? s.b : s.a.status === 'running' ? s.a : Math.random() < 0.5 ? s.a : s.b;
844	        const rgb = src.kind === 'core' ? HOT : src.rgb;
845	        this.spawn(s, src === s.a ? 1 : -1, rgb, run ? 1.15 : 0.8);
846	      }
847	    }
848	    const out: Pulse[] = [];
849	    for (const p of this.pulses) {
850	      p.t += p.speed * dt;
851	      if (p.t < 1.12) out.push(p);
852	      else {
853	        const dest = p.dir === 1 ? p.s.b : p.s.a;
854	        dest.flash = Math.min(1.2, dest.flash + 0.12 * p.size);
855	      }
856	    }
857	    this.pulses = out;
858	  }
