860	  private strandGeom(s: Strand) {
861	    const ax = s.a.x, ay = s.a.y, bx = s.b.x, by = s.b.y;
862	    const len = Math.hypot(bx - ax, by - ay);
863	    // catenary-ish sag (gravity +y) with a gentle sway
864	    const sway = this.reduced ? 0 : Math.sin(this.time * 0.7 + s.phase) * 0.012;
865	    const sag = len * (0.07 + sway);
866	    const nx = -(by - ay) / (len || 1), ny = (bx - ax) / (len || 1);
867	    // pick the normal that points "down"-ish, blend with pure gravity
868	    const sgn = ny >= 0 ? 1 : -1;
869	    s.cx = (ax + bx) / 2 + (nx * sgn * 0.6) * sag;
870	    s.cy = (ay + by) / 2 + (ny * sgn * 0.6 + 0.4) * sag;
871	    s.len = len;
872	  }
