export class FakeClaudebox {
  server: http.Server;
  url = '';
  runs = new Map<string, FakeRun>();
  aborts: string[] = [];
  bodies: Record<string, unknown>[] = [];
  previewRunning = false;

  constructor() {
    this.server = http.createServer((req, res) => void this.handle(req, res));
  }

  async start() {
    await new Promise<void>((r) => this.server.listen(0, '127.0.0.1', r));
    this.url = `http://127.0.0.1:${(this.server.address() as AddressInfo).port}`;
  }
  async stop() {
    this.server.closeAllConnections();
    await new Promise<void>((r) => this.server.close(() => r()));
  }

  private writeEvent(res: http.ServerResponse, seq: number, e: FakeEvent) {
    res.write(`id: ${seq}\nevent: ${e.event}\ndata: ${JSON.stringify(e.data)}\n\n`);
  }

  private async handle(req: http.IncomingMessage, res: http.ServerResponse) {
    if (req.headers.authorization !== 'Bearer test-key') {
      res.writeHead(401).end('{"error":"unauthorized"}');
      return;
    }
    const url = new URL(req.url!, 'http://x');
    let raw = '';
    for await (const c of req) raw += c;
    const body = raw ? (JSON.parse(raw) as Record<string, unknown>) : {};
    if (req.method === 'POST' && url.pathname === '/v2/run') {
      this.bodies.push(body);
      const prompt = String(body.prompt);
      if (prompt.includes('[fail]')) {
        res.writeHead(500, { 'content-type': 'application/json' }).end('{"error":"boom"}');
        return;
      }
      const run: FakeRun = { runId: String(body.runId), body, events: scriptFor(prompt), sent: 0, done: false, waiters: new Set(), hold: prompt.includes('[hold]') };
      this.runs.set(run.runId, run);
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      const dropAt = prompt.includes('[drop]') ? 7 : -1;
      for (let i = 0; i < run.events.length; i++) {
        if (run.hold && i === 1) {
          // stay open until aborted
          run.waiters.add(res);
          return;
        }
        if (i === dropAt) {
          run.sent = i;
          res.destroy(); // simulate connection loss mid-run
          return;
        }
        this.writeEvent(res, i + 1, run.events[i]!);
        await new Promise((r) => setTimeout(r, 2));
      }
      run.done = true;
      res.end();
      return;
    }
    const m = /^\/v2\/run\/([^/]+)\/events$/.exec(url.pathname);
    if (req.method === 'GET' && m) {
      const run = this.runs.get(decodeURIComponent(m[1]!));
      if (!run) {
        res.writeHead(404).end('{"error":"not found"}');
        return;
      }
      const from = Number(url.searchParams.get('fromSeq') ?? '1');
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      // replay from fromSeq (inclusive) to the end, including a duplicate of the previous event to test dedupe
      for (let i = Math.max(0, from - 2); i < run.events.length; i++) this.writeEvent(res, i + 1, run.events[i]!);
      run.done = true;
      res.end();
      return;
    }
    if (req.method === 'POST' && url.pathname === '/v2/abort') {
      this.aborts.push(String(body.runId));
      const run = this.runs.get(String(body.runId));
      if (run) {
        for (const w of run.waiters) {
          this.writeEvent(w, 2, { event: 'error', data: { message: 'aborted' } });
          this.writeEvent(w, 3, { event: 'done', data: { exitCode: null } });
          w.end();
        }
        run.waiters.clear();
      }
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"ok":true}');
      return;
    }
    if (url.pathname === '/v2/preview/start') {
      this.previewRunning = true;
      res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ running: true, port: body.port, pid: 42 }));
      return;
    }
    if (url.pathname === '/v2/preview/stop') {
      this.previewRunning = false;
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"ok":true}');
      return;
    }
    if (url.pathname === '/v2/preview/status') {
      res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ projectSlug: url.searchParams.get('projectSlug'), running: this.previewRunning, managed: true, listening: this.previewRunning, port: Number(url.searchParams.get('port')) || null, pid: 42, kind: 'process', command: 'npm run dev', logTail: ['line1', 'line2'] }));
      return;
    }
    if (url.pathname === '/health') {
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"status":"ok","version":"test"}');
      return;
    }
    res.writeHead(404).end();
  }
}

