"use strict";
const assert = require("node:assert/strict");
const test = require("node:test");
const fs = require("fs");
const os = require("os");
const path = require("path");
const { execFileSync } = require("child_process");
const { GitManager, handleGit, GitError } = require("../lib/git");

const TMP = fs.mkdtempSync(path.join(os.tmpdir(), "claudebox-git-"));
const git = new GitManager({ projectsDir: TMP });
const sh = (cwd, ...args) => execFileSync("git", args, { cwd, encoding: "utf8" }).trim();
const write = (p, s) => {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, s);
};

test.after(() => fs.rmSync(TMP, { recursive: true, force: true }));

test("ensure: init + initial snapshot + .gitignore, idempotent", async () => {
  const dir = path.join(TMP, "alpha");
  write(path.join(dir, "index.html"), "<h1>hi</h1>\n");
  write(path.join(dir, "node_modules", "x", "index.js"), "junk");
  const r = await git.ensure("alpha");
  assert.equal(r.mainBranch, "main");
  assert.equal(r.initialized, true);
  assert.match(r.head, /^[0-9a-f]{40}$/);
  const files = sh(dir, "ls-files").split("\n");
  assert.deepEqual(files.sort(), [".gitignore", "index.html"]);
  assert.match(fs.readFileSync(path.join(dir, ".gitignore"), "utf8"), /node_modules\n[\s\S]*__pycache__/);
  assert.equal(sh(dir, "config", "user.name"), "Nxeon");
  const again = await git.ensure("alpha");
  assert.equal(again.initialized, false);
  assert.equal(again.head, r.head);
});

test("ensure: adopts an existing repo and keeps its current branch as main", async () => {
  const dir = path.join(TMP, "legacy");
  write(path.join(dir, "a.txt"), "a\n");
  write(path.join(dir, ".gitignore"), "dist");
  sh(dir, "init", "-q", "-b", "master");
  sh(dir, "-c", "user.name=x", "-c", "user.email=x@y", "add", "-A");
  sh(dir, "-c", "user.name=x", "-c", "user.email=x@y", "commit", "-qm", "theirs");
  const head = sh(dir, "rev-parse", "HEAD");
  const r = await git.ensure("legacy");
  assert.equal(r.mainBranch, "master");
  assert.equal(r.adopted, true);
  assert.equal(r.head, head);
  const gi = fs.readFileSync(path.join(dir, ".gitignore"), "utf8");
  assert.ok(gi.startsWith("dist\nnode_modules\n"), gi);
  assert.equal(fs.readFileSync(path.join(dir, "a.txt"), "utf8"), "a\n");
});

test("branch lifecycle: create -> edit -> checkpoint -> diff -> merge -> remove", async () => {
  const repo = path.join(TMP, "alpha");
  const c = await git.createBranch("alpha", { branch: "feature/login", worktree: "feature_login", base: "main" });
  assert.equal(c.ok, true);
  const wt = path.join(TMP, ".branches", "alpha", "feature_login");
  assert.ok(fs.existsSync(path.join(wt, "index.html")));
  assert.equal(sh(wt, "branch", "--show-current"), "feature/login");

  write(path.join(wt, "index.html"), "<h1>hi</h1>\n<p>login</p>\n");
  write(path.join(wt, "login.js"), "export const x = 1;\n");
  // diff includes uncommitted + untracked files
  const d = await git.diff("alpha", { worktree: "feature_login", base: "main" });
  assert.deepEqual(d.files.map((f) => [f.path, f.status, f.additions, f.deletions]), [
    ["index.html", "modified", 1, 0],
    ["login.js", "added", 1, 0],
  ]);
  const fd = await git.fileDiff("alpha", { worktree: "feature_login", base: "main", path: "index.html" });
  assert.equal(fd.original, "<h1>hi</h1>\n");
  assert.equal(fd.modified, "<h1>hi</h1>\n<p>login</p>\n");
  assert.match(fd.patch, /\+<p>login<\/p>/);
  await assert.rejects(git.fileDiff("alpha", { worktree: "feature_login", base: "main", path: "../x" }), GitError);

  const cp = await git.checkpoint("alpha", { worktree: "feature_login", message: "nxeon: add login", expectBranch: "feature/login" });
  assert.match(cp.sha, /^[0-9a-f]{40}$/);
  assert.equal(cp.files, 2);
  assert.equal((await git.checkpoint("alpha", { worktree: "feature_login", message: "noop" })).sha, null);
  // main checkout is untouched
  assert.equal(fs.readFileSync(path.join(repo, "index.html"), "utf8"), "<h1>hi</h1>\n");

  const st = await git.status("alpha", { branches: [{ worktree: "feature_login", base: "main" }] });
  assert.equal(st.branches[0].ahead, 1);
  assert.equal(st.branches[0].behind, 0);
  assert.equal(st.branches[0].filesChanged, 2);

  // pending edits on main get checkpointed before the merge
  write(path.join(repo, "notes.md"), "main note\n");
  const m = await git.merge("alpha", { branch: "feature/login", worktree: "feature_login", into: "main" });
  assert.equal(m.ok, true);
  assert.equal(fs.readFileSync(path.join(repo, "login.js"), "utf8"), "export const x = 1;\n");
  assert.equal(sh(repo, "rev-list", "--parents", "-n1", "HEAD").split(" ").length, 3, "--no-ff merge commit");
  assert.equal(sh(repo, "status", "--porcelain"), "");

  const h = await git.history("alpha", { limit: 10 });
  assert.match(h.commits[0].message, /merge feature\/login into main/);
  assert.ok(h.commits.some((x) => x.message === "nxeon: add login"));

  const rm = await git.removeBranch("alpha", { branch: "feature/login", worktree: "feature_login" });
  assert.equal(rm.deletedRef, true);
  assert.ok(!fs.existsSync(wt));
  assert.equal(sh(repo, "branch", "--list", "feature/login"), "");
});

test("merge conflict: reported and the main tree is left clean", async () => {
  const repo = path.join(TMP, "alpha");
  await git.createBranch("alpha", { branch: "clash", worktree: "clash", base: "main" });
  const wt = path.join(TMP, ".branches", "alpha", "clash");
  write(path.join(wt, "index.html"), "<h1>branch</h1>\n");
  await git.checkpoint("alpha", { worktree: "clash", message: "nxeon: branch edit" });
  write(path.join(repo, "index.html"), "<h1>main</h1>\n");
  await git.checkpoint("alpha", { message: "nxeon: main edit", expectBranch: "main" });
  const head = sh(repo, "rev-parse", "HEAD");
  const m = await git.merge("alpha", { branch: "clash", worktree: "clash", into: "main" });
  assert.equal(m.ok, false);
  assert.deepEqual(m.conflicts, ["index.html"]);
  assert.equal(sh(repo, "rev-parse", "HEAD"), head);
  assert.equal(sh(repo, "status", "--porcelain"), "");
  assert.equal(fs.readFileSync(path.join(repo, "index.html"), "utf8"), "<h1>main</h1>\n");
  // rename keeps the worktree and moves its HEAD
  await git.renameBranch("alpha", { from: "clash", to: "clash-2" });
  assert.equal(sh(wt, "branch", "--show-current"), "clash-2");
  await assert.rejects(git.renameBranch("alpha", { from: "clash-2", to: "Bad Name" }), /Invalid branch name/);
  await git.removeBranch("alpha", { branch: "clash-2", worktree: "clash" });
});

test("checkpoint + revert (undo a run) and safety checks", async () => {
  const repo = path.join(TMP, "alpha");
  write(path.join(repo, "run.txt"), "made by run\n");
  const cp = await git.checkpoint("alpha", { message: "nxeon: make run.txt", expectBranch: "main" });
  write(path.join(repo, "other.txt"), "user edit\n");
  const r = await git.revert("alpha", { sha: cp.sha, expectBranch: "main" });
  assert.equal(r.ok, true);
  assert.match(r.checkpoint, /^[0-9a-f]{40}$/, "pending edits checkpointed first");
  assert.ok(!fs.existsSync(path.join(repo, "run.txt")));
  assert.equal(fs.readFileSync(path.join(repo, "other.txt"), "utf8"), "user edit\n");
  assert.match(sh(repo, "log", "-1", "--format=%s"), /^Revert "nxeon: make run.txt"/);
  const first = sh(repo, "rev-list", "--max-parents=0", "HEAD");
  await assert.rejects(git.revert("alpha", { sha: first }), /initial snapshot/);
  await assert.rejects(git.revert("alpha", { sha: "deadbeef" }), GitError);
  // checkpoint refuses to commit onto a branch someone switched to
  sh(repo, "checkout", "-q", "-b", "elsewhere");
  write(path.join(repo, "x.txt"), "x");
  const sk = await git.checkpoint("alpha", { message: "m", expectBranch: "main" });
  assert.equal(sk.skipped, "head_moved");
  sh(repo, "checkout", "-q", "main");
});

test("handleGit validates input", async () => {
  await assert.rejects(handleGit(git, "ensure", { projectSlug: "../x" }), /Invalid projectSlug/);
  await assert.rejects(handleGit(git, "branch/create", { projectSlug: "alpha", branch: "a--b", worktree: "a", base: "main" }), /Invalid branch name/);
  await assert.rejects(handleGit(git, "nope", { projectSlug: "alpha" }), /Unknown git operation/);
  await assert.rejects(handleGit(git, "diff", { projectSlug: "alpha", worktree: "missing", base: "main" }), /not found/);
});

