start=s.index("    app.get('/api/projects/graph', async (req) => {")
end=s.index("    app.get('/api/projects/:id', async (req) => {")
new='''    /**
     * Spider-web graph. Project nodes (kind 'project' | 'subproject' with parentId) + links (core / link / affinity / child).
     * `?satellites=1` adds branch and topic nodes (kind 'branch' | 'topic', parentId = project id) and their links;
     * without it the response keeps the legacy shape (plus the additive kind/parentId fields).
     */
    app.get('/api/projects/graph', async (req) => {
      const u = requireUser(req);
      const withSatellites = ['1', 'true'].includes(String((req.query as { satellites?: string }).satellites ?? ''));
      const projects = visibleProjects(ctx, u, false);
      const ids = projects.map(({ p }) => p.id);
      const idSet = new Set(ids);
      const running = new Set<string>();
      const runningBranch = new Set<string>(); // `${projectId}|${branch}`
      const lastStatus = new Map<string, string>();
      if (ids.length) {
        const ph = ids.map(() => '?').join(',');
        for (const r of db
          .prepare(`SELECT DISTINCT project_id, branch FROM runs WHERE status IN ('queued','running') AND project_id IN (${ph})`)
          .all(...ids) as { project_id: string; branch: string | null }[]) {
          running.add(r.project_id);
          if (r.branch) runningBranch.add(`${r.project_id}|${r.branch}`);
        }
        for (const r of db
          .prepare(
            `SELECT r.project_id, r.status FROM runs r JOIN (SELECT project_id, MAX(started_at) AS m FROM runs WHERE project_id IN (${ph}) GROUP BY project_id) x
             ON x.project_id = r.project_id AND x.m = r.started_at`,
          )
          .all(...ids) as { project_id: string; status: string }[])
          lastStatus.set(r.project_id, r.status);
      }
      const t = now();
      const activityOf = (last: number, isRunning: boolean) => (isRunning ? 1 : Math.round(Math.exp(-(t - last) / 3600_000 / 24) * 100) / 100);
      const nodes: Record<string, unknown>[] = [{ id: 'core', kind: 'core', name: 'Nxeon Core', color: '#ff3e8a', icon: 'cpu', status: running.size ? 'running' : 'idle', activity: running.size ? 1 : 0.3, lastActiveAt: null }];
      for (const { p } of projects) {
        const last = p.last_active_at ?? p.created_at;
        const isRunning = running.has(p.id);
        const child = !!p.parent_id && idSet.has(p.parent_id);
        nodes.push({
          id: p.id, kind: child ? 'subproject' : 'project', parentId: child ? p.parent_id : null,
          slug: p.slug, name: p.name, color: p.color, icon: p.icon, description: p.description.slice(0, 200),
          status: isRunning ? 'running' : lastStatus.get(p.id) === 'error' ? 'error' : 'idle',
          activity: activityOf(last, isRunning),
          lastActiveAt: iso(last),
        });
      }
      const links: { source: string; target: string; kind: string }[] = [];
      for (const { p } of projects) {
        if (p.parent_id && idSet.has(p.parent_id)) links.push({ source: p.parent_id, target: p.id, kind: 'child' });
        else links.push({ source: 'core', target: p.id, kind: 'core' });
      }
