import type { FastifyPluginAsync, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { requireProject, requireUser, type ProjectRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { ClaudeboxError, type PreviewStatusUpstream } from '../claudebox.js';
import { HttpError } from '../lib/errors.js';
import { branchParam, previewPath, type BranchRow } from '../lib/branches.js';

const startBody = z.object({ command: z.string().max(500).optional() }).optional();

/** Preview of the main checkout or of a branch worktree (`?branch=`): own port + /preview/<slug>--<dir>/. */
export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cb } = ctx;

    const shape = (p: ProjectRow, b: BranchRow | null, s: PreviewStatusUpstream) => ({
      running: !!s.running,
      port: s.port ?? (b ? b.preview_port : p.preview_port),
      pid: s.pid ?? null,
      logTail: Array.isArray(s.logTail) ? s.logTail.join('\n') : (s.logTail ?? ''),
      url: previewPath(p.slug, b),
      branch: b?.name ?? null,
      managed: s.managed ?? null,
      listening: s.listening ?? null,
      kind: s.kind ?? null,
      command: s.command ?? null,
      exitCode: s.exitCode ?? null,
    });
    async function status(p: ProjectRow, b: BranchRow | null) {
      const port = b ? b.preview_port : p.preview_port;
      try {
        return shape(p, b, await cb.previewStatus(p.slug, port, b?.dir));
      } catch (err) {
        return { running: false, port, pid: null, logTail: '', url: previewPath(p.slug, b), branch: b?.name ?? null, error: (err as Error).message };
      }
    }
    const upstreamErr = (err: unknown) => {
      const code = err instanceof ClaudeboxError && err.statusCode < 500 ? (err.statusCode === 401 ? 502 : err.statusCode) : 502;
      return new HttpError(code, 'preview_failed', (err as Error).message);
    };
    const target = (req: FastifyRequest, min: 'viewer' | 'editor') => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, min);
      return { project, branch: branchParam(db, project, (req.query as { branch?: string }).branch) };
    };
    const broadcast = (p: ProjectRow, b: BranchRow | null, running: boolean, port: number | null) =>
      ctx.hub.broadcastProject(p.id, { t: 'preview_status', projectId: p.id, running, port, branch: b?.name ?? null });

    app.get('/api/projects/:id/preview/status', async (req) => {
      const { project, branch } = target(req, 'viewer');
      return status(project, branch);
    });

    app.post('/api/projects/:id/preview/start', async (req) => {
      const { project, branch } = target(req, 'editor');
      const body = startBody.parse(req.body ?? {});
      let s;
      try {
        s = shape(project, branch, await cb.previewStart(project.slug, branch ? branch.preview_port : project.preview_port, body?.command || project.preview_command, branch?.dir));
      } catch (err) {
        throw upstreamErr(err);
      }
      ctx.audit(req, 'preview_start', project.id, branch ? { branch: branch.name } : null);
      broadcast(project, branch, s.running, s.port);
      return s;
    });

    app.post('/api/projects/:id/preview/stop', async (req) => {
      const { project, branch } = target(req, 'editor');
      try {
        await cb.previewStop(project.slug, branch ? branch.preview_port : project.preview_port, branch?.dir);
      } catch (err) {
        throw upstreamErr(err);
      }
      ctx.audit(req, 'preview_stop', project.id, branch ? { branch: branch.name } : null);
      const s = await status(project, branch);
      broadcast(project, branch, s.running, s.port);
      return s;
    });
  };
EOF
