import type { FastifyPluginAsync } from 'fastify';
import crypto from 'node:crypto';
import { z } from 'zod';
import { requireProject, requireUser } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { iso, now } from '../db.js';
import { notFound } from '../lib/errors.js';

const TOPIC_COLORS = ['#ff6fae', '#ff8a5c', '#b14bff', '#3dffb5', '#ffc857', '#5ce1ff', '#ff4d6d', '#ff3e8a'];
const colorSchema = z.string().regex(/^#[0-9a-fA-F]{6}$/, 'color must be #rrggbb');
const createBody = z.object({ name: z.string().trim().min(1).max(60), color: colorSchema.optional() });
const patchBody = z.object({ name: z.string().trim().min(1).max(60).optional(), color: colorSchema.optional(), sort: z.number().int().min(0).max(100_000).optional() });

export interface TopicRow { id: string; project_id: string; name: string; color: string; sort: number; created_at: number }
export const topicDTO = (t: TopicRow & { n?: number }) => ({
  id: t.id, projectId: t.project_id, name: t.name, color: t.color, sort: t.sort, createdAt: iso(t.created_at)!,
  ...(t.n != null ? { conversations: t.n } : {}),
});

/** Topic groups: lightweight per-project grouping of conversations (deleting one ungroups its conversations). */
export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db } = ctx;
    const changed = (projectId: string) => ctx.hub.broadcastProject(projectId, { t: 'project_changed', projectId, what: 'topics' });
    const loadTopic = (id: string) => {
      const t = db.prepare(`SELECT * FROM topics WHERE id = ?`).get(id) as TopicRow | undefined;
      if (!t) throw notFound('Topic not found');
      return t;
    };

    app.get('/api/projects/:id/topics', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'viewer');
      return (db
        .prepare(`SELECT t.*, (SELECT COUNT(*) FROM conversations c WHERE c.topic_id = t.id) AS n FROM topics t WHERE t.project_id = ? ORDER BY t.sort, t.created_at`)
        .all(project.id) as (TopicRow & { n: number })[]).map(topicDTO);
    });

    app.post('/api/projects/:id/topics', async (req, reply) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'editor');
      const body = createBody.parse(req.body ?? {});
      const count = (db.prepare(`SELECT COUNT(*) AS n, COALESCE(MAX(sort), -1) AS m FROM topics WHERE project_id = ?`).get(project.id) as { n: number; m: number });
      if (count.n >= 100) throw notFound('Too many topics');
      const id = crypto.randomUUID();
      db.prepare(`INSERT INTO topics(id, project_id, name, color, sort, created_at) VALUES (?,?,?,?,?,?)`)
        .run(id, project.id, body.name, body.color ?? TOPIC_COLORS[count.n % TOPIC_COLORS.length]!, count.m + 1, now());
      ctx.audit(req, 'topic_create', id, { projectId: project.id, name: body.name });
      changed(project.id);
      reply.code(201);
      return topicDTO({ ...loadTopic(id), n: 0 });
    });

    app.patch('/api/topics/:id', async (req) => {
      const u = requireUser(req);
      const t = loadTopic((req.params as { id: string }).id);
      requireProject(db, u, t.project_id, 'editor');
      const body = patchBody.parse(req.body ?? {});
      db.prepare(`UPDATE topics SET name = COALESCE(?, name), color = COALESCE(?, color), sort = COALESCE(?, sort) WHERE id = ?`)
        .run(body.name ?? null, body.color ?? null, body.sort ?? null, t.id);
      changed(t.project_id);
      return topicDTO(loadTopic(t.id));
    });

    app.delete('/api/topics/:id', async (req) => {
      const u = requireUser(req);
      const t = loadTopic((req.params as { id: string }).id);
      requireProject(db, u, t.project_id, 'editor');
      db.transaction(() => {
        db.prepare(`UPDATE conversations SET topic_id = NULL WHERE topic_id = ?`).run(t.id);
        db.prepare(`DELETE FROM topics WHERE id = ?`).run(t.id);
      })();
      ctx.audit(req, 'topic_delete', t.id, { projectId: t.project_id, name: t.name });
      changed(t.project_id);
      return { ok: true };
    });
  };

