import fs from 'node:fs';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { api, createUser, login, makeEnv, startPreviewUpstream, waitFor, type TestEnv } from './helpers.js';

let env: TestEnv;
let upstream: Awaited<ReturnType<typeof startPreviewUpstream>>;
let admin: string, alice: string, bob: string, carol: string, dave: string;
let aliceId: string, bobId: string, carolId: string;

const read = (...p: string[]) => fs.readFileSync(path.join(env.cfg.projectsDir, ...p), 'utf8');
const exists = (...p: string[]) => fs.existsSync(path.join(env.cfg.projectsDir, ...p));
const runStatus = (id: string) => (env.built.ctx.db.prepare(`SELECT status, commit_sha FROM runs WHERE id = ?`).get(id) as { status: string; commit_sha: string | null });
async function gitReady(projectId: string) {
  await waitFor(() => (env.built.ctx.db.prepare(`SELECT git_main FROM projects WHERE id = ?`).get(projectId) as { git_main: string | null }).git_main, 10000);
}

beforeAll(async () => {
  upstream = await startPreviewUpstream();
  env = await makeEnv({}, { listen: true });
  aliceId = await createUser(env, 'alice@test.local', 'alice-pass');
  bobId = await createUser(env, 'bob@test.local', 'bob-pass');
  carolId = await createUser(env, 'carol@test.local', 'carol-pass');
  await createUser(env, 'dave@test.local', 'dave-pass');
  admin = await login(env, 'admin@test.local', 'admin-password-1');
  alice = await login(env, 'alice@test.local', 'alice-pass');
  bob = await login(env, 'bob@test.local', 'bob-pass');
  carol = await login(env, 'carol@test.local', 'carol-pass');
  dave = await login(env, 'dave@test.local', 'dave-pass');
});
afterAll(async () => {
  await env.close();
  await upstream.close();
});

describe('sub-projects', () => {
  let parent: any, child: any, solo: any;
  it('creates children (max depth 2), inherits members, shows in graph', async () => {
    parent = (await api(env, alice, 'POST', '/api/projects', { name: 'Nxeon' })).json;
    const r = await api(env, alice, 'POST', '/api/projects', { name: 'Website', parentId: parent.id });
    expect(r.status).toBe(201);
    child = r.json;
    expect(child).toMatchObject({ parentId: parent.id, color: parent.color, myRole: 'owner' });
    expect(child.previewPort).not.toBe(parent.previewPort);
    expect(exists(child.slug, 'README.md')).toBe(true);
    // depth limit
    expect((await api(env, alice, 'POST', '/api/projects', { name: 'Deep', parentId: child.id })).json.error.code).toBe('max_depth');
    // non-member of the parent cannot create children
    expect((await api(env, bob, 'POST', '/api/projects', { name: 'Nope', parentId: parent.id })).status).toBe(404);
    // '--' is reserved for branch preview keys
    expect((await api(env, alice, 'POST', '/api/projects', { name: 'X', slug: 'a--b' })).status).toBe(400);

    // bob: viewer of the parent → viewer on the child (inherited); carol: editor of the child only
    await api(env, alice, 'PUT', `/api/projects/${parent.id}/members`, { members: [{ userId: aliceId, role: 'owner' }, { userId: bobId, role: 'viewer' }] });
    await api(env, alice, 'PUT', `/api/projects/${child.id}/members`, { members: [{ userId: aliceId, role: 'owner' }, { userId: carolId, role: 'editor' }, { userId: bobId, role: 'viewer' }] });
    expect((await api(env, bob, 'GET', `/api/projects/${child.id}`)).json.myRole).toBe('viewer');
    expect((await api(env, bob, 'POST', `/api/projects/${child.id}/conversations`, {})).status).toBe(403);
    // promote bob on the parent → effective editor on the child (max(own viewer, parent editor))
    await api(env, alice, 'PUT', `/api/projects/${parent.id}/members`, { members: [{ userId: aliceId, role: 'owner' }, { userId: bobId, role: 'editor' }] });
    expect((await api(env, bob, 'GET', `/api/projects/${child.id}`)).json.myRole).toBe('editor');
    expect((await api(env, bob, 'POST', `/api/projects/${child.id}/conversations`, {})).status).toBe(201);
    // carol sees the child but not the parent
    const carolList = (await api(env, carol, 'GET', '/api/projects')).json.map((p: any) => p.id);
    expect(carolList).toEqual([child.id]);
    expect((await api(env, carol, 'GET', `/api/projects/${parent.id}`)).status).toBe(404);
    // dave sees nothing
    expect((await api(env, dave, 'GET', `/api/projects/${child.id}`)).status).toBe(404);
    // bob (parent member) sees both
    const bobList = (await api(env, bob, 'GET', '/api/projects')).json.map((p: any) => p.id).sort();
    expect(bobList).toEqual([parent.id, child.id].sort());

    const g = (await api(env, bob, 'GET', '/api/projects/graph')).json;
    expect(g.nodes.find((n: any) => n.id === child.id)).toMatchObject({ kind: 'subproject', parentId: parent.id, slug: child.slug });
    expect(g.nodes.find((n: any) => n.id === parent.id)).toMatchObject({ kind: 'project', parentId: null });
    expect(g.links).toContainEqual({ source: parent.id, target: child.id, kind: 'child' });
    expect(g.links).toContainEqual({ source: 'core', target: parent.id, kind: 'core' });
    // carol can't see the parent: the child is a top-level ring node for her
    const gc = (await api(env, carol, 'GET', '/api/projects/graph')).json;
    expect(gc.nodes.find((n: any) => n.id === child.id)).toMatchObject({ kind: 'project', parentId: null });
  });

  it('moves children and guards parent deletion', async () => {
    solo = (await api(env, alice, 'POST', '/api/projects', { name: 'Solo' })).json;
    const extra = (await api(env, alice, 'POST', '/api/projects', { name: 'Admin Panel', parentId: parent.id })).json;
    // a project with children cannot become a child
    expect((await api(env, alice, 'PATCH', `/api/projects/${parent.id}`, { parentId: solo.id })).json.error.code).toBe('max_depth');
    // move extra under solo, then back to top-level
    expect((await api(env, alice, 'PATCH', `/api/projects/${extra.id}`, { parentId: solo.id })).json.parentId).toBe(solo.id);
    expect((await api(env, alice, 'PATCH', `/api/projects/${extra.id}`, { parentId: null })).json.parentId).toBe(null);
    // editors can't re-parent (owner field)
    expect((await api(env, bob, 'PATCH', `/api/projects/${child.id}`, { parentId: null })).status).toBe(403);
    // deleting a parent with children needs cascade
    const d = await api(env, alice, 'DELETE', `/api/projects/${parent.id}`);
    expect(d.status).toBe(409);
    expect(d.json.error.code).toBe('has_children');
    const c = await api(env, alice, 'DELETE', `/api/projects/${parent.id}?cascade=1`);
    expect(c.json).toEqual({ ok: true, deletedChildren: 1 });
    expect((await api(env, admin, 'GET', `/api/projects/${child.id}`)).status).toBe(404);
    expect(exists(child.slug)).toBe(false);
    await api(env, alice, 'DELETE', `/api/projects/${extra.id}`);
    await api(env, alice, 'DELETE', `/api/projects/${solo.id}`);
  });
});

describe('branches', () => {
  let project: any;
  const B = () => `/api/projects/${project.id}`;

  it('bootstraps git, creates a branch worktree with its own port and preview path', async () => {
    project = (await api(env, alice, 'POST', '/api/projects', { name: 'Shop' })).json;
    await api(env, alice, 'PUT', `${B()}/members`, { members: [{ userId: aliceId, role: 'owner' }, { userId: bobId, role: 'viewer' }] });
    await gitReady(project.id);
    expect(exists(project.slug, '.git')).toBe(true);
    expect(read(project.slug, '.gitignore')).toContain('node_modules');

    expect((await api(env, bob, 'POST', `${B()}/branches`, { name: 'feature/cart' })).status).toBe(403);
    expect((await api(env, alice, 'POST', `${B()}/branches`, { name: 'Bad Name' })).json.error.code).toBe('invalid_branch');
    expect((await api(env, alice, 'POST', `${B()}/branches`, { name: 'main' })).json.error.code).toBe('invalid_branch');
    const r = await api(env, alice, 'POST', `${B()}/branches`, { name: 'feature/cart' });
    expect(r.status).toBe(201);
    expect(r.json).toMatchObject({ name: 'feature/cart', base: 'main', status: 'active', previewPath: `/preview/${project.slug}--feature_cart/` });
    expect(r.json.previewPort).not.toBe(project.previewPort);
    expect(exists('.branches', project.slug, 'feature_cart', 'README.md')).toBe(true);
    expect((await api(env, alice, 'POST', `${B()}/branches`, { name: 'feature/cart' })).json.error.code).toBe('branch_exists');

    const list = (await api(env, bob, 'GET', `${B()}/branches`)).json;
    expect(list.main).toMatchObject({ name: 'main', previewPath: `/preview/${project.slug}/` });
    expect(list.branches).toHaveLength(1);
    expect(list.branches[0]).toMatchObject({ name: 'feature/cart', ahead: 0, filesChanged: 0 });
  });

  it('scopes files, conversations and preview to the branch', async () => {
    const q = '?branch=' + encodeURIComponent('feature/cart');
    expect((await api(env, alice, 'PUT', `${B()}/files/content${q}`, { path: 'cart.js', content: 'export const cart = [];\n' })).status).toBe(200);
    expect((await api(env, alice, 'PUT', `${B()}/files/content${q}`, { path: 'README.md', content: '# Shop\n\nwith a cart\n' })).status).toBe(200);
    expect((await api(env, bob, 'PUT', `${B()}/files/content${q}`, { path: 'x.js', content: '' })).status).toBe(403);
    expect(exists(project.slug, 'cart.js')).toBe(false);
    const tree = (await api(env, bob, 'GET', `${B()}/files/tree${q}`)).json;
    expect(tree.branch).toBe('feature/cart');
    expect(tree.children.map((c: any) => c.name)).toContain('cart.js');
    expect(tree.children.map((c: any) => c.name)).not.toContain('.git');
    expect((await api(env, bob, 'GET', `${B()}/files/content${q}&path=cart.js`)).json.content).toBe('export const cart = [];\n');
    expect((await api(env, bob, 'GET', `${B()}/files/tree?branch=nope`)).status).toBe(404);
    // .git is never writable
    expect((await api(env, alice, 'PUT', `${B()}/files/content`, { path: '.git/config', content: 'x' })).status).toBe(403);

    // conversations live on their branch
    const conv = (await api(env, alice, 'POST', `${B()}/conversations`, { branch: 'feature/cart' })).json;
    expect(conv.branch).toBe('feature/cart');
    expect((await api(env, alice, 'GET', `${B()}/conversations${q}`)).json.map((c: any) => c.id)).toEqual([conv.id]);
    expect((await api(env, alice, 'GET', `${B()}/conversations`)).json.map((c: any) => c.id)).not.toContain(conv.id);

    // preview targets the worktree
    const st = (await api(env, alice, 'POST', `${B()}/preview/start${q}`)).json;
    expect(st).toMatchObject({ url: `/preview/${project.slug}--feature_cart/`, branch: 'feature/cart' });
    expect(env.fake.previewCalls.at(-1)).toMatchObject({ op: 'start', projectSlug: project.slug, worktree: 'feature_cart' });
    await api(env, alice, 'POST', `${B()}/preview/stop${q}`);
  });

  it('proxies /preview/<slug>--<branch>/ to the branch port', async () => {
    env.built.ctx.db.prepare(`UPDATE branches SET preview_port = ? WHERE project_id = ? AND name = ?`).run(upstream.port, project.id, 'feature/cart');
    const res = await fetch(`${env.baseUrl}/preview/${project.slug}--feature_cart/app.js?v=1`, { headers: { cookie: bob } });
    expect(res.status).toBe(200);
    expect(await res.text()).toContain(`path=/preview/${project.slug}--feature_cart/app.js?v=1`);
    expect((await fetch(`${env.baseUrl}/preview/${project.slug}--nope/`, { headers: { cookie: bob } })).status).toBe(404);
    expect((await fetch(`${env.baseUrl}/preview/${project.slug}--feature_cart/`, { headers: { cookie: dave } })).status).toBe(404);
    const redir = await fetch(`${env.baseUrl}/preview/${project.slug}--feature_cart`, { headers: { cookie: bob }, redirect: 'manual' });
    expect(redir.headers.get('location')).toBe(`/preview/${project.slug}--feature_cart/`);
  });

  it('runs in the worktree, auto-checkpoints, and can undo the run', async () => {
    const q = '?branch=' + encodeURIComponent('feature/cart');
    const conv = (await api(env, alice, 'GET', `${B()}/conversations${q}`)).json[0];
    fs.writeFileSync(path.join(env.cfg.projectsDir, '.branches', project.slug, 'feature_cart', 'checkout.js'), 'export const pay = 1;\n');
    const p = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'Add a checkout module please', thinking: 'off' });
    expect(p.status).toBe(200);
    const body = env.fake.bodies.at(-1)!;
    expect(body).toMatchObject({ projectSlug: project.slug, worktree: 'feature_cart', previewPort: upstream.port });
    expect(String(body.appendSystemPrompt)).toContain('git branch "feature/cart"');
    expect(String(body.appendSystemPrompt)).toContain(`/preview/${project.slug}--feature_cart/`);
    expect(String(body.appendSystemPrompt)).toContain('.branches/' + project.slug + '/feature_cart');
    const run = await waitFor(() => (runStatus(p.json.runId).commit_sha ? runStatus(p.json.runId) : null), 10000);
    expect(run.status).toBe('done');

    const hist = (await api(env, bob, 'GET', `${B()}/history${q}`)).json;
    expect(hist.branch).toBe('feature/cart');
    expect(hist.commits[0]).toMatchObject({ message: 'nxeon: Add a checkout module please', sha: run.commit_sha, run: { id: p.json.runId, undone: false } });
    expect(hist.commits[0].filesChanged).toBe(3); // cart.js, README.md (editor edits) + checkout.js

    expect((await api(env, bob, 'POST', `/api/runs/${p.json.runId}/undo`)).status).toBe(403);
    const u = await api(env, alice, 'POST', `/api/runs/${p.json.runId}/undo`);
    expect(u.json).toMatchObject({ ok: true });
    expect(exists('.branches', project.slug, 'feature_cart', 'checkout.js')).toBe(false);
    expect((await api(env, alice, 'POST', `/api/runs/${p.json.runId}/undo`)).json.error.code).toBe('already_undone');
    const h2 = (await api(env, bob, 'GET', `${B()}/history${q}`)).json;
    expect(h2.commits[0].message).toMatch(/^Revert "nxeon: Add a checkout module please"/);
    expect(h2.commits[1].run.undone).toBe(true);

    // manual checkpoint
    fs.writeFileSync(path.join(env.cfg.projectsDir, '.branches', project.slug, 'feature_cart', 'cart.js'), 'export const cart = [1];\n');
    expect((await api(env, bob, 'POST', `${B()}/checkpoint${q}`, {})).status).toBe(403);
    const cp = (await api(env, alice, 'POST', `${B()}/checkpoint${q}`, { message: 'tweak cart' })).json;
    expect(cp.sha).toMatch(/^[0-9a-f]{40}$/);
    expect((await api(env, alice, 'POST', `${B()}/checkpoint${q}`, {})).json.sha).toBe(null);
  });

  it('diffs vs base and merges into main (--no-ff), closing the branch', async () => {
    const enc = encodeURIComponent('feature/cart');
    const d = (await api(env, bob, 'GET', `${B()}/branches/${enc}/diff`)).json;
    expect(d.base).toBe('main');
    expect(d.files.map((f: any) => [f.path, f.status])).toEqual([['README.md', 'modified'], ['cart.js', 'added']]);
    const fd = (await api(env, bob, 'GET', `${B()}/branches/${enc}/diff/file?path=README.md`)).json;
    expect(fd.modified).toContain('with a cart');
    expect(fd.original).not.toContain('with a cart');
    expect((await api(env, bob, 'POST', `${B()}/branches/${enc}/merge`, {})).status).toBe(403);

    const m = await api(env, alice, 'POST', `${B()}/branches/${enc}/merge`, {});
    expect(m.json).toMatchObject({ ok: true, closed: true, into: 'main' });
    expect(read(project.slug, 'cart.js')).toBe('export const cart = [1];\n');
    expect(exists('.branches', project.slug, 'feature_cart')).toBe(false);
    const list = (await api(env, alice, 'GET', `${B()}/branches?all=1`)).json.branches;
    expect(list[0]).toMatchObject({ name: 'feature/cart', status: 'merged' });
    // conversations of a closed branch move to main (fresh Claude session)
    const convs = (await api(env, alice, 'GET', `${B()}/conversations`)).json;
    expect(convs.some((c: any) => c.branch === null && c.claudeSessionId === null && c.title)).toBe(true);
    const h = (await api(env, alice, 'GET', `${B()}/history`)).json;
    expect(h.commits[0]).toMatchObject({ isMerge: true, message: 'nxeon: merge feature/cart into main' });
  });

  it('reports merge conflicts without touching main, offers a resolve prompt; discard + rename', async () => {
    const b = (await api(env, alice, 'POST', `${B()}/branches`, { name: 'restyle' })).json;
    expect(b.previewPath).toBe(`/preview/${project.slug}--restyle/`);
    await api(env, alice, 'PUT', `${B()}/files/content?branch=restyle`, { path: 'README.md', content: '# Shop (branch)\n' });
    await api(env, alice, 'PUT', `${B()}/files/content`, { path: 'README.md', content: '# Shop (main)\n' });
    const m = (await api(env, alice, 'POST', `${B()}/branches/restyle/merge`, {})).json;
    expect(m.ok).toBe(false);
    expect(m.conflicts).toEqual(['README.md']);
    expect(m.resolvePrompt).toContain('git merge main');
    expect(read(project.slug, 'README.md')).toBe('# Shop (main)\n');
    expect((await api(env, alice, 'GET', `${B()}/branches`)).json.branches[0]).toMatchObject({ name: 'restyle', status: 'active' });

    // rename keeps the worktree (and the preview key)
    const r = await api(env, alice, 'PATCH', `${B()}/branches/restyle`, { name: 'restyle-v2' });
    expect(r.json).toMatchObject({ name: 'restyle-v2', previewPath: `/preview/${project.slug}--restyle/` });
    expect((await api(env, alice, 'GET', `${B()}/files/content?branch=restyle-v2&path=README.md`)).json.content).toBe('# Shop (branch)\n');

    const conv = (await api(env, alice, 'POST', `${B()}/conversations`, { branch: 'restyle-v2' })).json;
    expect((await api(env, bob, 'DELETE', `${B()}/branches/restyle-v2`)).status).toBe(403);
    expect((await api(env, alice, 'DELETE', `${B()}/branches/restyle-v2`)).json).toEqual({ ok: true });
    expect(exists('.branches', project.slug, 'restyle')).toBe(false);
    expect((await api(env, alice, 'GET', `${B()}/branches`)).json.branches).toEqual([]);
    expect((await api(env, alice, 'GET', `/api/conversations/${conv.id}`)).json.branch).toBe(null);
    // the port is free again
    const again = (await api(env, alice, 'POST', `${B()}/branches`, { name: 'restyle' })).json;
    expect(again.previewPath).toBe(`/preview/${project.slug}--restyle-2/`);
  });
});

describe('topics', () => {
  it('CRUD, move conversations, delete ungroups, graph satellites', async () => {
    const project = (await api(env, alice, 'POST', '/api/projects', { name: 'Topics Lab' })).json;
    await api(env, alice, 'PUT', `/api/projects/${project.id}/members`, { members: [{ userId: aliceId, role: 'owner' }, { userId: bobId, role: 'viewer' }] });
    const T = `/api/projects/${project.id}/topics`;
    expect((await api(env, bob, 'POST', T, { name: 'Auth' })).status).toBe(403);
    const auth = (await api(env, alice, 'POST', T, { name: 'Auth' })).json;
    const ui = (await api(env, alice, 'POST', T, { name: 'UI', color: '#3dffb5' })).json;
    expect(auth).toMatchObject({ name: 'Auth', sort: 0, conversations: 0 });
    expect(ui).toMatchObject({ color: '#3dffb5', sort: 1 });
    const c1 = (await api(env, alice, 'POST', `/api/projects/${project.id}/conversations`, { topicId: auth.id })).json;
    const c2 = (await api(env, alice, 'POST', `/api/projects/${project.id}/conversations`, {})).json;
    expect(c1.topicId).toBe(auth.id);
    expect((await api(env, alice, 'PATCH', `/api/conversations/${c2.id}`, { topicId: ui.id })).json.topicId).toBe(ui.id);
    expect((await api(env, bob, 'PATCH', `/api/conversations/${c2.id}`, { topicId: null })).status).toBe(403);
    expect((await api(env, alice, 'PATCH', `/api/conversations/${c2.id}`, { topicId: 'nope' })).json.error.code).toBe('unknown_topic');
    expect((await api(env, alice, 'PATCH', `/api/topics/${auth.id}`, { name: 'Login & auth', sort: 5 })).json).toMatchObject({ name: 'Login & auth', sort: 5 });
    const list = (await api(env, bob, 'GET', T)).json;
    expect(list.map((t: any) => [t.name, t.conversations])).toEqual([['UI', 1], ['Login & auth', 1]]);

    await gitReady(project.id);
    await api(env, alice, 'POST', `/api/projects/${project.id}/branches`, { name: 'dark-mode' });
    const g = (await api(env, bob, 'GET', '/api/projects/graph?satellites=1')).json;
    const br = g.nodes.find((n: any) => n.kind === 'branch' && n.parentId === project.id);
    expect(br).toMatchObject({ name: 'dark-mode', branch: 'dark-mode', slug: project.slug, base: 'main', status: 'idle' });
    const tp = g.nodes.filter((n: any) => n.kind === 'topic' && n.parentId === project.id);
    expect(tp.map((n: any) => n.name).sort()).toEqual(['Login & auth', 'UI']);
    expect(g.links).toContainEqual({ source: project.id, target: br.id, kind: 'branch' });
    // legacy shape (no satellites) stays project-only
    const legacy = (await api(env, bob, 'GET', '/api/projects/graph')).json;
    expect(legacy.nodes.every((n: any) => ['core', 'project', 'subproject'].includes(n.kind))).toBe(true);

    expect((await api(env, alice, 'DELETE', `/api/topics/${auth.id}`)).json).toEqual({ ok: true });
    expect((await api(env, alice, 'GET', `/api/conversations/${c1.id}`)).json.topicId).toBe(null);
    expect((await api(env, bob, 'GET', T)).json).toHaveLength(1);
  });
});

