// Global UI toggles (command palette, new-project modal).
import { create } from 'zustand';
interface UIState {
  paletteOpen: boolean; newProjectOpen: boolean;
  setPalette: (o: boolean) => void; setNewProject: (o: boolean) => void;
}
export const useUI = create<UIState>((set) => ({
  paletteOpen: false, newProjectOpen: false,
  setPalette: (paletteOpen) => set({ paletteOpen }),
  setNewProject: (newProjectOpen) => set({ newProjectOpen, paletteOpen: false }),
}));
import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Check, Sparkles } from 'lucide-react';
import { Button, Input, Textarea, cn, toast } from '@/components/ui';
import { Modal } from '@/components/ui';
import { PROJECT_COLORS, PROJECT_ICONS, PROJECT_ICON_NAMES, ProjectBadge } from '@/components/ProjectIcon';
import { useUI } from '@/stores/ui';
import { useProjects } from '@/stores/projects';
import { slugify } from '@/lib/format';

/** Global "create project" modal (open with useUI.getState().setNewProject(true)). */
export function NewProjectModal() {
  const open = useUI((s) => s.newProjectOpen);
  const setOpen = useUI((s) => s.setNewProject);
  const create = useProjects((s) => s.create);
  const nav = useNavigate();
  const [name, setName] = useState('');
  const [desc, setDesc] = useState('');
  const [color, setColor] = useState(PROJECT_COLORS[0]);
  const [icon, setIcon] = useState('rocket');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      setName(''); setDesc(''); setErr(null);
      setColor(PROJECT_COLORS[Math.floor(Math.random() * 5)]);
      setIcon(PROJECT_ICON_NAMES[Math.floor(Math.random() * PROJECT_ICON_NAMES.length)]);
    }
  }, [open]);

  const slug = slugify(name);
  const valid = /^[a-z0-9][a-z0-9-]{0,47}$/.test(slug);
  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!valid) return setErr('Name must contain letters or numbers');
    setBusy(true); setErr(null);
    try {
      const p = await create({ name: name.trim(), description: desc.trim(), color, icon, slug });
      toast.success(`Project “${p.name}” created`);
      setOpen(false);
      nav(`/p/${p.slug}`);
    } catch (e: any) { setErr(e.message || 'Could not create project'); }
    finally { setBusy(false); }
  };

  return (
    <Modal open={open} onClose={() => setOpen(false)} title="Spin a new strand" description="Create a project — it gets its own folder, chat history and live preview." icon={<Sparkles size={18} />}>
      <form onSubmit={submit} className="flex flex-col gap-4 pb-1">
        <div className="flex items-start gap-3">
          <div className="pt-6"><ProjectBadge name={icon} color={color} size={40} /></div>
          <div className="flex-1">
            <Input
              label="Name" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Neon Storefront" autoFocus maxLength={60} required
              hint={name ? <span className="font-mono">/p/{slug || '…'}</span> : 'Short and memorable'} error={err}
            />
          </div>
        </div>
        <Textarea label="Description" value={desc} onChange={(e) => setDesc(e.target.value)} rows={2} placeholder="What are you building? (Claude sees this as context)" maxLength={500} />
        <div>
          <div className="mb-1.5 text-xs font-medium text-muted">Color</div>
          <div className="flex flex-wrap gap-2">
            {PROJECT_COLORS.map((c) => (
              <button
                key={c} type="button" onClick={() => setColor(c)} aria-label={`Color ${c}`} aria-pressed={c === color}
                className={cn('flex h-7 w-7 items-center justify-center rounded-full transition-transform hover:scale-110', c === color && 'ring-2 ring-offset-2 ring-offset-panel')}
                style={{ background: c, boxShadow: `0 0 12px -2px ${c}`, ['--tw-ring-color' as any]: c }}
              >
                {c === color && <Check size={13} className="text-black/70" />}
              </button>
            ))}
          </div>
        </div>
        <div>
          <div className="mb-1.5 text-xs font-medium text-muted">Icon</div>
          <div className="grid grid-cols-[repeat(9,minmax(0,1fr))] gap-1.5 sm:grid-cols-[repeat(13,minmax(0,1fr))]">
            {PROJECT_ICON_NAMES.map((n) => {
              const I = PROJECT_ICONS[n];
              const on = n === icon;
              return (
                <button
                  key={n} type="button" onClick={() => setIcon(n)} aria-label={n} aria-pressed={on} title={n}
                  className={cn('flex h-8 items-center justify-center rounded-md border transition-colors', on ? 'border-transparent' : 'border-line text-muted hover:text-ink hover:border-pink/30')}
                  style={on ? { background: `${color}22`, color, boxShadow: `inset 0 0 0 1px ${color}88` } : undefined}
                >
                  <I size={15} />
                </button>
              );
            })}
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-1">
          <Button variant="ghost" onClick={() => setOpen(false)}>Cancel</Button>
          <Button type="submit" variant="primary" loading={busy} disabled={!name.trim()}>Create project</Button>
        </div>
      </form>
    </Modal>
  );
}
