import {
  Boxes, Rocket, CodeXml, Globe, Database, Cpu, Bot, Brain, Gamepad2, ShoppingCart, ChartLine, Palette, Terminal, Zap,
  Flame, Music, Camera, BookOpen, Server, Shield, Sparkles, Layers, FlaskConical, Smartphone, Puzzle, Network, type LucideIcon,
} from 'lucide-react';

export const PROJECT_ICONS: Record<string, LucideIcon> = {
  boxes: Boxes, rocket: Rocket, code: CodeXml, globe: Globe, database: Database, cpu: Cpu, bot: Bot, brain: Brain,
  gamepad: Gamepad2, cart: ShoppingCart, chart: ChartLine, palette: Palette, terminal: Terminal, zap: Zap, flame: Flame,
