export const PROJECT_COLORS = ['#ff3e8a', '#ff6fae', '#ff8a5c', '#ffc857', '#b14bff', '#3dffb5', '#ff4d6d', '#f6e9f0'];

export function projectIcon(name?: string | null): LucideIcon {
  if (!name) return Boxes;
  return PROJECT_ICONS[name] || PROJECT_ICONS[name.toLowerCase()] || Boxes;
}

/** <ProjectIcon name="rocket" size={16} color="#ff3e8a"/> */
export function ProjectIcon({ name, size = 16, color, className }: { name?: string | null; size?: number; color?: string; className?: string }) {
  const I = projectIcon(name);
  return <I size={size} color={color} className={className} />;
}

/** Colored rounded tile with the project's icon. */
export function ProjectBadge({ name, color = '#ff3e8a', size = 28 }: { name?: string | null; color?: string; size?: number }) {
import type { HTMLAttributes, ReactNode } from 'react';
import { cn } from './cn';

/**
 * Badge — small pill label.
 *  tone: 'neutral' | 'pink' | 'warm' | 'violet' | 'ok' | 'warn' | 'bad'  (default 'neutral')
 *  size 'sm' | 'md' (default 'sm'), icon?, dot? (leading colored dot), mono?
 */
export type BadgeTone = 'neutral' | 'pink' | 'warm' | 'violet' | 'ok' | 'warn' | 'bad';
const tones: Record<BadgeTone, string> = {
  neutral: 'bg-white/[0.04] text-muted border-line',
  pink: 'bg-pink/10 text-hot border-pink/30',
  warm: 'bg-warm/10 text-warm border-warm/30',
  violet: 'bg-violet/10 text-violet border-violet/30',
  ok: 'bg-ok/10 text-ok border-ok/25',
  warn: 'bg-warn/10 text-warn border-warn/25',
  bad: 'bg-bad/10 text-bad border-bad/30',
};
const dots: Record<BadgeTone, string> = { neutral: 'bg-muted', pink: 'bg-pink', warm: 'bg-warm', violet: 'bg-violet', ok: 'bg-ok', warn: 'bg-warn', bad: 'bg-bad' };
export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> { tone?: BadgeTone; size?: 'sm' | 'md'; icon?: ReactNode; dot?: boolean; mono?: boolean }
export function Badge({ tone = 'neutral', size = 'sm', icon, dot, mono, className, children, ...rest }: BadgeProps) {
  return (
    <span
      className={cn('inline-flex items-center gap-1 rounded-full border font-medium whitespace-nowrap',
        size === 'sm' ? 'h-5 px-2 text-[10.5px]' : 'h-6 px-2.5 text-xs', mono && 'font-mono', tones[tone], className)}
      {...rest}
    >
      {dot && <span className={cn('h-1.5 w-1.5 rounded-full', dots[tone])} />}
      {icon}
      {children}

