// Formatting helpers (numbers, tokens, money, relative time).
export function fmtNum(n: number | null | undefined) {
  if (n == null || !isFinite(n)) return '—';
  return n.toLocaleString('en-US');
}
/** 1234 → "1.2k", 2_500_000 → "2.5M" */
export function fmtCompact(n: number | null | undefined, digits = 1) {
  if (n == null || !isFinite(n)) return '—';
  const a = Math.abs(n);
  if (a >= 1e9) return (n / 1e9).toFixed(digits).replace(/\.0+$/, '') + 'B';
  if (a >= 1e6) return (n / 1e6).toFixed(digits).replace(/\.0+$/, '') + 'M';
  if (a >= 1e3) return (n / 1e3).toFixed(digits).replace(/\.0+$/, '') + 'k';
  return String(Math.round(n));
}
export function fmtUsd(n: number | null | undefined) {
  if (n == null || !isFinite(n)) return '—';
  return n >= 100 ? `$${n.toFixed(0)}` : n >= 1 ? `$${n.toFixed(2)}` : `$${n.toFixed(n === 0 ? 2 : 3)}`;
}
export function fmtPct(n: number | null | undefined, digits = 1) {
  if (n == null || !isFinite(n)) return '—';
  return `${(n * 100).toFixed(digits)}%`;
}
export function fmtBytes(n: number | null | undefined) {
  if (n == null) return '—';
  if (n < 1024) return `${n} B`;
  if (n < 1024 ** 2) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 ** 3) return `${(n / 1024 ** 2).toFixed(1)} MB`;
  return `${(n / 1024 ** 3).toFixed(2)} GB`;
}
export function fmtDuration(ms: number | null | undefined) {
  if (ms == null) return '—';
  if (ms < 1000) return `${Math.round(ms)}ms`;
  const s = ms / 1000;
  if (s < 60) return `${s.toFixed(1)}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ${Math.round(s % 60)}s`;
  return `${Math.floor(m / 60)}h ${m % 60}m`;
}
export function timeAgo(iso: string | number | null | undefined) {
  if (iso == null || iso === '') return 'never';
  const t = typeof iso === 'number' ? iso : Date.parse(iso);
  if (!isFinite(t)) return '—';
  const d = (Date.now() - t) / 1000;
  if (d < 10) return 'just now';
  if (d < 60) return `${Math.floor(d)}s ago`;
  if (d < 3600) return `${Math.floor(d / 60)}m ago`;
  if (d < 86400) return `${Math.floor(d / 3600)}h ago`;
  if (d < 86400 * 30) return `${Math.floor(d / 86400)}d ago`;
  return new Date(t).toLocaleDateString();
