// Top-bar git/branch UI: branch switcher chip, merge/discard/compare actions, checkpoint history,
// and the parent/child project breadcrumb.
import { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import clsx from 'clsx';
import {
  Check, ChevronDown, ChevronRight, GitBranch, GitCompareArrows, GitMerge, History, Pencil, Plus, Save, Trash2, TriangleAlert,
  Undo2, Sparkles, CornerDownRight, FolderTree, GitCommitHorizontal,
} from 'lucide-react';
import { Button, Modal, toast } from '@/components/ui';
import { ProjectBadge } from '@/components/ProjectIcon';
import { useUI } from '@/stores/ui';
import { timeAgo } from '@/lib/format';
import type { Branch, HistoryCommit } from '@/lib/types';
import { useWs } from './store';
import { Dot, IconBtn, Popover, Spin, Tip } from './ui';

const BRANCH_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*(?:\/[a-z0-9]+(?:-[a-z0-9]+)*)*$/;

/** Navigate the workspace to another branch (null = main), keeping the URL the source of truth. */
export function useBranchNav() {
  const [sp, setSp] = useSearchParams();
  return (branch: string | null) => {
    const next = new URLSearchParams(sp);
    if (branch) next.set('branch', branch); else next.delete('branch');
    next.delete('topic');
    setSp(next, { replace: false });
  };
}

const sanitize = (v: string) => v.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9/-]/g, '').replace(/-{2,}/g, '-').replace(/\/{2,}/g, '/').slice(0, 40);
const shortMsg = (m: string) => m.replace(/^nxeon:\s*/, '');

function BranchStat({ b }: { b: Branch }) {
  return (
    <span className="flex shrink-0 items-center gap-1.5 font-mono text-[10.5px] text-muted">
      {b.filesChanged != null && b.filesChanged > 0 && <span title="files changed vs base" className="text-warm/90">{b.filesChanged} file{b.filesChanged === 1 ? '' : 's'}</span>}
      {!!b.ahead && <span title="commits ahead of base" className="text-ok/80">↑{b.ahead}</span>}
      {!!b.behind && <span title="commits behind base" className="text-muted/70">↓{b.behind}</span>}
    </span>
  );
}

// ---------------------------------------------------------------- branch chip

export function BranchChip({ compact }: { compact?: boolean }) {
  const branch = useWs((s) => s.branch);
  const list = useWs((s) => s.branchList);
  const canEdit = useWs((s) => s.canEdit);
  const running = useWs((s) => s.branchList?.branches.find((b) => b.name === s.branch)?.running ?? s.branchList?.main.running ?? false);
  const [el, setEl] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  const [creating, setCreating] = useState(false);
  const [merge, setMerge] = useState<Branch | null>(null);
  const [discard, setDiscard] = useState<Branch | null>(null);
  const [conflict, setConflict] = useState<{ branch: string; files: string[]; prompt: string } | null>(null);
  const go = useBranchNav();
  const mainName = list?.main.name ?? 'main';
  const count = list?.branches.length ?? 0;

  useEffect(() => { if (open) useWs.getState().loadBranches(); }, [open]);

  return (
    <>
      <Tip label={branch ? `Branch ${branch} — switch, merge or compare` : 'Branches — work on an isolated copy with its own preview'} side="bottom">
        <button ref={setEl} type="button" onClick={() => setOpen((o) => !o)} data-testid="branch-chip"
          className={clsx('flex h-7 min-w-0 items-center gap-1.5 rounded-full border px-2 text-[11.5px] transition-colors',
            branch ? 'border-violet/50 bg-violet/10 text-ink shadow-[0_0_14px_-6px_rgba(177,75,255,.9)]' : 'border-line/80 text-muted hover:border-pink/40 hover:text-ink',
            open && 'border-pink/50 text-ink')}>
          <GitBranch size={13} className={branch ? 'text-violet' : ''} />
          <span className={clsx('truncate font-mono', compact ? 'max-w-[90px]' : 'max-w-[160px]')}>{branch ?? mainName}</span>
          {running && <Dot tone="pink" pulse className="scale-75" />}
          {!branch && count > 0 && <span className="rounded-full bg-white/[.07] px-1.5 text-[10px] text-muted">{count}</span>}
          <ChevronDown size={12} className="shrink-0 opacity-70" />
        </button>
      </Tip>
      <Popover open={open} anchor={el} onClose={() => { setOpen(false); setCreating(false); }} side="bottom" align="start" className="w-[340px] max-w-[calc(100vw-16px)]">
        <div className="flex items-center gap-2 px-2.5 pb-1.5 pt-2">
          <GitBranch size={13} className="text-pink" />
          <span className="flex-1 text-[10.5px] font-medium uppercase tracking-[.16em] text-muted">Branches</span>
          {list === null && <Spin className="h-3 w-3" />}
        </div>
        <div className="nxw-scroll max-h-[min(52vh,420px)] overflow-y-auto">
          <BranchRow name={mainName} current={!branch} running={!!list?.main.running} isMain onSelect={() => { go(null); setOpen(false); }} />
          {list?.branches.map((b) => (
            <BranchRow key={b.id} name={b.name} current={branch === b.name} running={!!b.running} branch={b} canEdit={canEdit}
              onSelect={() => { go(b.name); setOpen(false); }}
              onCompare={() => { useWs.getState().openCompare(b.name); setOpen(false); }}
              onMerge={() => { setMerge(b); setOpen(false); }}
              onDiscard={() => { setDiscard(b); setOpen(false); }} />
          ))}
          {list && !list.branches.length && (
            <div className="px-3 pb-2 pt-1 text-[12px] leading-relaxed text-muted">
              Branches are isolated copies of the project with their own chats and live preview. Merge them back into <span className="font-mono text-ink/80">{mainName}</span> when ready.
            </div>
          )}
        </div>
        {canEdit && (
          <div className="border-t border-line/70 p-1.5">
            {creating ? (
              <NewBranchForm mainName={mainName} current={branch} onDone={(name) => { setCreating(false); setOpen(false); if (name) go(name); }} />
            ) : (
              <button type="button" onClick={() => setCreating(true)} data-testid="new-branch"
                className="flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-[13px] text-hot transition-colors hover:bg-pink/10">
                <Plus size={14} /> New branch{branch ? <span className="text-muted">from {branch} or {mainName}</span> : ''}
              </button>
            )}
          </div>
        )}
      </Popover>
      <MergeModal branch={merge} mainName={mainName} onClose={() => setMerge(null)} onConflict={setConflict} />
      <DiscardModal branch={discard} onClose={() => setDiscard(null)} />
      <ConflictModal conflict={conflict} onClose={() => setConflict(null)} />
    </>
  );
}

function BranchRow({ name, current, running, isMain, branch, canEdit, onSelect, onCompare, onMerge, onDiscard }: {
  name: string; current: boolean; running: boolean; isMain?: boolean; branch?: Branch; canEdit?: boolean;
  onSelect: () => void; onCompare?: () => void; onMerge?: () => void; onDiscard?: () => void;
}) {
  const [renaming, setRenaming] = useState(false);
  const [v, setV] = useState(name);
  const commitRename = async () => {
    setRenaming(false);
    const to = sanitize(v);
    if (!to || to === name) return;
    try {
      await useWs.getState().renameBranch(name, to);
      if (current) window.history.replaceState(null, '', `${location.pathname}?branch=${encodeURIComponent(to)}`), useWs.setState({ branch: to });
      toast.success(`Renamed to ${to}`);
    } catch (e: any) { toast.error(e?.message || 'Rename failed'); }
  };
  return (
    <div className={clsx('group relative mx-1 flex items-center gap-2 rounded-lg px-2 py-1.5 transition-colors', current ? 'bg-pink/[.09]' : 'hover:bg-white/[.04]')}>
      {current && <span className="absolute bottom-1.5 left-0 top-1.5 w-[2px] rounded-full bg-pink shadow-[0_0_8px_var(--pink)]" />}
      <button type="button" onClick={onSelect} className="flex min-w-0 flex-1 items-center gap-2 text-left" data-testid={`branch-row-${name}`}>
        <span className="flex h-4 w-4 shrink-0 items-center justify-center">
          {running ? <Dot tone="pink" pulse /> : isMain ? <GitCommitHorizontal size={14} className="text-muted" /> : <span className="h-2 w-2 rotate-45 rounded-[2px] border border-violet/80 bg-violet/30" />}
        </span>
        {renaming ? (
          <input autoFocus value={v} onChange={(e) => setV(sanitize(e.target.value))} onClick={(e) => e.stopPropagation()}
            onKeyDown={(e) => { e.stopPropagation(); if (e.key === 'Enter') commitRename(); if (e.key === 'Escape') setRenaming(false); }} onBlur={commitRename}
            className="min-w-0 flex-1 rounded border border-pink/50 bg-bg px-1.5 py-0.5 font-mono text-[12.5px] text-ink outline-none" />
        ) : (
          <span className={clsx('min-w-0 flex-1 truncate font-mono text-[12.5px]', current ? 'text-ink' : 'text-ink/85')}>{name}</span>
        )}
        {isMain && <span className="shrink-0 rounded border border-line px-1 text-[9.5px] uppercase tracking-wider text-muted">main</span>}
        {branch && !renaming && <BranchStat b={branch} />}
        {current && !branch && <Check size={13} className="shrink-0 text-pink" />}
      </button>
      {branch && !renaming && (
        <div className="hidden shrink-0 items-center gap-0.5 group-hover:flex group-focus-within:flex">
          <IconBtn label="Compare with base" className="h-6 w-6" onClick={onCompare}><GitCompareArrows size={13} /></IconBtn>
          {canEdit && <IconBtn label={`Merge into ${branch.base === 'main' ? 'main' : 'main'}`} className="h-6 w-6 hover:text-ok" onClick={onMerge}><GitMerge size={13} /></IconBtn>}
          {canEdit && <IconBtn label="Rename" className="h-6 w-6" onClick={() => { setV(name); setRenaming(true); }}><Pencil size={12} /></IconBtn>}
          {canEdit && <IconBtn label="Discard branch" className="h-6 w-6 hover:text-bad" onClick={onDiscard}><Trash2 size={12} /></IconBtn>}
        </div>
      )}
    </div>
  );
}

function NewBranchForm({ mainName, current, onDone }: { mainName: string; current: string | null; onDone: (name: string | null) => void }) {
  const [name, setName] = useState('');
  const [base, setBase] = useState<string>(current ?? mainName);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const valid = BRANCH_RE.test(name) && name !== 'main' && name !== mainName;
  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!valid) { setErr('lowercase letters, digits, "-" and "/"'); return; }
    setBusy(true); setErr(null);
    try {
      const b = await useWs.getState().createBranch(name, base === mainName ? null : base);
      toast.success(`Branch ${b.name} created`, { description: `Preview at ${b.previewPath}` });
      onDone(b.name);
    } catch (e: any) { setErr(e?.message || 'Could not create branch'); }
    finally { setBusy(false); }
  };
  return (
    <form onSubmit={submit} className="flex flex-col gap-2 p-1">
      <div className="flex items-center gap-1.5 rounded-lg border border-line bg-bg/60 px-2 focus-within:border-pink/50">
        <GitBranch size={13} className="shrink-0 text-violet" />
        <input autoFocus value={name} onChange={(e) => { setName(sanitize(e.target.value)); setErr(null); }} placeholder="feature/login"
          className="h-8 min-w-0 flex-1 bg-transparent font-mono text-[12.5px] text-ink outline-none placeholder:text-muted/50"
          onKeyDown={(e) => { if (e.key === 'Escape') { e.stopPropagation(); onDone(null); } }} data-testid="new-branch-name" />
      </div>
      {current && (
        <div className="flex items-center gap-1 text-[11.5px] text-muted">
          from
          {[mainName, current].map((b) => (
            <button key={b} type="button" onClick={() => setBase(b)}
              className={clsx('rounded-md px-1.5 py-0.5 font-mono', base === b ? 'bg-pink/15 text-hot' : 'hover:bg-white/5')}>{b}</button>
          ))}
        </div>
      )}
      {err && <div className="px-0.5 text-[11.5px] text-bad">{err}</div>}
      <div className="flex justify-end gap-1.5">
        <Button size="sm" variant="ghost" onClick={() => onDone(null)}>Cancel</Button>
        <Button size="sm" variant="primary" type="submit" loading={busy} disabled={!name}>Create</Button>
      </div>
    </form>
  );
}

function MergeModal({ branch, mainName, onClose, onConflict }: {
  branch: Branch | null; mainName: string; onClose: () => void; onConflict: (c: { branch: string; files: string[]; prompt: string }) => void;
}) {
  const [close, setClose] = useState(true);
  const [busy, setBusy] = useState(false);
  const current = useWs((s) => s.branch);
  const go = useBranchNav();
  useEffect(() => { if (branch) setClose(true); }, [branch]);
  if (!branch) return null;
  const run = async () => {
    setBusy(true);
    try {
      const r = await useWs.getState().mergeBranch(branch.name, close);
      onClose();
      if (!r.ok) { onConflict({ branch: branch.name, files: r.conflicts ?? [], prompt: r.resolvePrompt ?? '' }); return; }
      toast.success(`Merged ${branch.name} into ${r.into ?? mainName}`, { description: r.closed ? 'Branch closed; its chats moved to main.' : undefined });
      if (r.closed && current === branch.name) go(null);
    } catch (e: any) { toast.error(e?.message || 'Merge failed'); }
    finally { setBusy(false); }
  };
  return (
    <Modal open onClose={onClose} size="sm" icon={<GitMerge size={18} />} title={`Merge ${branch.name}`}
      description={<>into <span className="font-mono text-ink/90">{mainName}</span> as a merge commit. Pending edits on both sides are checkpointed first.</>}
      footer={<><Button variant="ghost" onClick={onClose}>Cancel</Button><Button variant="primary" loading={busy} onClick={run} icon={<GitMerge size={14} />} data-testid="merge-confirm">Merge</Button></>}>
      <div className="flex items-center gap-3 rounded-lg border border-line/70 bg-bg/50 px-3 py-2.5 text-[12.5px]">
        <BranchStat b={branch} />
        <span className="text-muted">{branch.filesChanged ? 'changed vs base' : 'no file changes detected'}</span>
      </div>
      <label className="mt-3 flex cursor-pointer items-start gap-2.5 text-[13px]">
        <input type="checkbox" className="mt-0.5 accent-[var(--pink)]" checked={close} onChange={(e) => setClose(e.target.checked)} />
        <span><span className="text-ink">Close the branch after merging</span><span className="block text-[11.5px] text-muted">Removes its worktree and preview; its chats continue on {mainName}.</span></span>
      </label>
    </Modal>
  );
}

function DiscardModal({ branch, onClose }: { branch: Branch | null; onClose: () => void }) {
  const [busy, setBusy] = useState(false);
  const current = useWs((s) => s.branch);
  const go = useBranchNav();
  if (!branch) return null;
  const run = async () => {
    setBusy(true);
    try {
      await useWs.getState().discardBranch(branch.name);
      toast.success(`Discarded ${branch.name}`);
      onClose();
      if (current === branch.name) go(null);
    } catch (e: any) { toast.error(e?.message || 'Discard failed'); }
    finally { setBusy(false); }
  };
  return (
    <Modal open onClose={onClose} size="sm" icon={<Trash2 size={18} />} title={`Discard ${branch.name}?`}
      description="Deletes the branch, its files and its preview. Changes not merged are lost. Its chats move to main."
      footer={<><Button variant="ghost" onClick={onClose}>Cancel</Button><Button variant="danger" loading={busy} onClick={run}>Discard branch</Button></>}>
      {!!branch.filesChanged && <div className="flex items-center gap-2 text-[12.5px] text-warn"><TriangleAlert size={14} /> {branch.filesChanged} changed file{branch.filesChanged === 1 ? '' : 's'} will be lost.</div>}
    </Modal>
  );
}

function ConflictModal({ conflict, onClose }: { conflict: { branch: string; files: string[]; prompt: string } | null; onClose: () => void }) {
  const go = useBranchNav();
  const canEdit = useWs((s) => s.canEdit);
  if (!conflict) return null;
  const ask = () => {
    const s = useWs.getState();
    onClose();
    if (s.branch === conflict.branch) { s.selectConversation(null).then(() => s.send(conflict.prompt)); return; }
    useWs.setState({ pendingPrompt: conflict.prompt });
    go(conflict.branch);
  };
  return (
    <Modal open onClose={onClose} size="md" icon={<TriangleAlert size={18} className="text-warn" />} title="Merge conflicts"
      description={<>Nothing was changed on main. These files were edited on both sides of <span className="font-mono text-ink/90">{conflict.branch}</span>:</>}
      footer={<>
        <Button variant="ghost" onClick={onClose}>Close</Button>
        {canEdit && <Button variant="primary" icon={<Sparkles size={14} />} onClick={ask} data-testid="resolve-with-claude">Ask Claude to resolve</Button>}
      </>}>
      <ul className="nxw-scroll max-h-48 space-y-1 overflow-y-auto">
        {conflict.files.map((f) => (
          <li key={f} className="flex items-center gap-2 rounded-md bg-warn/[.06] px-2.5 py-1.5 font-mono text-[12px] text-ink/90"><TriangleAlert size={12} className="shrink-0 text-warn" />{f}</li>
        ))}
      </ul>
      <p className="mt-3 text-[12px] text-muted">Claude will merge main into the branch, resolve the conflicts there and commit — then merge again.</p>
    </Modal>
  );
}

// ---------------------------------------------------------------- history

export function HistoryButton() {
  const [el, setEl] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  useEffect(() => { if (open) useWs.getState().loadHistory(); }, [open]);
  return (
    <>
      <IconBtn label="Checkpoints & history" side="bottom" active={open} btnRef={setEl} onClick={() => setOpen((o) => !o)} data-testid="history-btn"><History size={15} /></IconBtn>
      <Popover open={open} anchor={el} onClose={() => setOpen(false)} side="bottom" align="end" className="w-[380px] max-w-[calc(100vw-16px)]">
        <HistoryPanel onNavigate={() => setOpen(false)} />
      </Popover>
    </>
  );
}

function HistoryPanel({ onNavigate }: { onNavigate: () => void }) {
  const history = useWs((s) => s.history);
  const loading = useWs((s) => s.historyLoading);
  const canEdit = useWs((s) => s.canEdit);
  const branch = useWs((s) => s.branch);
  const [busy, setBusy] = useState<string | null>(null);
  const checkpoint = async () => {
    setBusy('cp');
    const sha = await useWs.getState().checkpointNow();
    setBusy(null);
    toast[sha ? 'success' : 'info'](sha ? `Checkpoint ${sha.slice(0, 7)} saved` : 'Nothing to checkpoint — no changes since the last one');
  };
  const undo = async (c: HistoryCommit) => {
    if (!c.run && !window.confirm(`Revert “${shortMsg(c.message)}”? A new commit undoes its changes.`)) return;
    setBusy(c.sha);
    const r = await useWs.getState().undo(c.run ? { runId: c.run.id } : { sha: c.sha });
    setBusy(null);
    if (r.ok) toast.success('Undone', { description: 'A revert commit was added; files are restored.' });
    else if (r.conflicts?.length) toast.error('Could not undo cleanly', { description: `Later changes touch: ${r.conflicts.join(', ')}` });
  };
  const openConv = (id: string) => { useWs.getState().selectConversation(id); onNavigate(); };
  return (
    <div className="flex max-h-[min(70vh,560px)] flex-col">
      <div className="flex items-center gap-2 px-2.5 pb-2 pt-2">
        <History size={13} className="text-pink" />
        <div className="min-w-0 flex-1">
          <div className="text-[10.5px] font-medium uppercase tracking-[.16em] text-muted">Checkpoints</div>
          <div className="truncate font-mono text-[11px] text-muted/80">{history?.checkout ?? branch ?? 'main'}{history?.dirty ? ' · uncommitted changes' : ''}</div>
        </div>
        {canEdit && <Button size="xs" variant="outline" icon={busy === 'cp' ? <Spin className="h-3 w-3" /> : <Save size={12} />} onClick={checkpoint} disabled={!!busy} data-testid="checkpoint-now">Checkpoint now</Button>}
      </div>
      <div className="nxw-scroll min-h-0 flex-1 overflow-y-auto border-t border-line/60 px-1 py-1">
        {loading && !history && <div className="flex justify-center py-8"><Spin /></div>}
        {history && !history.commits.length && <div className="px-3 py-6 text-center text-[12.5px] text-muted">No checkpoints yet.</div>}
        <ol className="relative">
          {history?.commits.map((c, i) => {
            const isRun = !!c.run;
            const reverted = c.run?.undone;
            const isRevert = /^Revert "/.test(c.message);
            return (
              <li key={c.sha} className="group relative flex gap-2.5 rounded-lg px-2 py-1.5 hover:bg-white/[.03]">
                <div className="relative flex w-3 shrink-0 justify-center">
                  {i < history.commits.length - 1 && <span className="absolute bottom-[-10px] top-4 w-px bg-line" />}
                  <span className={clsx('mt-1.5 h-2.5 w-2.5 rounded-full border', c.isMerge ? 'border-ok bg-ok/30' : isRun ? 'border-pink bg-pink/30 shadow-[0_0_8px_-1px_var(--pink)]' : isRevert ? 'border-warn bg-warn/20' : 'border-muted/60 bg-bg')} />
                </div>
                <div className="min-w-0 flex-1">
                  <div className={clsx('truncate text-[12.5px]', reverted ? 'text-muted line-through decoration-muted/50' : 'text-ink/90')} title={c.message}>
                    {c.isMerge && <GitMerge size={11} className="mr-1 inline text-ok" />}{shortMsg(c.message)}
                  </div>
                  <div className="mt-0.5 flex items-center gap-1.5 font-mono text-[10.5px] text-muted">
                    <span>{c.short}</span><span>·</span><span>{timeAgo(c.time)}</span>
                    {c.filesChanged > 0 && <><span>·</span><span>{c.filesChanged}f</span><span className="text-ok/80">+{c.insertions}</span><span className="text-bad/80">−{c.deletions}</span></>}
                  </div>
                  {c.run && (
                    <button type="button" onClick={() => openConv(c.run!.conversationId)} className="mt-0.5 flex max-w-full items-center gap-1 truncate text-[11px] text-pink/80 hover:text-hot">
                      <CornerDownRight size={10} className="shrink-0" /><span className="truncate">{c.run.conversationTitle || 'conversation'}</span>
                    </button>
                  )}
                </div>
                {canEdit && !c.isMerge && !c.isRoot && !reverted && !isRevert && (
                  <button type="button" onClick={() => undo(c)} disabled={!!busy} data-testid="undo-commit"
                    className={clsx('flex h-6 shrink-0 items-center gap-1 self-center rounded-md border border-line px-1.5 text-[11px] text-muted transition-colors hover:border-warn/50 hover:text-warn',
                      !isRun && 'opacity-0 group-hover:opacity-100')}>
                    {busy === c.sha ? <Spin className="h-3 w-3" /> : <Undo2 size={11} />} {isRun ? 'Undo run' : 'Revert'}
                  </button>
                )}
                {reverted && <span className="self-center rounded border border-line px-1 text-[9.5px] uppercase tracking-wider text-muted">undone</span>}
              </li>
            );
          })}
        </ol>
      </div>
      <div className="border-t border-line/60 px-3 py-1.5 text-[10.5px] text-muted/80">Every successful run is checkpointed automatically.</div>
    </div>
  );
}

// ---------------------------------------------------------------- breadcrumb

export function ProjectCrumb({ compact }: { compact?: boolean }) {
  const project = useWs((s) => s.project);
  const family = useWs((s) => s.family);
  const canEdit = useWs((s) => s.canEdit);
  const [el, setEl] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  const nav = useNavigate();
  const color = project?.color || 'var(--pink)';
  const parent = family.parent;
  const items = useMemo(() => (parent ? family.siblings : family.children), [parent, family]);
  useEffect(() => { if (open) useWs.getState().loadFamily(); }, [open]);
  if (!project) return null;
  const isTop = !project.parentId;
  const addSub = () => {
    setOpen(false);
    useUI.getState().setNewProject(true, { id: project.id, name: project.name, color: project.color, icon: project.icon });
  };
  return (
    <div className="flex min-w-0 items-center gap-1.5">
      {parent && !compact && (
        <>
          <Link to={`/p/${parent.slug}`} className="flex min-w-0 items-center gap-1.5 rounded-md px-1 py-0.5 text-[12px] text-muted transition-colors hover:bg-white/5 hover:text-ink" data-testid="crumb-parent">
            <span className="h-2 w-2 shrink-0 rounded-full" style={{ background: parent.color }} />
            <span className="max-w-[120px] truncate font-display tracking-[.08em]">{parent.name}</span>
          </Link>
          <span className="text-muted/40">/</span>
        </>
      )}
      <button ref={setEl} type="button" onClick={() => setOpen((o) => !o)} data-testid="crumb-project"
        className={clsx('flex min-w-0 items-center gap-2 rounded-md px-1 py-0.5 transition-colors hover:bg-white/5', open && 'bg-white/5')}>
        <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: color, boxShadow: `0 0 12px ${color}` }} />
        <span className="truncate font-display text-[13px] tracking-[.1em] text-ink">{project.name}</span>
        {(items.length > 0 || (isTop && canEdit) || parent) && <ChevronDown size={12} className="shrink-0 text-muted" />}
      </button>
      <Popover open={open} anchor={el} onClose={() => setOpen(false)} side="bottom" align="start" className="w-[290px] max-w-[calc(100vw-16px)]">
        {parent && (
          <button type="button" onClick={() => { setOpen(false); nav(`/p/${parent.slug}`); }} className="flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left hover:bg-white/5">
            <ProjectBadge name={parent.icon} color={parent.color} size={24} />
            <span className="min-w-0 flex-1"><span className="block truncate text-[13px] text-ink">{parent.name}</span><span className="block text-[10.5px] uppercase tracking-wider text-muted">parent</span></span>
          </button>
        )}
        <div className="px-2.5 pb-1 pt-1.5 text-[10.5px] font-medium uppercase tracking-[.16em] text-muted">{parent ? 'Siblings' : 'Sub-projects'}</div>
        {!items.length && <div className="px-2.5 pb-2 text-[12px] text-muted">{isTop ? 'No sub-projects yet — split big work into website, api, admin…' : 'No siblings.'}</div>}
        {items.map((p) => (
          <button key={p.id} type="button" onClick={() => { setOpen(false); if (p.id !== project.id) nav(`/p/${p.slug}`); }}
            className={clsx('flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left', p.id === project.id ? 'bg-pink/[.08]' : 'hover:bg-white/5')}>
            <span className="flex w-4 justify-center"><CornerDownRight size={12} className="text-muted/60" /></span>
            <ProjectBadge name={p.icon} color={p.color} size={22} />
            <span className="min-w-0 flex-1 truncate text-[13px] text-ink/90">{p.name}</span>
            {p.id === project.id ? <Check size={13} className="text-pink" /> : <ChevronRight size={13} className="text-muted/50" />}
          </button>
        ))}
        {isTop && canEdit && (
          <div className="mt-1 border-t border-line/60 pt-1">
            <button type="button" onClick={addSub} data-testid="add-subproject" className="flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-[13px] text-hot hover:bg-pink/10">
              <FolderTree size={14} /> Sub-project
            </button>
          </div>
        )}
      </Popover>
    </div>
  );
}

