// Branch "Compare" view (Code tab): files changed vs the branch's base + Monaco diff editor.
// Lazy-loaded together with CodePane (Monaco).
import { useEffect, useRef, useState } from 'react';
import { DiffEditor } from '@monaco-editor/react';
import clsx from 'clsx';
import { GitCompareArrows, GitMerge, RotateCw, X, FileWarning } from 'lucide-react';
import { useWs } from './store';
import { langFromPath } from './toolFormat';
import { IconBtn, Spin } from './ui';

const STATUS: Record<string, { l: string; c: string }> = {
  added: { l: 'A', c: 'text-ok' },
  deleted: { l: 'D', c: 'text-bad' },
  modified: { l: 'M', c: 'text-warn' },
};

export default function CompareView() {
  const compare = useWs((s) => s.compare)!;
  const branch = useWs((s) => s.branchList?.branches.find((b) => b.name === s.compare?.branch));
  const { selectCompareFile, closeCompare, openCompare } = useWs.getState();
  const box = useRef<HTMLDivElement>(null);
  const [wide, setWide] = useState(true);
  useEffect(() => {
    const el = box.current; if (!el) return;
    const ro = new ResizeObserver(() => setWide(el.clientWidth >= 620));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const s = compare.summary;
  const files = s?.files ?? [];
  const f = compare.file;

  return (
    <div ref={box} className="flex h-full min-h-0 flex-col" data-testid="compare-view">
      <div className="flex h-9 shrink-0 items-center gap-2 border-b border-line/70 bg-panel/40 px-2.5">
        <GitCompareArrows size={14} className="shrink-0 text-violet" />
        <div className="flex min-w-0 flex-1 items-center gap-1.5 font-mono text-[12px]">
          <span className="truncate text-ink">{compare.branch}</span>
          <span className="shrink-0 text-muted/60">vs</span>
          <span className="shrink-0 text-muted">{s?.base ?? branch?.base ?? 'main'}</span>
        </div>
        {s && (
          <span className="shrink-0 font-mono text-[11px]">
            <span className="text-muted">{files.length} file{files.length === 1 ? '' : 's'}</span>{' '}
            <span className="text-ok">+{s.additions}</span> <span className="text-bad">−{s.deletions}</span>
          </span>
        )}
        <IconBtn label="Refresh" onClick={() => openCompare(compare.branch)}><RotateCw size={13} className={clsx(compare.loading && 'animate-spin')} /></IconBtn>
        <IconBtn label="Close compare" onClick={closeCompare}><X size={14} /></IconBtn>
      </div>
      {compare.error && <div className="shrink-0 border-b border-bad/30 bg-bad/[.07] px-3 py-1.5 text-[12px] text-bad">{compare.error}</div>}
      <div className={clsx('flex min-h-0 flex-1', wide ? 'flex-row' : 'flex-col')}>
        <ul className={clsx('nxw-scroll shrink-0 overflow-y-auto bg-panel/30 py-1', wide ? 'w-[220px] border-r border-line/60' : 'max-h-[34%] border-b border-line/60')}>
          {compare.loading && !s && <li className="flex justify-center py-6"><Spin /></li>}
          {s && !files.length && (
            <li className="px-4 py-8 text-center text-[12.5px] text-muted">
              <GitMerge size={20} className="mx-auto mb-2 text-pink/50" />No changes vs {s.base} yet.
            </li>
          )}
          {files.map((x) => {
            const st = STATUS[x.status] ?? STATUS.modified;
            const on = x.path === compare.selected;
            const name = x.path.split('/').pop();
            const dir = x.path.slice(0, x.path.length - (name?.length ?? 0));
            return (
              <li key={x.path}>
                <button type="button" onClick={() => selectCompareFile(x.path)} title={x.path}
                  className={clsx('relative flex w-full items-center gap-2 px-2.5 py-1 text-left text-[12px] transition-colors', on ? 'bg-pink/[.10] text-ink' : 'text-ink/80 hover:bg-white/[.04]')}>
                  {on && <span className="absolute bottom-1 left-0 top-1 w-[2px] rounded-full bg-pink" />}
                  <span className={clsx('w-3 shrink-0 font-mono text-[10.5px] font-semibold', st.c)}>{st.l}</span>
                  <span className="min-w-0 flex-1 truncate"><span className="text-muted/70">{dir}</span>{name}</span>
                  {x.binary ? <span className="shrink-0 text-[10px] text-muted">bin</span> : (
                    <span className="shrink-0 font-mono text-[10px]"><span className="text-ok/80">+{x.additions}</span> <span className="text-bad/80">−{x.deletions}</span></span>
                  )}
                </button>
              </li>
            );
          })}
        </ul>
        <div className="relative min-h-0 min-w-0 flex-1 bg-[#0a070d]">
          {compare.fileLoading && <div className="absolute right-3 top-2 z-10"><Spin /></div>}
          {f && f.binary ? (
            <div className="flex h-full flex-col items-center justify-center gap-2 text-[13px] text-muted"><FileWarning size={20} /> Binary file — no text diff.</div>
          ) : f ? (
            <DiffEditor
              key={`${compare.branch}:${f.path}`}
              original={f.original}
              modified={f.modified}
              language={langFromPath(f.path)}
              theme="nxeon"
              loading={<Spin />}
              options={{
                readOnly: true,
                originalEditable: false,
                renderSideBySide: wide,
                fontFamily: '"JetBrains Mono", ui-monospace, monospace',
                fontSize: 12.5,
                lineHeight: 19,
                minimap: { enabled: false },
                scrollBeyondLastLine: false,
                automaticLayout: true,
                renderOverviewRuler: false,
                padding: { top: 8, bottom: 8 },
                scrollbar: { verticalScrollbarSize: 10, horizontalScrollbarSize: 10 },
              }}
            />
          ) : !compare.loading && files.length ? (
            <div className="flex h-full items-center justify-center text-[13px] text-muted">Pick a file to see its diff.</div>
          ) : null}
        </div>
      </div>
    </div>
  );
}

