start=s.index('function ConversationList() {')
end=s.index('export function LeftRail(')
new='''const TOPIC_SWATCHES = ['#ff6fae', '#ff8a5c', '#b14bff', '#3dffb5', '#ffc857', '#5ce1ff', '#ff4d6d', '#f6e9f0'];

function ConversationRow({ c, active, running, canEdit, renaming, setRenaming, onMenu }: {
  c: Conversation; active: boolean; running: boolean; canEdit: boolean; renaming: boolean;
  setRenaming: (id: string | null) => void; onMenu: (e: React.MouseEvent, id: string) => void;
}) {
  const { selectConversation, renameConversation } = useWs.getState();
  return (
    <div role="button" tabIndex={0} data-testid="conv-row"
      onClick={() => selectConversation(c.id)}
      onDoubleClick={() => canEdit && setRenaming(c.id)}
      onContextMenu={(e) => { e.preventDefault(); onMenu(e, c.id); }}
      draggable={canEdit}
      onDragStart={(e) => { e.dataTransfer.setData('application/x-nx-conv', c.id); e.dataTransfer.effectAllowed = 'move'; }}
      className={clsx('group relative flex cursor-pointer items-center gap-2 rounded-lg px-2.5 py-2 transition-colors',
        active ? 'bg-pink/[.10] text-ink' : 'text-ink/75 hover:bg-white/[.04] hover:text-ink')}>
      {active && <span className="absolute left-0 top-2 bottom-2 w-[2px] rounded-full bg-pink shadow-[0_0_8px_var(--pink)]" />}
      {running ? <Spin className="h-3 w-3 shrink-0" /> : <MessageSquare size={14} className={clsx('shrink-0', active ? 'text-pink' : 'text-muted/60')} />}
      {renaming ? (
        <InlineInput initial={c.title || ''} onCancel={() => setRenaming(null)} onCommit={(v) => { setRenaming(null); renameConversation(c.id, v); }} />
      ) : (
        <span className="min-w-0 flex-1 truncate text-[13px]">{c.title || 'Untitled'}</span>
      )}
      <span className="shrink-0 text-[10.5px] text-muted/60 group-hover:hidden">{relTime(c.updatedAt || c.createdAt)}</span>
      {canEdit && (
        <button type="button" onClick={(e) => { e.stopPropagation(); onMenu(e, c.id); }}
          className="hidden h-5 w-5 shrink-0 items-center justify-center rounded text-muted hover:bg-white/10 hover:text-ink group-hover:flex">
          <Ellipsis size={13} />
        </button>
      )}
    </div>
  );
}

function TopicHeader({ topic, count, collapsed, canEdit, onToggle, onMenu, onDropConv }: {
  topic: Topic | null; count: number; collapsed: boolean; canEdit: boolean; onToggle: () => void;
  onMenu?: (e: React.MouseEvent) => void; onDropConv: (convId: string) => void;
}) {
  const [over, setOver] = useState(false);
  const [renaming, setRenaming] = useState(false);
  const { updateTopic } = useWs.getState();
  return (
    <div
      onDragOver={(e) => { if (canEdit && e.dataTransfer.types.includes('application/x-nx-conv')) { e.preventDefault(); setOver(true); } }}
      onDragLeave={() => setOver(false)}
      onDrop={(e) => { setOver(false); const id = e.dataTransfer.getData('application/x-nx-conv'); if (id) onDropConv(id); }}
      onContextMenu={(e) => { if (topic && onMenu) { e.preventDefault(); onMenu(e); } }}
      className={clsx('group mt-1 flex h-7 cursor-pointer select-none items-center gap-1.5 rounded-md px-1.5 transition-colors',
        over ? 'bg-pink/15 ring-1 ring-pink/50' : 'hover:bg-white/[.03]')}
      onClick={onToggle} data-testid={topic ? 'topic-header' : 'topic-header-none'}>
      <ChevronRight size={12} className={clsx('shrink-0 text-muted/60 transition-transform', !collapsed && 'rotate-90')} />
      {topic ? <span className="h-2 w-2 shrink-0 rounded-full" style={{ background: topic.color, boxShadow: `0 0 8px -1px ${topic.color}` }} />
        : <span className="h-2 w-2 shrink-0 rounded-full border border-muted/50" />}
      {renaming && topic ? (
        <InlineInput initial={topic.name} onCancel={() => setRenaming(false)} onCommit={(v) => { setRenaming(false); updateTopic(topic.id, { name: v }); }} />
      ) : (
        <span onDoubleClick={(e) => { if (topic && canEdit) { e.stopPropagation(); setRenaming(true); } }}
          className="min-w-0 flex-1 truncate text-[11px] font-medium uppercase tracking-[.12em] text-muted group-hover:text-ink/80">{topic ? topic.name : 'No topic'}</span>
      )}
      <span className="shrink-0 rounded-full bg-white/[.05] px-1.5 text-[10px] text-muted">{count}</span>
      {topic && canEdit && onMenu && (
        <button type="button" onClick={(e) => { e.stopPropagation(); onMenu(e); }}
          className="hidden h-5 w-5 shrink-0 items-center justify-center rounded text-muted hover:bg-white/10 hover:text-ink group-hover:flex">
          <Ellipsis size={12} />
        </button>
      )}
    </div>
  );
}

function ConversationList() {
  const conversations = useWs((s) => s.conversations);
  const activeConvId = useWs((s) => s.activeConvId);
  const convLoading = useWs((s) => s.convLoading);
  const canEdit = useWs((s) => s.canEdit);
  const topics = useWs((s) => s.topics);
  const collapsed = useWs((s) => s.collapsedTopics);
  const topicFilter = useWs((s) => s.topicFilter);
  const branch = useWs((s) => s.branch);
  const runningConv = useWs((s) => (s.items.some((i) => i.runId && s.runs[i.runId] && !isTerminal(s.runs[i.runId].status)) ? s.activeConvId : null));
  const { newConversation, deleteConversation, moveConversation, createTopic, deleteTopic, updateTopic, toggleTopic, setTopicFilter } = useWs.getState();
  const [renaming, setRenaming] = useState<string | null>(null);
  const [menu, setMenu] = useState<{ at: { x: number; y: number }; id: string } | null>(null);
  const [topicMenu, setTopicMenu] = useState<{ at: { x: number; y: number }; id: string } | null>(null);
  const [newTopic, setNewTopic] = useState<null | { forConv?: string }>(null);
  const [q, setQ] = useState('');
  const filtered = q ? conversations.filter((c) => (c.title || '').toLowerCase().includes(q.toLowerCase())) : conversations;
  const list = topicFilter ? filtered.filter((c) => c.topicId === topicFilter) : filtered;
  const filterTopic = topics.find((t) => t.id === topicFilter) ?? null;
  const grouped = topics.length > 0 && !topicFilter;
  const groups = useMemo(() => {
    if (!grouped) return [];
    const known = new Set(topics.map((t) => t.id));
    const by = new Map<string | null, Conversation[]>();
    for (const c of list) {
      const k = c.topicId && known.has(c.topicId) ? c.topicId : null;
      const arr = by.get(k) ?? [];
      arr.push(c);
      by.set(k, arr);
    }
    const out: { topic: Topic | null; items: Conversation[] }[] = topics.map((t) => ({ topic: t, items: by.get(t.id) ?? [] }));
    out.push({ topic: null, items: by.get(null) ?? [] });
