private positionHoverEl() {
  const el = this.hoverEl;
  if (!el) return;
  const n = this.hovered && (this.hovered.kind === 'project' || isSat(this.hovered)) ? this.hovered : null;
  if (!n) return;
  const p = this.screenPos(n);
  const r = (isSat(n) ? n.r * (0.42 + 0.58 * n.vis) : n.r) * this.cam.k;
  const w = el.offsetWidth || 260, h = el.offsetHeight || 120;
  let x = p.x + r + 28, y = p.y - h / 2;
  if (x + w > this.W - 12) x = p.x - r - 28 - w;
  y = Math.max(12, Math.min(this.H - h - 12, y));

