#!/usr/bin/env node
// Mock `claude` CLI emitting realistic `--output-format stream-json --verbose
// --include-partial-messages` output (shapes captured from Claude Code 2.1.287).
// Scenario is chosen from the prompt text:
//   contains "SLOW"     -> init, then streams slowly for ~60s (abort tests)
//   contains "AUTHFAIL" -> identical to a real unauthenticated run (exit 1)
//   contains "CRASH"    -> stderr + exit 2 without a result line
//   contains "TASKS"    -> uses TaskCreate/TaskUpdate (Claude Code >= 2.1 todo tools)
//   starts with "/compact" -> manual compaction (shapes captured from 2.1.287)
//   contains "DELEGATE" -> Agent tool + subagent (forwarded text, usage with parent_tool_use_id)
//   otherwise           -> thinking + text + TodoWrite + Bash + tool_result + result
// Env MOCK_ARGS_FILE: write {args, cwd, env subset} as JSON there.

const fs = require("fs");
const args = process.argv.slice(2);

if (args[0] === "--version" || args[0] === "-v") {
  process.stdout.write("2.1.287 (Claude Code)\n");
  process.exit(0);
}
if (args[0] === "--help" || args[0] === "-h") {
  process.stdout.write(`Usage: claude [options] [command] [prompt]
  --include-partial-messages            Include partial message chunks
  --permission-mode <mode>              Permission mode to use for the session
                                        (choices: "acceptEdits", "auto",
                                        "bypassPermissions", "manual",
                                        "dontAsk", "plan")
  --permission-prompts <target>         Who answers permission prompts
  --effort <level>                      Effort level
  --autocompact <auto|tokens>           Auto-compact window size
  --agents <json-or-file>               JSON object defining custom agents
  --agent <agent>                       Agent for the current session
  --forward-subagent-text               Forward subagent text and thinking
`);
  process.exit(0);
}

const dd = args.indexOf("--");
const prompt = dd >= 0 ? args.slice(dd + 1).join(" ") : args[args.length - 1] || "";
const modelIdx = args.indexOf("--model");

