// Seed the local QA stack with projects, sub-projects, branches, topics and a few runs.
const B = process.env.BASE || 'http://127.0.0.1:8901';
let cookie = '';
async function api(method, path, body) {
  const r = await fetch(B + '/api' + path, { method, headers: { cookie, 'x-requested-with': 'qa', ...(body ? { 'content-type': 'application/json' } : {}) }, body: body ? JSON.stringify(body) : undefined });
  const sc = r.headers.get('set-cookie'); if (sc) cookie = sc.split(';')[0];
  const t = await r.text(); let j; try { j = JSON.parse(t); } catch { j = t; }
  if (!r.ok) throw new Error(`${method} ${path} ${r.status} ${t}`);
  return j;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await api('POST', '/auth/login', { email: 'qa@test.local', password: 'qa-password-123' });
const html = (t, c) => `<!doctype html><html><head><meta charset="utf-8"><title>${t}</title><style>body{font-family:system-ui;background:${c};color:#fff;display:grid;place-items:center;height:100vh;margin:0}h1{font-size:48px}</style></head><body><h1>${t}</h1></body></html>`;
const mk = async (name, extra = {}) => api('POST', '/projects', { name, description: `${name} — QA seed project`, ...extra });
const nx = await mk('Nxeon', { color: '#ff3e8a', icon: 'cpu' });
const kids = [];
for (const n of ['website', 'api', 'admin']) kids.push(await mk(n, { parentId: nx.id }));
const shop = await mk('Neon Shop', { color: '#ff8a5c', icon: 'cart' });
const others = [];
for (const [n, c, i] of [['Goonies Fan Page', '#ffc857', 'flame'], ['Synth Lab', '#b14bff', 'music'], ['Data Forge', '#3dffb5', 'database'], ['Pixel Arcade', '#ff6fae', 'gamepad'], ['Docs Hub', '#5ce1ff', 'book'], ['Bot Garage', '#ff4d6d', 'bot']]) others.push(await mk(n, { color: c, icon: i }));
await sleep(1500);
for (const p of [nx, shop, kids[0], others[0]]) await api('PUT', `/projects/${p.id}/files/content`, { path: 'index.html', content: html(p.name, '#1a0d1a') });
await sleep(800);
await api('POST', `/projects/${shop.id}/checkpoint`, { message: 'site skeleton' });
await api('POST', `/projects/${nx.id}/checkpoint`, { message: 'landing page' });
// branches
const b1 = await api('POST', `/projects/${shop.id}/branches`, { name: 'feature/cart' });
