import { chromium } from 'playwright';
const BASE = process.env.BASE || 'http://127.0.0.1:8901';
const EMAIL = process.env.EMAIL || 'qa@test.local';
const PASS = process.env.PASS || 'qa-password-123';
const OUT = process.env.OUT || 'shots';
const only = process.argv.slice(2);
const want = (n) => !only.length || only.includes(n);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const browser = await chromium.launch({ args: ['--host-resolver-rules=MAP workspace.trynxeon.com 127.0.0.1'] });
const problems = [];
async function ctxPage(viewport = { width: 1600, height: 960 }, mobile = false) {
  const ctx = await browser.newContext({ viewport, ...(mobile ? { isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : {}) });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => { problems.push(`PAGEERROR ${e.message}`); console.log('PAGEERROR', e.message); });
  page.on('console', (m) => { if (m.type() === 'error') { problems.push(`console ${m.text().slice(0, 300)}`); console.log('console.error', m.text().slice(0, 300)); } });
  page.on('response', (r) => { if (r.status() >= 400 && !r.url().includes('/preview/')) console.log('HTTP', r.status(), r.request().method(), r.url().replace(BASE, '')); });
  await page.goto(BASE + '/login', { waitUntil: 'networkidle' });
  await page.locator('input[type=email], input[name=email], input[autocomplete=username]').first().fill(EMAIL);
  await page.locator('input[type=password]').first().fill(PASS);
  await page.keyboard.press('Enter');
  await page.waitForURL((u) => !u.pathname.startsWith('/login'));
  return page;
}
const shot = async (page, n) => { await page.screenshot({ path: `${OUT}/${n}.png` }); console.log('shot', n); };
const SHOP = process.env.SHOP || 'neon-shop';
const CHILD = process.env.CHILD || 'website';

if (want('nexus')) {
  const p = await ctxPage();
  await p.evaluate(() => { localStorage.removeItem('nx.nexus.sats'); localStorage.removeItem('nx.nexus.pos.v1'); });
  await p.goto(BASE + '/', { waitUntil: 'networkidle' }); await sleep(2500);
  await shot(p, '01-nexus-collapsed');
  await p.keyboard.press('s'); await sleep(1800);
  await shot(p, '02-nexus-expanded-toggle');
  await p.keyboard.press('s'); await sleep(1200);
  // zoom in past the semantic-zoom threshold
  for (let i = 0; i < 5; i++) { await p.mouse.move(800, 480); await p.mouse.wheel(0, -260); await sleep(120); }
  await sleep(1500);
  await shot(p, '03-nexus-zoomed');
  await p.close();
}
if (want('hover')) {
  const p = await ctxPage();
  await p.goto(BASE + '/', { waitUntil: 'networkidle' }); await sleep(2000);
  // find a node with satellites via the engine (exposed for QA through the canvas element)
  const pos = await p.evaluate(() => (window).__nxProbe?.());
  console.log('probe', JSON.stringify(pos));
  if (pos?.project) {
    await p.mouse.move(pos.project.x, pos.project.y); await sleep(1400);
    await shot(p, '04-nexus-hover-project');
    const sat = await p.evaluate(() => (window).__nxProbe?.());
    const b = sat?.branch;
    if (b) { await p.mouse.move(b.x, b.y, { steps: 6 }); await sleep(900); await shot(p, '05-nexus-hover-branch'); }
    const s2 = await p.evaluate(() => (window).__nxProbe?.());
    if (s2?.sub) { await p.mouse.move(s2.sub.x, s2.sub.y, { steps: 6 }); await sleep(900); await shot(p, '06-nexus-hover-sub'); }
  }
  await p.close();
}
if (want('ws')) {
  const p = await ctxPage();
  await p.goto(`${BASE}/p/${SHOP}`, { waitUntil: 'networkidle' }); await sleep(1500);
  await p.getByTestId('branch-chip').click(); await sleep(900);
  await shot(p, '10-branch-switcher');
  await p.getByTestId('new-branch').click(); await sleep(300);
  await p.getByTestId('new-branch-name').fill('promo-banner');
  await shot(p, '11-new-branch-form');
  await p.keyboard.press('Escape'); await p.keyboard.press('Escape'); await sleep(300);
  await p.goto(`${BASE}/p/${SHOP}?branch=feature%2Fcart`, { waitUntil: 'networkidle' }); await sleep(1800);
  await shot(p, '12-on-branch');
  await p.getByTestId('branch-chip').click(); await sleep(700);
  await p.locator('[data-testid="branch-row-feature/cart"]').hover(); await sleep(300);
  await shot(p, '13-branch-row-actions');
  await p.keyboard.press('Escape'); await sleep(200);
  await p.evaluate(() => (window).__nxWs?.getState().openCompare('feature/cart')); await sleep(2500);
  await shot(p, '14-compare');
  await p.getByTestId('history-btn').click(); await sleep(1500);
  await shot(p, '15-history');
  await p.keyboard.press('Escape');
  await p.goto(`${BASE}/p/${SHOP}`, { waitUntil: 'networkidle' }); await sleep(1500);
  await p.getByText('Chats', { exact: true }).click(); await sleep(800);
  await shot(p, '16-topics');
  await p.goto(`${BASE}/p/${CHILD}`, { waitUntil: 'networkidle' }); await sleep(1500);
  await p.getByTestId('crumb-project').click(); await sleep(700);
  await shot(p, '17-subproject-breadcrumb');
  await p.keyboard.press('Escape');
  await p.goto(`${BASE}/p/nxeon`, { waitUntil: 'networkidle' }); await sleep(1500);
  await p.getByTestId('crumb-project').click(); await sleep(700);
  await shot(p, '18-parent-crumb');
  await p.close();
}
if (want('merge')) {
  const p = await ctxPage();
  await p.goto(`${BASE}/p/${SHOP}?branch=dark-mode`, { waitUntil: 'networkidle' }); await sleep(1500);
  await p.getByTestId('branch-chip').click(); await sleep(700);
  await p.locator('[data-testid="branch-row-dark-mode"]').hover(); await sleep(200);
  await p.locator('[data-testid="branch-row-dark-mode"]').locator('..').getByLabel('Merge into main').click(); await sleep(500);
  await shot(p, '20-merge-modal');
  await p.getByTestId('merge-confirm').click(); await sleep(2000);
  await shot(p, '21-merge-conflict');
  await p.close();
}
if (want('mobile')) {
  const p = await ctxPage({ width: 390, height: 844 }, true);
  await p.goto(`${BASE}/p/${SHOP}?branch=feature%2Fcart`, { waitUntil: 'networkidle' }); await sleep(1800);
  await shot(p, '30-mobile-workspace');
  await p.getByTestId('branch-chip').click(); await sleep(700);
  await shot(p, '31-mobile-branches');
  await p.keyboard.press('Escape');
  await p.getByTestId('history-btn').click(); await sleep(1200);
  await shot(p, '32-mobile-history');
  await p.keyboard.press('Escape');
  await p.getByText('Files', { exact: true }).click(); await sleep(400);
  await p.goto(`${BASE}/`, { waitUntil: 'networkidle' }); await sleep(2500);
  await shot(p, '33-mobile-nexus');
  await p.close();
}
await browser.close();
console.log('problems:', problems.length, problems.slice(0, 10));
EOF
