async function page(viewport, mobile) {
  const ctx = await browser.newContext({ viewport, ...(mobile ? { isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : {}) });
  const p = await ctx.newPage();
  p.on('pageerror', (e) => problems.push('PAGEERROR ' + e.message));
  p.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('401')) problems.push('console ' + m.text().slice(0, 200)); });
  p.on('request', (r) => { const u = new URL(r.url()); if (u.hostname !== 'workspace.trynxeon.com' && !['data:', 'blob:'].includes(u.protocol)) problems.push('EXTERNAL ' + r.url()); });
