  const s2 = await p.evaluate(() => window.__nxProbe?.());
  if (s2?.branch) { await p.mouse.move(s2.branch.x, s2.branch.y, { steps: 5 }); await sleep(800); await shot(p, '03-nexus-branch-card'); }
  const s3 = await p.evaluate(() => window.__nxProbe?.());
  if (s3?.sub) { await p.mouse.move(s3.sub.x, s3.sub.y, { steps: 5 }); await sleep(800); await shot(p, '04-nexus-sub-card'); } }
await p.mouse.move(30, 400); await p.keyboard.press('s'); await sleep(1500); await shot(p, '05-nexus-toggle-on');
await p.keyboard.press('s'); await sleep(300);
await p.goto(BASE + '/p/qa-branches-lab?branch=qa-other', { waitUntil: 'networkidle' }); await sleep(1800);
await p.getByTestId('branch-chip').click(); await sleep(900); await shot(p, '10-branch-switcher');
