await p.goto(BASE + '/p/qa-child', { waitUntil: 'networkidle' }); await sleep(1500); await shot(p, '15-child-breadcrumb');
await p.goto(BASE + '/p/goonies-fanpage', { waitUntil: 'networkidle' }); await sleep(3500); await shot(p, '16-goonies-ok');
await p.getByTestId('history-btn').click(); await sleep(1200); await shot(p, '17-goonies-history'); await p.keyboard.press('Escape');
await p.close();
p = await page({ width: 390, height: 844 }, true);
await p.goto(BASE + '/p/qa-branches-lab?branch=qa-other', { waitUntil: 'networkidle' }); await sleep(1800); await shot(p, '20-mobile-branch');
await p.getByTestId('branch-chip').click(); await sleep(700); await shot(p, '21-mobile-switcher');
await browser.close();
console.log('problems', problems);
